// FIFO buffer pointers
reg [3:0] wr_ptr;
reg [3:0] rd_ptr;

// FIFO buffer status flags
wire fifo_almost_full;
wire fifo_almost_empty;

// Initialize FIFO buffer pointers
initial begin
    wr_ptr = 4'b0000;
    rd_ptr = 4'b0000;
    fifo_full = 1'b0;
    fifo_empty = 1'b1;
end

