    end
end

// Read data from the FIFO buffer
always @(posedge clk) begin
    if (reset) begin
        rd_ptr <= 4'b0000;
        fifo_empty <= 1'b1;
    end else if (rd_en && !fifo_empty) begin
        data_out <= fifo_mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == 4'b1111) begin
            fifo_empty <= 1'b1;
        end
        fifo_full <= 1'b0; // Set fifo_full to false after read
    end
end

// FIFO buffer status logic
