module vga_cdma_control(
input wire clk,
input wire active,
input wire [9:0] x_addr_r,
input wire [9:0] y_addr_r,
input wire [9:0] x_addr_w,
input wire [9:0] y_addr_w,
input wire [23:0] rgb888_in,
output reg [23:0] rgb888_out,
input wire aclk,
output reg [5:0] m_axi_lite_araddr,
input wire m_axi_lite_arready,
output reg m_axi_lite_arvalid,
output reg [5:0] m_axi_lite_awaddr,
input wire m_axi_lite_awready,
output reg m_axi_lite_awvalid,
input wire [31:0] m_axi_lite_rdata,
output reg m_axi_lite_rready,
input wire m_axi_lite_rvalid,
output reg [31:0] m_axi_lite_wdata,
input wire m_axi_lite_wready,
output reg m_axi_lite_wvalid,
output reg s_axi_rready,
input wire s_axi_rvalid,
input wire [31:0] s_axi_rdata,
input wire s_axi_wready,
output reg s_axi_wvalid,
output reg [31:0] s_axi_wdata
);
reg [1:0] state = 2'b00;
reg last_clk = 1'b1;
reg [23:0] rgb;
  always @(posedge aclk) begin
    if(s_axi_wready == 1'b1) begin
      s_axi_wvalid <= 1'b0;
    end
    if(s_axi_rvalid == 1'b1) begin
      // read data
      rgb <= s_axi_rdata[23:0];
      s_axi_rready <= 1'b0;
    end
    if(state == 2'b00) begin
      m_axi_lite_arvalid <= 1'b0;
      m_axi_lite_awvalid <= 1'b0;
      m_axi_lite_rready <= 1'b0;
      m_axi_lite_wvalid <= 1'b0;
      if(last_clk == 1'b0 && clk == 1'b1 && active == 1'b1) begin
        // latch on rising clock
        rgb888_out <= rgb;
        state <= 2'b01;
      end
    end
    else if(state == 2'b01) begin
      if(m_axi_lite_arready == 1'b1 || m_axi_lite_rvalid == 1'b1) begin
        if(m_axi_lite_arready == 1'b1) begin
          m_axi_lite_arvalid <= 1'b0;
        end
        if(m_axi_lite_rvalid == 1'b1) begin
          m_axi_lite_rready <= 1'b0;
          if(m_axi_lite_rdata[1] == 1'b1) begin
            // CDMASR.idle = 1
            state <= 2'b10;
          end
        end
      end
      else begin
        // select CDMASR register for read    
        m_axi_lite_arvalid <= 1'b1;
        m_axi_lite_araddr <= 6'b000100;
        // x"04"
        m_axi_lite_rready <= 1'b1;
      end
    end
    else if(state == 2'b10) begin
      if(m_axi_lite_awready == 1'b1 && m_axi_lite_wready == 1'b1) begin
        m_axi_lite_awvalid <= 1'b0;
        m_axi_lite_wvalid <= 1'b0;
        s_axi_rready <= 1'b1;
        state <= 2'b11;
      end
      else begin
        // select source address
        m_axi_lite_awvalid <= 1'b1;
        m_axi_lite_awaddr <= 6'b011000;
        // x"18"
        m_axi_lite_wvalid <= 1'b1;
        m_axi_lite_wdata[9:0] <= x_addr_r;
        m_axi_lite_wdata[19:10] <= y_addr_r;
        m_axi_lite_wdata[31:20] <= {12{1'b0}};
      end
    end
    else if(state == 2'b11) begin
      if(m_axi_lite_awready == 1'b1 && m_axi_lite_wready == 1'b1) begin
        m_axi_lite_awvalid <= 1'b0;
        m_axi_lite_wvalid <= 1'b0;
        s_axi_wvalid <= 1'b1;
        s_axi_wdata[23:0] <= rgb888_in;
        state <= 2'b00;
      end
      else begin
        // select destination address
        m_axi_lite_awvalid <= 1'b1;
        m_axi_lite_awaddr <= 6'b100000;
        // x"20"
        m_axi_lite_wvalid <= 1'b1;
        m_axi_lite_wdata[9:0] <= x_addr_w;
        m_axi_lite_wdata[19:10] <= y_addr_w;
        m_axi_lite_wdata[31:20] <= {12{1'b0}};
      end
    end
    last_clk <= clk;
  end
endmodule

