module MultBcd_1Dig(
input wire [3:0] a_bcd_1dig,
input wire [3:0] b_bcd_1dig,
input wire [3:0] cin_bcd_1dig,
output reg [3:0] z_bcd_1dig,
output reg [3:0] cout_bcd_1dig
);
reg [7:0] signal_out_1dig = 1'b0;
reg [7:0] signal_out_1dig_aux = 1'b0;
reg [3:0] cout_bcd_1dig_aux = 1'b0;
  always @(a_bcd_1dig, b_bcd_1dig, cin_bcd_1dig, signal_out_1dig, signal_out_1dig_aux, cout_bcd_1dig_aux) begin
    // Exemplo A = "0000 0111" B = "0000 0111" --< Saida = 1001 Cout = 0100
    signal_out_1dig <= (a_bcd_1dig * b_bcd_1dig) + cin_bcd_1dig;
    // Prod = (A * B) + Cin
    if(((signal_out_1dig >= 8'b00000000) && (signal_out_1dig < 8'b00001010))) begin
      // Entre 0 e 9?
      cout_bcd_1dig_aux <= 4'b0000;
      signal_out_1dig_aux <= signal_out_1dig;
    end
    else if(((signal_out_1dig >= 8'b00001010) && (signal_out_1dig < 8'b00010100))) begin
      // Entre 10 e 19?
      cout_bcd_1dig_aux <= 4'b0001;
      signal_out_1dig_aux <= signal_out_1dig - 8'b00001010;
    end
    else if(((signal_out_1dig >= 8'b00010100) && (signal_out_1dig < 8'b00011110))) begin
      cout_bcd_1dig_aux <= 4'b0010;
      signal_out_1dig_aux <= signal_out_1dig - 8'b00010100;
    end
    else if(((signal_out_1dig >= 8'b00011110) && (signal_out_1dig < 8'b00101000))) begin
      cout_bcd_1dig_aux <= 4'b0011;
      signal_out_1dig_aux <= signal_out_1dig - 8'b00011110;
    end
    else if(((signal_out_1dig >= 8'b00101000) && (signal_out_1dig < 8'b00110010))) begin
      cout_bcd_1dig_aux <= 4'b0100;
      signal_out_1dig_aux <= signal_out_1dig - 8'b00101000;
    end
    else if(((signal_out_1dig >= 8'b00110010) && (signal_out_1dig < 8'b00111100))) begin
      cout_bcd_1dig_aux <= 4'b0101;
      signal_out_1dig_aux <= signal_out_1dig - 8'b00110010;
    end
    else if(((signal_out_1dig >= 8'b00111100) && (signal_out_1dig < 8'b01000110))) begin
      cout_bcd_1dig_aux <= 4'b0110;
      signal_out_1dig_aux <= signal_out_1dig - 8'b00111100;
    end
    else if(((signal_out_1dig >= 8'b01000110) && (signal_out_1dig < 8'b01010000))) begin
      cout_bcd_1dig_aux <= 4'b0111;
      signal_out_1dig_aux <= signal_out_1dig - 8'b01000110;
    end
    else if(((signal_out_1dig >= 8'b01010000) && (signal_out_1dig < 8'b01011010))) begin
      cout_bcd_1dig_aux <= 4'b1000;
      signal_out_1dig_aux <= signal_out_1dig - 8'b01010000;
    end
    else begin
      cout_bcd_1dig_aux <= 4'b1001;
      signal_out_1dig_aux <= signal_out_1dig - 8'b01011010;
    end
    z_bcd_1dig <= signal_out_1dig_aux[3:0];
    cout_bcd_1dig <= cout_bcd_1dig_aux;
  end
endmodule

