module zero(
input wire [31:0] input_a,
input wire [31:0] input_b,
input wire [4:0] optype,
output reg result
);
  always @(input_a, input_b, optype) begin
    case(optype)
    5'b10110 : begin
      // beq
      if((input_a) == (input_b)) begin
        result <= 1'b1;
      end
      else begin
        result <= 1'b0;
      end
    end
    5'b10111 : begin
      // bne
      if((input_a) == (input_b)) begin
        result <= 1'b0;
      end
      else begin
        result <= 1'b1;
      end
    end
    5'b11000 : begin
      // j
      result <= 1'b1;
    end
    5'b11001 : begin
      // jr
      result <= 1'b1;
    end
    5'b11010 : begin
      // jal
      result <= 1'b1;
    end
    default : begin
      result <= 1'b0;
    end
    endcase
  end
endmodule

module alu(
input wire [31:0] a,
input wire [31:0] b,
input wire [2:0] alucontrol,
output reg [31:0] result,
output reg zero
);
  always @(a, b, alucontrol) begin : P1
    reg [31:0] temp;
    case(alucontrol)
    3'b000 : begin
      temp = a & b;
    end
    3'b001 : begin
      temp = a | b;
    end
    3'b010 : begin
      temp = a + b;
    end
    3'b011 : begin
      temp = 32'h00000000;
      //preguntar
    end
    3'b100 : begin
      temp = a &  ~(b);
    end
    3'b101 : begin
      temp = a |  ~(b);
    end
    3'b110 : begin
      temp = a - b;
    end
    3'b111 : begin
      if((a < b)) begin
        temp = {1{1'b1}};
      end
      else if((a > b)) begin
        temp = {1{1'b0}};
      end
    end
    default : begin
      temp = 32'h00000000;
    end
    endcase
    if((temp == 32'h00000000)) begin
      zero <= 1'b1;
    end
    else begin
      zero <= 1'b0;
    end
    result <= temp;
  end
endmodule

