module IFetch(
input wire clock,
input wire reset,
input wire condition_flag_from_EX,
input wire [31:0] PC_new_addr_from_EX,
input wire [31:0] instruction_from_iROM,
output wire [22:0] addr_to_iROM,
output wire [31:0] instruction_to_ID
);
////Components\\--
//\\Components//--
////Signals\\--
//Signals that have to do with the program counter
reg [22:0] PC_addr_to_load;
wire [22:0] incremented_addr;
wire [22:0] PC_out;  //Signals that carry the outputs of the two 16-bit instruction
//registers
wire [31:0] instruction;  //\\Signals//--
  //This process gives the program counter either an incremented
  //address, or an alternate address to jump to
  always @(PC_new_addr_from_EX, incremented_addr, condition_flag_from_EX) begin
    if(condition_flag_from_EX == 1'b1) begin
      PC_addr_to_load <= PC_new_addr_from_EX[22:0];
    end
    else begin
      PC_addr_to_load <= incremented_addr;
    end
  end
  GenReg #(
  23)
  PC(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(PC_addr_to_load),
    .output(PC_out));
  GenRegFalling #(
  32)
  Inst_reg(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(instruction_from_iROM),
    .output(instruction));
  //The address that goes out to the flash
  assign addr_to_iROM = PC_out;
  //Send both halves of the instruction to the instruction decoder
  assign instruction_to_ID = instruction;
  //This generates the incremented address for the program counter
  assign incremented_addr = PC_out + 23'b00000000000000000000001;
endmodule

module RGB_2_Y(
input wire rst,
