output wire [31:0] OUTPUT_1
);
parameter s_rgb_30 = 12'b001001100100;
parameter s_rgb_59 = 12'b010010110010;
parameter s_rgb_11 = 12'b000011101001;
wire [7:0] INPUT_R;
wire [7:0] INPUT_G;
wire [7:0] INPUT_B;
reg [7:0] INPUT_Y;
reg [19:0] s_rgb_out_y = 1'b0;
reg [19:0] rgb_in_r_reg_Y = 1'b0;
reg [19:0] rgb_in_g_reg_Y = 1'b0;
reg [19:0] rgb_in_b_reg_Y = 1'b0;
  assign INPUT_R = INPUT_1[7:0];
  assign INPUT_G = INPUT_1[15:8];
  assign INPUT_B = INPUT_1[23:16];
  assign OUTPUT_1 = {24'b000000000000000000000000,INPUT_Y};
  always @(INPUT_R, INPUT_G, INPUT_B) begin
    rgb_in_r_reg_Y <= s_rgb_30 * (INPUT_R);
    rgb_in_g_reg_Y <= s_rgb_59 * (INPUT_G);
    rgb_in_b_reg_Y <= s_rgb_11 * (INPUT_B);
    s_rgb_out_y <= rgb_in_r_reg_Y + (rgb_in_g_reg_Y + rgb_in_b_reg_Y);
    INPUT_Y <= s_rgb_out_y[19:12];
  end
endmodule

module brake_anim(
input wire clk,
input wire reset,
input wire en,
output reg [1:0] led_out
);
parameter [0:0]
  s0 = 0,
  s1 = 1;
reg s;
  always @(posedge clk, posedge reset, posedge s, posedge en) begin : P1
    reg [31:0] i = 0;
    if((reset == 1'b1) || (en == 1'b0)) begin
      s <= s0;
      led_out <= 2'b00;
    end
    else begin
      case(s)
      s0 : begin
        i = i + 1;
        led_out <= 2'b00;
        if((i == 2000000)) begin
          i = 0;
          s <= s1;
        end
      end
      s1 : begin
        i = i + 1;
        led_out <= 2'b11;
        if((i == 2000000)) begin
          i = 0;
          s <= s0;
        end
      end
      endcase
    end
  end
endmodule

