module demux1_4(
input wire [3:0] we,
input wire [1:0] adr,
input wire oe,
output reg [3:0] Y0,
output reg [3:0] Y1,
output reg [3:0] Y2,
output reg [3:0] Y3
);
// wejscia
// wyjscia
  always @(oe, adr) begin
    //gdy '1' na wejsciu oe, demltiplexera
    // we zostaje przepisane na Yx w zaleznosci 
    // od wejscia adresowego
    // '0' wygasza w 4 segmenty
    if(oe == 1'b1) begin
      if(adr == 2'b00) begin
        Y0 <= we;
        Y1 <= 4'b1111;
        Y2 <= 4'b1111;
        Y3 <= 4'b1111;
      end
      else if(adr == 2'b01) begin
        Y0 <= 4'b1111;
        Y1 <= we;
        Y2 <= 4'b1111;
        Y3 <= 4'b1111;
      end
      else if(adr == 2'b10) begin
        Y0 <= 4'b1111;
        Y1 <= 4'b1111;
        Y2 <= we;
        Y3 <= 4'b1111;
      end
      else if(adr == 2'b11) begin
        Y0 <= 4'b1111;
        Y1 <= 4'b1111;
        Y2 <= 4'b1111;
        Y3 <= we;
      end
    end
    else if(oe == 1'b0) begin
      Y0 <= 4'b1111;
      Y1 <= 4'b1111;
      Y2 <= 4'b1111;
      Y3 <= 4'b1111;
    end
  end
endmodule

module dig_peripherals_demo(
input wire clk,
output wire [7:0] leds_out,
output wire [6:0] seg_out,
output wire dp_out,
output wire [3:0] an_out,
input wire [7:0] sw_in,
input wire [3:0] btn_in,
input wire miso,
output wire mosi,
output wire sclk,
output wire ss
);
// PMOD SD
// declaration of KCPSM3
//
//----------------------------------------------------------------------------------
//
// Signals used to connect KCPSM3 to program ROM and I/O logic
//
wire [9:0] address;
wire [17:0] instruction;
wire [7:0] port_id;
wire [7:0] out_port;
reg [7:0] in_port;
wire write_strobe;
wire read_strobe;
wire interrupt;
wire interrupt_ack;
wire port_display;
wire port_display_wlsb;
wire port_display_wmsb;  // SPI port signals
wire port_spi_enable;
wire port_spi_op;  // select config/status or data io
// Input ports multiplexer
wire [7:0] port_switches;
wire [7:0] port_buttons;
wire [7:0] port_spi;
  kcpsm3 u_processor(
      .address(address),
    .instruction(instruction),
    .port_id(port_id),
    .write_strobe(write_strobe),
    .out_port(out_port),
    .read_strobe(read_strobe),
    .in_port(in_port),
    .interrupt(interrupt),
    .interrupt_ack(interrupt_ack),
    .reset(1'b0),
    .clk(clk));
  asmcode u_asmcode(
      .address(address),
    .instruction(instruction),
    .clk(clk));
  //------------------------------------------
  // Picoblaze out ports 
  // Leds connected to port 4
  port_leds_dig u_leds(
      .w(write_strobe),
    .enable(port_id[2]),
    .clk(clk),
    .port_in(out_port),
    .leds_out(leds_out));
  // Display needs two ports: LSB and MSB digit. Port 8  and 16
  assign port_display = port_id[3] | port_id[4];
  assign port_display_wlsb = port_id[3] & write_strobe;
  assign port_display_wmsb = port_id[4] & write_strobe;
  port_display_dig u_display(
      .clk(clk),
    .enable(port_display),
    .digit_in(out_port),
    .w_msb(port_display_wmsb),
    .w_lsb(port_display_wlsb),
    .seg_out(seg_out),
    .dp_out(dp_out),
    .an_out(an_out));
  //--------------------------------------
  // Picoblaze input ports
  always @(*) begin
    case(port_id[1:0])
      2'b00 : in_port <= port_switches;
      2'b11 : in_port <= port_buttons;
      default : in_port <= port_spi;
    endcase
  end
  // Switches connected to input port 0
  port_switches_dig u_switches(
      .r(read_strobe),
    .clk(clk),
    .enable(1'b1),
    .port_out(port_switches),
    .switches_in(sw_in));
  // Buttons on input port 3
  port_buttons_dig u_buttons(
      .r(read_strobe),
    .clk(clk),
    .enable(1'b1),
    .port_out(port_buttons),
    .buttons_in(btn_in));
  // SPI component for PMOD SD
  // Two ports are used: config (at port 1) and data (at port 2)
  assign port_spi_enable = port_id[0] | port_id[1];
  // data/conf selector
  assign port_spi_op = port_id[1];
  // Write mode
  port_spi_dig u_spi(
      .clk(clk),
    .data_in(out_port),
    .data_out(port_spi),
    .enable(port_spi_enable),
    .rw(write_strobe),
    .cfst_data(port_spi_op),
    .miso(miso),
    .mosi(mosi),
    .sclk(sclk),
    .ss(ss));
endmodule

