module EPROC_OUT4_ENC8b10b(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
output wire getDataTrig,
input wire [9:0] edataIN,
input wire edataINrdy,
output wire [3:0] EdataOUT
);
// ready on every bitCLK
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
parameter zeros4bit = 4'b0000;
wire [9:0] enc10bit; reg [9:0] enc10bit0; reg [9:0] enc10bit1;
reg [19:0] enc10bit_x2_r = 1'b0;
reg [2:0] request_cycle_cnt = 1'b0; reg [2:0] send_count = 1'b0;
reg send_out_trig = 1'b0; reg word_cnt = 1'b0;
wire inp_request_trig; wire inp_request_trig_out; wire enc10bitRdy;
  //-----------------------------------------------------------------------------------------
  // input handshaking, request cycle 5 CLKs, request is 2 clks wide, 2 bytes at a time
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(rst == 1'b1) begin
      request_cycle_cnt <= {3{1'b0}};
    end
    else begin
      if(inp_request_trig == 1'b1) begin
        // meaning request_cycle_cnt = "100"
        request_cycle_cnt <= {3{1'b0}};
      end
      else begin
        request_cycle_cnt <= request_cycle_cnt + 1;
      end
    end
  end
  //
  assign inp_request_trig = (request_cycle_cnt == 3'b100) ? 1'b1 : 1'b0;
  //
  pulse_pdxx_pwxx #(
      .pd(0),
    .pw(2))
  inp_reques1clk(
      bitCLKx4,
    inp_request_trig,
    inp_request_trig_out);
  assign getDataTrig = inp_request_trig_out;
  //
  always @(posedge bitCLK) begin
    send_out_trig <= inp_request_trig;
    // slow clock output trigger
  end
  //
  //-----------------------------------------------------------------------------------------
  // 8b10b encoding
  //-----------------------------------------------------------------------------------------
  enc8b10_wrap enc8b10bx(
      .clk(bitCLKx4),
    .rst(rst),
    .dataCode(edataIN[9:8]),
    // 00"data, 01"eop, 10"sop, 11"comma
    .dataIN(edataIN[7:0]),
    .dataINrdy(edataINrdy),
    // one? CLKx4 after inp_request_trig_out
    .encDataOut(enc10bit),
    .encDataOutrdy(enc10bitRdy));
  //-----------------------------------------------------------------------------------------
  // sending out 4 bits @ bitCLK
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLKx4) begin
    if(enc10bitRdy == 1'b1) begin
      word_cnt <=  ~word_cnt;
    end
    else begin
      word_cnt <= 1'b0;
    end
  end
  //
  always @(posedge bitCLKx4) begin
    if(enc10bitRdy == 1'b1) begin
      if(word_cnt == 1'b0) begin
        enc10bit0 <= enc10bit;
      end
      else begin
        enc10bit1 <= enc10bit;
      end
    end
  end
  //
  //-----------------------------------------------------------------------------------------
  // slow clock logic
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(send_out_trig == 1'b1) begin
      send_count <= {3{1'b0}};
    end
    else begin
      send_count <= send_count + 1;
    end
  end
  //
  always @(posedge bitCLK) begin
    if(rst == 1'b1) begin
      enc10bit_x2_r <= {20{1'b0}};
    end
    else if(send_out_trig == 1'b1) begin
      enc10bit_x2_r <= {enc10bit1,enc10bit0};
    end
  end
  //
  MUX8_Nbit #(
      .N(4))
  outmux(
      .data0(enc10bit_x2_r[3:0]),
    .data1(enc10bit_x2_r[7:4]),
    .data2(enc10bit_x2_r[11:8]),
    .data3(enc10bit_x2_r[15:12]),
    .data4(enc10bit_x2_r[19:16]),
    .data5(zeros4bit),
    .data6(zeros4bit),
    .data7(zeros4bit),
    .sel(send_count),
    .data_out(EdataOUT));
    //
endmodule

