module debouncer(
input wire clk_i,
input wire reset_i,
input wire btn_i,
output reg deb_o
);
parameter [31:0] counter_size=100;
//input clock
//input reset
//input signal to be debounced
//debounced signal
reg [1:0] ff = 1'b0;  //input flip flops and initialize
wire counter_reset;  //sync reset to zero
reg [31:0] counter = 0;  //counter output
  assign counter_reset = ff[0] ^ ff[1];
  //determine when to start/reset counter
  always @(posedge clk_i, posedge reset_i) begin
    if(reset_i == 1'b1) begin
      counter <= 0;
      ff <= {2{1'b0}};
      counter <= 0;
    end else begin
      ff[1] <= ff[0];
      ff[0] <= btn_i;
      if((counter_reset == 1'b1)) begin
        //reset counter because input is changing
        counter <= 0;
      end
      else if((counter < counter_size)) begin
        //stable input time is not yet met
        counter <= counter + 1;
      end
      else begin
        //stable input time is met
        deb_o <= ff[1];
      end
    end
  end
endmodule

module i2s_serializer(
input wire clock,
input wire reset,
output reg i2s_out,
input wire i2s_in,
output reg i2s_bclk,
output reg i2s_fs,
output reg sample_pulse,
output reg [23:0] left_sample_out,
output reg [23:0] right_sample_out,
input wire [23:0] left_sample_in,
input wire [23:0] right_sample_in
);
// equals i2s_mclk
reg [7:0] bit_count;
reg [31:0] shift_reg = 1'b0;
  // mclk = 256*fs. bclk = 64*fs (32 bits per channel)
  always @(posedge clock) begin
    bit_count <= bit_count + 1;
    i2s_bclk <= bit_count[1];
    i2s_fs <= bit_count[7];
    sample_pulse <= 1'b0;
    if(bit_count[1:0] == 2'b00) begin
      i2s_out <= shift_reg[(31)];
    end
    else if(bit_count[1:0] == 2'b10) begin
      shift_reg <= {shift_reg[(31) - 1:0],i2s_in};
    end
    case(bit_count)
    8'h7E : begin
      left_sample_out <= shift_reg[(31) - 2:(31) - 25];
    end
    8'hFE : begin
      right_sample_out <= shift_reg[(31) - 2:(31) - 25];
      sample_pulse <= 1'b1;
    end
    8'h02 : begin
      shift_reg <= {left_sample_in,7'b0000000,i2s_in};
    end
    8'h82 : begin
      shift_reg <= {right_sample_in,7'b0000000,i2s_in};
    end
    default : begin
    end
    endcase
    if(reset == 1'b1) begin
      bit_count <= {8{1'b1}};
      i2s_out <= 1'b0;
      left_sample_out <= {24{1'b0}};
      right_sample_out <= {24{1'b0}};
    end
  end
endmodule

