module m_calc(
input wire clk,
input wire reset,
input wire [15:0] ab,
input wire [15:0] t,
input wire [15:0] n_cons,
output reg [15:0] m,
input wire mult_valid,
output reg m_valid
);
// indica que los datos de entrada son validos
// la m calculada es valida
reg [15:0] sum_res; reg [15:0] next_sum_res;
reg mult_valid_1; reg mult_valid_2;  //delay del valido a lo largo del calculo
wire [31:0] mult;
  assign mult = sum_res * n_cons;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      sum_res <= {16{1'b0}};
      mult_valid_1 <= 1'b0;
      mult_valid_2 <= 1'b0;
    end
    else begin
      sum_res <= next_sum_res;
      mult_valid_1 <= mult_valid;
      mult_valid_2 <= mult_valid_1;
    end
  end
  always @(ab, t, mult_valid_2) begin
    m <= mult[15:0];
    next_sum_res <= ab + t;
    m_valid <= mult_valid_2;
  end
endmodule

