  always @(posedge reset, posedge entrada) begin
    if((reset == 1'b1)) begin
      temporal <= 1'b0;
      contador <= 0;
    end else begin
      if((contador == 124999)) begin
        temporal <=  ~(temporal);
        contador <= 0;
      end
      else begin
        contador <= contador + 1;
