module sampler(
input wire [31:0] input,
input wire clock,
input wire exClock,
input wire external,
input wire [23:0] data,
input wire wrDivider,
output reg [31:0] sample,
output reg ready,
output reg ready50
);
// 32 input channels
// internal clock
// external clock
// clock selection
// configuration data
// write divider register
// sampled data
// new sample ready
// low rate sample signal with 50% duty cycle
reg [23:0] divider; reg [23:0] counter;
reg lastExClock; reg syncExClock;
  // sample data
  always @(posedge clock) begin
    syncExClock <= exClock;
    if(wrDivider == 1'b1) begin
      divider <= data[23:0];
      counter <= {24{1'b0}};
      ready <= 1'b0;
    end
    else if(external == 1'b1) begin
      if(syncExClock == 1'b0 && lastExClock == 1'b1) begin
        //					sample <= input(31 downto 10) & exClock & lastExClock & input(7 downto 0);
        ready <= 1'b1;
      end
      else begin
        sample <= input;
        ready <= 1'b0;
      end
      lastExClock <= syncExClock;
    end
    else if(counter == divider) begin
      sample <= input;
      counter <= {24{1'b0}};
      ready <= 1'b1;
    end
    else begin
      counter <= counter + 1;
      ready <= 1'b0;
    end
  end
  // generate ready50 50% duty cycle sample signal
  always @(posedge clock) begin
    if(counter == divider) begin
      ready50 <= 1'b1;
    end
    else if(counter[22:0] == divider[23:1]) begin
      ready50 <= 1'b0;
    end
  end
endmodule

module guardaifft(
input wire reset,
input wire clk,
input wire dv,
input wire cpv,
input wire edone,
input wire [6:0] xk_index,
output reg we,
input wire [15:0] xk_re,
input wire [15:0] xk_im,
output reg EnableTxserie,
output wire [31:0] dato_out,
output wire [8:0] addresout
);
parameter [1:0]
  reposo = 0,
  inicio = 1,
  fin = 2;
reg [1:0] estado_actual; reg [1:0] estado_nuevo;
reg [8:0] dir_actual; reg [8:0] dir_nueva;
  always @(posedge reset, posedge clk) begin
    if((reset == 1'b1)) begin
      estado_actual <= reposo;
      dir_actual <= {9{1'b0}};
    end else begin
      dir_actual <= dir_nueva;
      estado_actual <= estado_nuevo;
    end
  end
  assign addresout = dir_actual;
  assign dato_out = {xk_re,xk_im};
  always @(estado_actual, dir_actual, dv, cpv, xk_index, edone) begin
    we <= dv;
    dir_nueva <= dir_actual;
    EnableTxserie <= 1'b0;
    case(estado_actual)
    reposo : begin
      if((dv == 1'b1)) begin
        estado_nuevo <= inicio;
        dir_nueva <= dir_actual + 1;
      end
      else begin
        estado_nuevo <= reposo;
      end
    end
    inicio : begin
      if((dv == 1'b1)) begin
        dir_nueva <= dir_actual + 1;
        estado_nuevo <= inicio;
      end
      else begin
        estado_nuevo <= fin;
      end
    end
    fin : begin
      EnableTXserie <= 1'b1;
      estado_nuevo <= reposo;
    end
    endcase
  end
endmodule

module GreenDroidASR64Core(
input wire [31:0] i00,
input wire [31:0] i01,
input wire [31:0] i02,
input wire [31:0] i03,
output reg [31:0] r00,
output reg [31:0] r01,
output reg [31:0] r02,
output reg [31:0] r03,
input wire [31:0] FP,
output reg [31:0] FPout,
output reg [31:0] M_ADDR,
inout reg [31:0] M_DATA,
inout reg M_RD,
inout reg M_WR,
input wire M_RDY,
input wire reset,
input wire CLK
);
parameter [2:0]
  ST_INIT = 0,
  WS_INIT = 1,
  ST_RESET = 2,
  ST00 = 3,
  WS00 = 4,
  ST01 = 5,
  WS01 = 6,
  ST_END = 7;
reg [2:0] Mstate;
  // CONTROL PROCESS --------
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      Mstate <= ST_RESET;
    end else begin
      case(Mstate)
      ST_RESET : begin
        Mstate <= ST_INIT;
      end
      ST_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
        else begin
          Mstate <= WS_INIT;
        end
      end
      WS_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
      end
      ST00 : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST01;
        end
        else begin
          Mstate <= WS00;
        end
      end
      WS00 : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST01;
        end
      end
      ST01,WS01,ST_END : begin
      end
      default : begin
      end
      endcase
    end
  end
  // EXECUTE PROCESS --------
  always @(posedge clk, posedge reset) begin : P1
    reg [31:0] T, s0, s1, s2, s3, s4, s5, s6, s7, fpi;
    if((reset == 1'b1)) begin
      // reset any internal states -- 
      s0 = {1{1'b0}};
      s1 = {1{1'b0}};
      s2 = {1{1'b0}};
      s3 = {1{1'b0}};
      s4 = {1{1'b0}};
      s5 = {1{1'b0}};
      s6 = {1{1'b0}};
      s7 = {1{1'b0}};
      fpi = {1{1'b0}};
      M_ADDR <= {32{1'bZ}};
      M_DATA <= {32{1'bZ}};
      M_RD <= 1'bZ;
      M_WR <= 1'bZ;
    end else begin
      M_DATA <= 32'bZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ;
      case(Mstate)
      ST_INIT : begin
        // connect 4 input params here --
        s0 = i00;
        s1 = i01;
        s2 = i02;
        s3 = i03;
        fpi = FP;
        //lit ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s1 = s0;
        s0 = 8;
        //fp- ;
        fpi = fpi + s0;
        s0 = s1;
        s1 = s2;
        s2 = s3;
        s3 = s4;
        s4 = s5;
        s5 = s6;
        s6 = s7;
        //rsd3 ;
        T = s2;
        s2 = s1;
        s1 = s0;
        s0 = T;
      end
      ST00 : begin
        //lit ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s1 = s0;
        s0 = 63;
        //and ;
        s0 = s0 & s1;
        s1 = s2;
        s2 = s3;
        s3 = s4;
        s4 = s5;
        s5 = s6;
        s6 = s7;
        //tuck2 ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s2 = s0;
        //lit ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s1 = s0;
        s0 = 31;
        // bzp ### ignored ### ;
        // recover 4 results here --
        r00 <= s0;
        r01 <= s1;
        r02 <= s2;
        r03 <= s3;
        FPout <= fpi;
      end
      default : begin
      end
      endcase
    end
  end
endmodule

