module LFSR16(
input wire CLK,
input wire RESET,
input wire LD,
input wire EN,
input wire [0:15] DIN,
output wire [0:15] PRN,
output wire ZERO_D
);
reg [0:15] t_prn;
  // Continuous assignments :
  assign PRN = t_prn;
  assign ZERO_D = (t_prn == 16'b0000000000000000) ? 1'b1 : 1'b0;
  // LFSR process : 
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      t_prn <= 16'b0000000000000001;
      // load 1 at reset 
    end else begin
      if((LD == 1'b1)) begin
        // load a new seed when ld is active 
        t_prn <= DIN;
      end
      else if((EN == 1'b1)) begin
        // shift when enabled 
        t_prn[0] <= t_prn[15] ^ t_prn[4] ^ t_prn[2] ^ t_prn[1];
        t_prn[1:15] <= t_prn[0:14];
      end
    end
  end
endmodule

module sub_345(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

