output wire [3:0] flags_next,
output wire [1:0] flags_update
);
// 0:none 1:NZ 2:NZC 3:NZCV
wire zero; wire carry_out; wire overflow;
wire [31:0] output_mux; wire [31:0] output_mul; wire [31:0] output_shift; wire [31:0] output_add; wire [31:0] output_mvn;
wire carry_mux; wire carry_shift; wire carry_in_add; wire carry_add;
wire [1:0] shift_mode;
wire [31:0] input_add_2;
  //FIX OP CODE
  //00000 AND ok
  //00001 EOR ok
  //00010 LSL ok
  //00011 LSR ok
  //00100 ASR ok
  //00101 ADC ok, V not implemented
  //00110 SBC ok, V not implemented
  //00111 ROR ok
  //01000 TST
  //01001 NEG
  //01010 CMP ok, V not implemented, same as sub, not implemented not outputting result
  //01011 CMN ok, V not implemented, same as add, not implemented not outputting result
  //01100 ORR ok
  //01101 MUL ok
  //01110 BIC ok
  //01111 MVN ok
  //10000 MOV ok
  //10001 ADD ok, V not implemented
  //10010 SUB ok, V not implemented
  mul32 mul_block(
      .a(input_1),
    .b(input_2),
    .p(output_mul));
  assign shift_mode = funct == 5'b00010 ? 2'b00 : funct == 5'b00011 ? 2'b01 : funct == 5'b00100 ? 2'b10 : 2'b11;
  shift shift_block(
      .mode(shift_mode),
    .shift(input_2[4:0]),
    .input(input_1),
    .carry(carry_shift),
    .output(output_shift));
  assign input_add_2 = funct == 5'b00101 || funct == 5'b10001 || funct == 5'b01011 ? input_2 : ( ~(input_2)) + 1;
  assign carry_in_add = funct == 5'b00101 || funct == 5'b00110 ? flags_current[1] : 1'b0;
  add32 add_block(
      .a(input_1),
    .b(input_add_2),
    .cin(carry_in_add),
    .sum(output_add),
    .cout(carry_add));
  assign output_mvn =  ~(input_1);
  assign output_mux = funct == 5'b00000 ? input_1 & input_2 : funct == 5'b00001 ? input_1 ^ input_2 : funct == 5'b01100 ? input_1 | input_2 : funct == 5'b01110 ? input_1 &  ~(input_2) : funct == 5'b01101 ? output_mul : funct == 5'b00010 || funct == 5'b00011 || funct == 5'b00100 || funct == 5'b00111 ? output_shift : funct == 5'b00101 || funct == 5'b10001 || funct == 5'b00110 || funct == 5'b10010 || funct == 5'b01011 || funct == 5'b01010 ? output_add : funct == 5'b01111 ? output_mvn : funct == 5'b10000 ? input_1 : {32{1'b0}};
  assign output = output_mux;
  assign zero =  ~(output_mux[31] | output_mux[30] | output_mux[29] | output_mux[28] | output_mux[27] | output_mux[26] | output_mux[25] | output_mux[24] | output_mux[23] | output_mux[22] | output_mux[21] | output_mux[20] | output_mux[19] | output_mux[18] | output_mux[17] | output_mux[16] | output_mux[15] | output_mux[14] | output_mux[13] | output_mux[12] | output_mux[11] | output_mux[10] | output_mux[9] | output_mux[8] | output_mux[7] | output_mux[6] | output_mux[5] | output_mux[4] | output_mux[3] | output_mux[2] | output_mux[1] | output_mux[0]);
  assign carry_mux = funct == 5'b00010 || funct == 5'b00011 || funct == 5'b00100 || funct == 5'b00111 ? carry_shift : funct == 5'b00101 || funct == 5'b10001 || funct == 5'b00110 || funct == 5'b10010 || funct == 5'b01011 || funct == 5'b01010 ? carry_add : 1'b0;
  assign overflow = funct == 0'b ? 1'b1 : 1'b0;
  assign flags_next = {output_mux[31],zero,carry_mux,overflow};
  assign flags_update = funct == 5'b01101 || funct == 5'b00000 || funct == 5'b00001 || funct == 5'b01100 || funct == 5'b01110 || funct == 5'b01000 || funct == 5'b01111 || funct == 5'b10000 ? 2'b01 : funct == 5'b00010 || funct == 5'b00011 || funct == 5'b00100 || funct == 5'b00111 ? 2'b10 : funct == 5'b00101 || funct == 5'b00110 || funct == 5'b01001 || funct == 5'b01010 || funct == 5'b01011 || funct == 5'b10001 || funct == 5'b10010 ? 2'b11 : 2'b00;
endmodule

