  //-- Reset generation logic -----
  assign rst_int_wr = rst_async_rd3 | rst_s_rd;
  assign rst_int_rd = rst_async_rd3 | rst_s_rd;
  //Testbench reset synchronization
  always @(posedge clk_i, posedge RESET) begin
    if((RESET == 1'b1)) begin
      rst_async_rd1 <= 1'b1;
      rst_async_rd2 <= 1'b1;
      rst_async_rd3 <= 1'b1;
    end else begin
      rst_async_rd1 <= RESET;
      rst_async_rd2 <= rst_async_rd1;
      rst_async_rd3 <= rst_async_rd2;
    end
  end
  assign rst_s_wr3 = 1'b0;
  assign rst_s_rd = 1'b0;
  //----------------
