  fg_tb_dverif #(
      .C_DOUT_WIDTH(69),
    .C_DIN_WIDTH(69),
    .C_USE_EMBEDDED_REG(0),
    .TB_SEED(TB_SEED),
    .C_CH_TYPE(0))
  fg_dv_nv(
      .RESET(rst_int_rd),
    .RD_CLK(clk_i),
    .PRC_RD_EN(prc_re_i),
    .RD_EN(rd_en_i),
    .EMPTY(empty_i),
    .DATA_OUT(dout_i),
    .DOUT_CHK(dout_chk_i));
  fg_tb_pctrl #(
      .AXI_CHANNEL(6'bNative),
    .C_APPLICATION_TYPE(0),
    .C_DOUT_WIDTH(69),
    .C_DIN_WIDTH(69),
    .C_WR_PNTR_WIDTH(9),
    .C_RD_PNTR_WIDTH(9),
    .C_CH_TYPE(0),
    .FREEZEON_ERROR(FREEZEON_ERROR),
    .TB_SEED(TB_SEED),
    .TB_STOP_CNT(TB_STOP_CNT))
  fg_pc_nv(
      .RESET_WR(rst_int_wr),
    .RESET_RD(rst_int_rd),
    .RESET_EN(reset_en),
    .WR_CLK(clk_i),
    .RD_CLK(clk_i),
    .PRC_WR_EN(prc_we_i),
    .PRC_RD_EN(prc_re_i),
    .FULL(full_i),
    .ALMOST_FULL(almost_full_i),
    .ALMOST_EMPTY(almost_empty_i),
    .DOUT_CHK(dout_chk_i),
    .EMPTY(empty_i),
    .DATA_IN(wr_data),
    .DATA_OUT(dout),
    .SIM_DONE(SIM_DONE),
    .STATUS(STATUS));
  fifo_69x512_hf_top fg_inst(
      .CLK(clk_i),
    .RST(rst),
    .PROG_FULL(prog_full),
    .WR_EN(wr_en),
    .RD_EN(rd_en),
    .DIN(din),
    .DOUT(dout),
    .FULL(full),
    .EMPTY(empty));
endmodule

