module clockdiv(
input wire clk_i,
input wire rst,
output wire clk_o
);
parameter [31:0] DIVPARAM=5000000;
reg [31:0] count;
reg temp_q;
  always @(posedge clk_i, posedge rst) begin
    if((rst == 1'b1)) begin
      count <= 0;
      temp_q <= 1'b0;
    end else begin
      if((count == (DIVPARAM / 2 - 1))) begin
        count <= 0;
        temp_q <=  ~(temp_q);
      end
      else begin
        count <= count + 1;
      end
    end
  end
  assign clk_o = temp_q;
endmodule

