module PMAUnit(
output wire [15:0] ProgAB,
input wire [15:0] ProgDB,
input wire [1:0] PCUpdateSel,
output wire [15:0] NextPC,
input wire [11:0] PCOffset,
input wire NewIns,
output reg [15:0] IR,
input wire [15:0] NewPCZ,
input wire [15:0] NewPCS,
input wire Reset,
input wire Clk
);
// address for program memory
// data from program memory
// source of next program counter
// next program counter
// increment for program counter
// indicates new instruction should be loaded
// instruction register
// from Z register
// from stack
// reset
// system clock
reg [15:0] PC;
wire [15:0] IncrementedPC;
parameter ResetValue = 1'b0;
  assign ProgAB = PC;
  assign IncrementedPC = (PC) + (PCOffset);
  assign NextPC = IncrementedPC;
  always @(posedge Clk) begin
    if((NewIns == 1'b1)) begin
      IR <= ProgDB;
    end
    if((PCUpdateSel == 2'b00)) begin
      PC <= IncrementedPC;
    end
    else if((PCUpdateSel == 2'b01)) begin
      PC <= ProgDB;
    end
    else if((PCUpdateSel == 2'b10)) begin
      PC <= NewPCZ;
    end
    else if((PCUpdateSel == 2'b11)) begin
      PC <= NewPCS;
    end
    else begin
      PC <= {16{1'bX}};
    end
    if((Reset == 1'b0)) begin
      PC <= ResetValue;
    end
  end
endmodule

