module voiceSynth(
input wire clk,
input wire enable,
input wire [15:0] period,
output reg [7:0] sig
);
parameter clkDiv = 4;  // Nexys 2 runs at 50,000,000 Mhz..
// Sample clock at 3125000Hz.
reg [16 + clkDiv:0] counter;
  always @(posedge clk, posedge period, posedge enable) begin
    if((counter[(16 + clkDiv):clkDiv] < {1'b0,period}) && (enable == 1'b1)) begin
      counter <= (counter) + 1;
    end
    else begin
      counter <= {((16 + clkDiv)-(0)+1){1'b0}};
    end
  end
  always @(counter, period) begin
    if(counter[16 + clkDiv -: 16 + 1] > ({1'b0,period / 2})) begin
      sig <= {8{1'b1}};
    end
    else begin
      sig <= {8{1'b0}};
    end
  end
endmodule

module edgeDetector(
input wire clk,
input wire reset,
input wire enable,
input wire input,
output reg detected
);
  always @(posedge clk, posedge reset) begin : P1
    reg currentState;
    reg previousState;
      // Reset
    if(reset == 1'b1) begin
      currentState = 1'b0;
      previousState = 1'b0;
      detected <= 1'b0;
      // Synchronous behaviour
    end else begin
      if(enable == 1'b1) begin
        // Update states
        previousState = currentState;
        currentState = input;
        // If the current state is high, and the previous state was low,
        // an edge has arrived:
        detected <= currentState &  ~previousState;
      end
    end
  end
endmodule

module top_level(
input wire fx2Clk_in,
output wire fx2FifoSel_out,
inout wire [7:0] fx2Data_io,
output wire fx2Read_out,
input wire fx2GotData_in,
output wire fx2Write_out,
input wire fx2GotRoom_in,
output wire fx2PktEnd_out,
output wire ramClk_out,
output wire [2:0] ramCmd_out,
output wire [1:0] ramBank_out,
output wire [11:0] ramAddr_out,
inout wire [15:0] ramData_io,
output wire ramLDQM_out,
output wire ramUDQM_out
);
// FX2 interface -----------------------------------------------------------------------------
// 48MHz clock from FX2
// select FIFO: "0" for EP2OUT, "1" for EP6IN
// 8-bit data to/from FX2
// When EP2OUT selected:
// asserted (active-low) when reading from FX2
// asserted (active-high) when FX2 has data for us
// When EP6IN selected:
// asserted (active-low) when writing to FX2
// asserted (active-high) when FX2 has room for more data from us
// asserted (active-low) when a host read needs to be committed early
// SDRAM signals -----------------------------------------------------------------------------
// Channel read/write interface -----------------------------------------------------------------
//signal chanAddr  : std_logic_vector(6 downto 0);  -- the selected channel (0-127)
// Host >> FPGA pipe:
wire [7:0] h2fData;  // data lines used when the host writes to a channel
wire h2fValid;  // '1' means "on the next clock rising edge, please accept the data on h2fData"
wire h2fReady;  // channel logic can drive this low to say "I'm not ready for more data yet"
// Host << FPGA pipe:
wire [7:0] f2hData;  // data lines used when the host reads from a channel
wire f2hValid;  // channel logic can drive this low to say "I don't have data ready for you"
wire f2hReady;  // '1' means "on the next clock rising edge, put your next byte of data on f2hData"
// ----------------------------------------------------------------------------------------------
// Clock synthesis & reset
wire sysClk000;
wire sysClk180;
wire locked;
wire reset;
  // CommFPGA module
  comm_fpga_fx2 comm_fpga_fx2(
      .clk_in(sysClk000),
    .reset_in(reset),
    .reset_out(/* open */),
    // FX2 interface
    .fx2FifoSel_out(fx2FifoSel_out),
    .fx2Data_io(fx2Data_io),
    .fx2Read_out(fx2Read_out),
    .fx2GotData_in(fx2GotData_in),
    .fx2Write_out(fx2Write_out),
    .fx2GotRoom_in(fx2GotRoom_in),
    .fx2PktEnd_out(fx2PktEnd_out),
    // DVR interface -> Connects to application module
    .chanAddr_out(/* open */),
    //chanAddr,
    .h2fData_out(h2fData),
    .h2fValid_out(h2fValid),
    .h2fReady_in(h2fReady),
    .f2hData_in(f2hData),
    .f2hValid_in(f2hValid),
    .f2hReady_out(f2hReady));
  // SDRAM application
  sdram sdram_app(
      .clk_in(sysClk000),
    .reset_in(reset),
    // DVR interface -> Connects to comm_fpga module
    //chanAddr_in  => chanAddr,
    .h2fData_in(h2fData),
    .h2fValid_in(h2fValid),
    .h2fReady_out(h2fReady),
    .f2hData_out(f2hData),
    .f2hValid_out(f2hValid),
    .f2hReady_in(f2hReady),
    // External interface
    .ramCmd_out(ramCmd_out),
    .ramBank_out(ramBank_out),
    .ramAddr_out(ramAddr_out),
    .ramData_io(ramData_io),
    .ramLDQM_out(ramLDQM_out),
    .ramUDQM_out(ramUDQM_out));
  // Generate the system clock from the FX2LP's 48MHz clock
  clk_gen clk_gen(
      .clk_in(fx2Clk_in),
    .clk000_out(sysClk000),
    .clk180_out(sysClk180),
    .locked_out(locked));
  // Drive system clock and sync reset
  ODDR2 clk_drv(
      .D0(1'b1),
    .D1(1'b0),
    .C0(sysClk000),
    .C1(sysClk180),
    .Q(ramClk_out));
  assign reset =  ~(locked);
endmodule

