module pe(
input wire clk,
input wire reset,
input wire [15:0] a_j,
input wire [15:0] b_i,
input wire [15:0] s_prev,
input wire [15:0] m,
input wire [15:0] n_j,
output reg [15:0] s_next,
output reg [15:0] aj_bi,
input wire ab_valid_in,
input wire valid_in,
output reg ab_valid_out,
output reg valid_out,
output reg fifo_req
);
//entrada de la s anterior para la suma
//salida con la siguiente s
//salida de multiplicador reutilizado para calcular a*b
//indica que los datos de entrada en el multiplicador son validos
//todas las entradas son validas, y la m está calculada
//indica que la multiplicacion de un a y b validos se ha realizado con exito
//peticion de las siguientes entradas a, b, s, m
reg [31:0] prod_aj_bi; reg [31:0] next_prod_aj_bi; wire [31:0] mult_aj_bi;  // registros para la primera mult
reg [31:0] prod_nj_m; reg [31:0] next_prod_nj_m; wire [31:0] mult_nj_m; wire [31:0] mult_nj_m_reg;
reg [31:0] sum_1; reg [31:0] next_sum_1;
reg [31:0] sum_2; reg [31:0] next_sum_2;
reg ab_valid_reg; reg valid_out_reg; reg valid_out_reg2; reg valid_out_reg3;
reg [15:0] n_reg; reg [15:0] next_n_reg; reg [15:0] s_prev_reg; reg [15:0] next_s_prev_reg; reg [15:0] ab_out_reg;  //signal prod_aj_bi_out, next_prod_aj_bi_out : std_logic_vector(15 downto 0);
  assign mult_aj_bi = a_j * b_i;
  assign mult_nj_m = n_reg * m;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      prod_aj_bi <= {32{1'b0}};
      prod_nj_m <= {32{1'b0}};
      sum_1 <= {32{1'b0}};
      sum_2 <= {32{1'b0}};
      ab_valid_reg <= 1'b0;
      n_reg <= {16{1'b0}};
      valid_out_reg <= 1'b0;
      valid_out_reg2 <= 1'b0;
      valid_out_reg3 <= 1'b0;
      s_prev_reg <= {16{1'b0}};
    end
    else begin
      //prod_aj_bi_out <= next_prod_aj_bi_out;
      prod_aj_bi <= next_prod_aj_bi;
      prod_nj_m <= next_prod_nj_m;
      sum_1 <= next_sum_1;
      sum_2 <= next_sum_2;
      ab_valid_reg <= ab_valid_in;
      ab_out_reg <= mult_aj_bi[15:0];
      n_reg <= next_n_reg;
      valid_out_reg <= valid_in;
      //registramos el valid out para sacarle al tiempo de los datos validos
      valid_out_reg2 <= valid_out_reg;
      valid_out_reg3 <= valid_out_reg2;
      s_prev_reg <= next_s_prev_reg;
      //mult_nj_m_reg <= mult_nj_m;
    end
  end
  always @(s_prev, prod_aj_bi, prod_nj_m, sum_1, sum_2, mult_aj_bi, mult_nj_m, valid_in, ab_valid_reg, n_j, n_reg, valid_out_reg3, s_prev_reg, ab_out_reg) begin
    ab_valid_out <= ab_valid_reg;
    aj_bi <= ab_out_reg[15:0];
    //Sacamos uno de los dos registros de la multiplicacion fuera para el calculo de la constante
    s_next <= sum_2[15:0];
    //salida de la pipe
    fifo_req <= valid_in;
    valid_out <= valid_out_reg3;
    next_sum_1 <= sum_1;
    next_sum_2 <= sum_2;
    next_prod_nj_m <= prod_nj_m;
    next_prod_aj_bi <= prod_aj_bi;
    next_n_reg <= n_reg;
    next_s_prev_reg <= s_prev_reg;
    if((valid_in == 1'b1)) begin
      next_s_prev_reg <= s_prev;
      next_n_reg <= n_j;
      next_prod_aj_bi <= mult_aj_bi;
      next_prod_nj_m <= mult_nj_m;
      //registramos la multiplicacion de n_j,m
      next_sum_1 <= prod_aj_bi + sum_1[31:16] + s_prev_reg;
      next_sum_2 <= prod_nj_m + sum_2[31:16] + sum_1[15:0];
    end
    else begin
      next_s_prev_reg <= {16{1'b0}};
      next_n_reg <= {16{1'b0}};
      next_prod_aj_bi <= {32{1'b0}};
      next_prod_nj_m <= {32{1'b0}};
      next_sum_1 <= {32{1'b0}};
      next_sum_2 <= {32{1'b0}};
    end
  end
endmodule

module Debouncer(
input wire clock,
input wire reset,
input wire d_in,
output reg d_out
);
parameter [31:0] CLOCK_FREQUENCY=32000000;
parameter [31:0] SAMPLE_FREQUENCY=2000;
parameter [31:0] SAMPLE_COUNT=20;
wire sample_tick;
reg [1:0] sync;
reg [31:0] sample_counter;
  Timer #(
      .CLOCK_FREQUENCY(CLOCK_FREQUENCY),
    .TIMER_FREQUENCY(SAMPLE_FREQUENCY))
  sample_clock(
      .clock(clock),
    .reset(reset),
    .tick(sample_tick));
  always @(posedge clock) begin
    if(reset == 1'b1) begin
      sync <= {2{1'b0}};
      sample_counter <= 0;
      d_out <= 1'b0;
    end
    else begin
      sync <= {sync[0],d_in};
      if(sync[1] == 1'b0) begin
        sample_counter <= 0;
        d_out <= 1'b0;
      end
      else if(sample_tick == 1'b1) begin
        if(sample_counter == SAMPLE_COUNT) begin
          d_out <= 1'b1;
        end
        else begin
          sample_counter <= sample_counter + 1;
        end
      end
    end
  end
endmodule

