module FSM(
input wire clock,
input wire reset,
input wire [7:0] b_done,
input wire stop,
input wire doneVGA,
output reg start,
output reg startVGA
);
parameter [2:0]
  init = 0,
  inc = 1,
  finish = 2,
  writing = 3,
  calcul = 4;
reg [2:0] etat_present; reg [2:0] etat_futur;
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b1) begin
      etat_present <= init;
    end else begin
      etat_present <= etat_futur;
    end
  end
  always @(etat_present, doneVGA, stop, b_done) begin
    case(etat_present)
    init : begin
      etat_futur <= inc;
    end
    calcul : begin
      if(stop == 1'b1) begin
        etat_futur <= finish;
      end
      else if(b_done == 8'hFF) begin
        //all iterators are done
        etat_futur <= writing;
      end
      else begin
        etat_futur <= calcul;
      end
    end
    writing : begin
      if(doneVGA == 1'b1) begin
        //all results have been written on VGA
        etat_futur <= inc;
      end
      else begin
        etat_futur <= writing;
      end
    end
    inc : begin
      etat_futur <= calcul;
    end
    finish : begin
      etat_futur <= init;
    end
    endcase
  end
  always @(etat_present) begin
    case(etat_present)
    init : begin
      start <= 1'b0;
      startVGA <= 1'b0;
    end
    calcul : begin
      start <= 1'b0;
      startVGA <= 1'b0;
    end
    writing : begin
      start <= 1'b0;
      startVGA <= 1'b1;
    end
    inc : begin
      start <= 1'b1;
      startVGA <= 1'b0;
    end
    finish : begin
      start <= 1'b0;
      startVGA <= 1'b0;
    end
    endcase
  end
endmodule

