module tx_arbiter(
input wire clk,
input wire ready,
input wire ch0_request,
output wire ch0_granted,
input wire ch0_valid,
input wire [7:0] ch0_data,
input wire ch1_request,
output wire ch1_granted,
input wire ch1_valid,
input wire [7:0] ch1_data,
input wire ch2_request,
output wire ch2_granted,
input wire ch2_valid,
input wire [7:0] ch2_data,
input wire ch3_request,
output wire ch3_granted,
input wire ch3_valid,
input wire [7:0] ch3_data,
output wire merged_data_valid,
output wire [7:0] merged_data
);
parameter [5:0] idle_time;
reg [5:0] count = 1'b0;
wire [7:0] request = 1'b0;
reg [7:0] grant = 1'b0;
  assign request[0] = ch0_request;
  assign ch0_granted = grant[0] & request[0];
  assign request[1] = ch1_request;
  assign ch1_granted = grant[1] & request[1];
  assign request[2] = ch2_request;
  assign ch2_granted = grant[2] & request[2];
  assign request[3] = ch3_request;
  assign ch3_granted = grant[3] & request[3];
  assign merged_data_valid = ch0_valid | ch1_valid | ch2_valid | ch3_valid;
  assign merged_data = ch0_data | ch1_data | ch2_data | ch3_data;
  always @(posedge clk) begin
    grant <= grant & request;
    if(count == 0 && ready == 1'b1) begin
      if(request[3] == 1'b1) begin
        grant[3] <= 1'b1;
        count <= idle_time;
      end
      else if(request[2] == 1'b1) begin
        grant[2] <= 1'b1;
        count <= idle_time;
      end
      else if(request[1] == 1'b1) begin
        grant[1] <= 1'b1;
        count <= idle_time;
      end
      else if(request[0] == 1'b1) begin
        grant[0] <= 1'b1;
        count <= idle_time;
      end
    end
    else if((grant & request) != 8'b00000000) begin
      count <= (idle_time) - 2;
    end
    else begin
      count <= count - 1;
    end
  end
endmodule

module key_expansion_cu(
input wire clk,
input wire reset,
input wire x_start,
output reg y_end,
input wire x_comp,
output reg y_we,
output reg [1:0] y_1_2,
output reg [1:0] y_3_4
);
// start key expansion
// key expansion finished
// expansion finished (notification from operational unit)
// controlling signal for write enable
// controlling signal for key empander mux
// controlling signal for counter mux
parameter [1:0]
  S0 = 0,
  S1 = 1,
  S2 = 2;
reg [1:0] S; reg [1:0] S_next;
  always @(S, x_start, x_comp) begin
    case(S)
    S0 : begin
      y_1_2 <= 2'b00;
      // load into expander
      y_3_4 <= 2'b00;
      // initialize counter
      y_we <= 1'b0;
      y_end <= 1'b0;
      if(x_start == 1'b1) begin
        S_next <= S1;
      end
      else begin
        S_next <= S0;
      end
    end
    S1 : begin
      y_1_2 <= 2'b01;
      // feed back last round key
      y_3_4 <= 2'b01;
      // increment counter
      y_we <= 1'b1;
      y_end <= 1'b0;
      if(x_comp == 1'b1) begin
        S_next <= S2;
      end
      else begin
        S_next <= S1;
      end
    end
    S2 : begin
      y_1_2 <= 2'b--;
      y_3_4 <= 2'b--;
      y_we <= 1'b0;
      y_end <= 1'b1;
      S_next <= S0;
    end
    endcase
  end
  always @(posedge clk, posedge reset, posedge S_next) begin
    if(reset == 1'b1) begin
      S <= S0;
    end else begin
      S <= S_next;
    end
  end
endmodule

module gtia_priority(
