input wire PF1,
input wire PF2,
input wire PF3,
input wire BK,
output wire P0_OUT,
output wire P1_OUT,
output wire P2_OUT,
output wire P3_OUT,
output wire PF0_OUT,
output wire PF1_OUT,
output wire PF2_OUT,
output wire PF3_OUT,
output wire BK_OUT
);
wire P01;
wire P23;
wire PF01;
wire PF23;
wire PRI01;
wire PRI12;
wire PRI23;
wire PRI03;
wire PRI0;
wire PRI1;
wire PRI2;
wire PRI3;
wire MULTI;
wire SP0;
wire SP1;
wire SP2;
wire SP3;
wire SF0;
wire SF1;
wire SF2;
wire SF3;
wire SB;
reg SP0_next;
reg SP1_next;
reg SP2_next;
reg SP3_next;
reg SF0_next;
reg SF1_next;
reg SF2_next;
reg SF3_next;
reg SB_next;
reg SP0_reg;
reg SP1_reg;
reg SP2_reg;
reg SP3_reg;
reg SF0_reg;
reg SF1_reg;
reg SF2_reg;
reg SF3_reg;
reg SB_reg;
  // Use actual GTIA logic...
  assign P01 = P0 | P1;
  assign P23 = P2 | P3;
  assign PF01 = PF0 | PF1;
  assign PF23 = PF2 | PF3;
  assign PRI0 = prior[0];
  assign PRI1 = prior[1];
  assign PRI2 = prior[2];
  assign PRI3 = prior[3];
  assign MULTI = prior[5];
  assign PRI01 = PRI0 | PRI1;
  assign PRI12 = PRI1 | PRI2;
  assign PRI23 = PRI2 | PRI3;
  assign PRI03 = PRI0 | PRI3;
  assign SP0 = P0 &  ~(PF01 & PRI23) &  ~(PRI2 & PF23);
  assign SP1 = P1 &  ~(PF01 & PRI23) &  ~(PRI2 & PF23) & ( ~P0 | MULTI);
  assign SP2 = P2 &  ~P01 &  ~(PF23 & PRI12) &  ~(PF01 &  ~PRI0);
  assign SP3 = P3 &  ~P01 &  ~(PF23 & PRI12) &  ~(PF01 &  ~PRI0) & ( ~P2 | MULTI);
  assign SF0 = PF0 &  ~(P23 & PRI0) &  ~(P01 & PRI01) &  ~SF3;
  assign SF1 = PF1 &  ~(P23 & PRI0) &  ~(P01 & PRI01) &  ~SF3;
  assign SF2 = PF2 &  ~(P23 & PRI03) &  ~(P01 &  ~PRI2) &  ~SF3;
  assign SF3 = PF3 &  ~(P23 & PRI03) &  ~(P01 &  ~PRI2);
  assign SB =  ~P01 &  ~P23 &  ~PF01 &  ~PF23;
  // register
  always @(posedge clk) begin
    SP0_reg <= SP0_next;
    SP1_reg <= SP1_next;
    SP2_reg <= SP2_next;
    SP3_reg <= SP3_next;
    SF0_reg <= SF0_next;
    SF1_reg <= SF1_next;
    SF2_reg <= SF2_next;
    SF3_reg <= SF3_next;
    SB_reg <= SB_next;
  end
  // need to register this to get same position as GTIA modes - i.e. two colour clocks after AN data received
  always @(colour_enable, SP0_reg, SP1_reg, SP2_reg, SP3_reg, SF0_reg, SF1_reg, SF2_reg, SF3_reg, SB_reg, SP0, SP1, SP2, SP3, SF0, SF1, SF2, SF3, SB) begin
    SP0_next <= SP0_reg;
    SP1_next <= SP1_reg;
    SP2_next <= SP2_reg;
    SP3_next <= SP3_reg;
    SF0_next <= SF0_reg;
    SF1_next <= SF1_reg;
    SF2_next <= SF2_reg;
    SF3_next <= SF3_reg;
    SB_next <= SB_reg;
    if((colour_enable == 1'b1)) begin
      SP0_next <= SP0;
      SP1_next <= SP1;
      SP2_next <= SP2;
      SP3_next <= SP3;
      SF0_next <= SF0;
      SF1_next <= SF1;
      SF2_next <= SF2;
      SF3_next <= SF3;
      SB_next <= SB;
    end
  end
  // output
  assign P0_OUT = SP0_reg;
  assign P1_OUT = SP1_reg;
  assign P2_OUT = SP2_reg;
  assign P3_OUT = SP3_reg;
  assign PF0_OUT = SF0_reg;
  assign PF1_OUT = SF1_reg;
  assign PF2_OUT = SF2_reg;
  assign PF3_OUT = SF3_reg;
  assign BK_OUT = SB_reg;
endmodule

