module edge_detect(
input wire clk,
input wire data_in,
input wire reset_n,
output reg rise,
output reg fall
);
// Architecture Declaration 
// Signals & Constants Declaration 
reg q1;
reg q2;  // Begin Architecture
  //-----------------------------------------
  // Process for combinatorial logic
  //----------------------------------------- 
  // not needed in this file, using concurrent logic
  //-----------------------------------------
  // Process for registers (flip-flops)
  //-----------------------------------------
  always @(posedge clk, posedge reset_n) begin
    if(reset_n == 1'b0) begin
      q1 <= 1'b0;
      q2 <= 1'b0;
    end else begin
      q1 <= data_in;
      q2 <= q1;
    end
  end
  //-----------------------------------------
  // Concurrent Assignments  
  //-----------------------------------------
  always @(q1, q2) begin
    // Default for rise und fall
    rise <= 1'b0;
    fall <= 1'b0;
    if(q1 == 1'b1 && q2 == 1'b0) begin
      rise <= 1'b1;
    end
    else if(q1 == 1'b0 && q2 == 1'b1) begin
      fall <= 1'b1;
    end
  end
endmodule

module add_118(
output wire [15:0] result,
input wire [15:0] in_a,
input wire [15:0] in_b
);
wire [17:0] carry_inA;
wire [17:0] carry_inB;
wire [17:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign result = carry_res[16:1];
endmodule

