module flip_flop_latch(
input wire d,
input wire clk,
output reg q1,
output reg q2
);
//------------------------------------
//signals and declarations
  //-----------------
  //-- flip flop
  //-----------------
  always @(posedge clk) begin : P2
  //declarativepart
    q1 <= d;
  end
  //-----------------
