module EPROC_IN2(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
input wire ENA,
input wire swap_inputbits,
input wire [1:0] ENCODING,
input wire [1:0] EDATA_IN,
output wire [9:0] DATA_OUT,
output wire DATA_RDY,
output wire busyOut
);
parameter do_generate=true;
parameter zeros10array = 1'b0;  //
reg [1:0] edata_in_s;  //
wire [9:0] DATA_OUT_direct;
wire DATA_RDY_direct;  //-
wire [9:0] DATA_OUT_8b10b_decoded;
wire DATA_RDY_8b10b_decoded;  //-
wire [9:0] DATA_OUT_HDLC_decoded;
wire DATA_RDY_HDLC_decoded;  //-
wire DATA_RDY_sig;
wire [9:0] DATA_OUT_s;
wire RESTART_sig; wire rst_case00; wire rst_case01; wire rst_case10;  //-
  generate if (do_generate == true) begin: gen_enabled
      //
    always @(swap_inputbits, EDATA_IN) begin
      if(swap_inputbits == 1'b1) begin
        edata_in_s <= {EDATA_IN[0],EDATA_IN[1]};
      end
      else begin
        edata_in_s <= EDATA_IN;
      end
    end
    //
    assign RESTART_sig = rst | ( ~ENA);
    // comes from clk40 domain 
    //-----------------------------------------------------------------------------------------
    // ENCODING case "00": direct data, no delimeter...
    //-----------------------------------------------------------------------------------------
    assign rst_case00 = ((RESTART_sig == 1'b0) && (ENCODING == 2'b00)) ? 1'b0 : 1'b1;
    //
    EPROC_IN2_direct direct_data_case(
          .bitCLK(bitCLK),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case00),
      .edataIN(edata_in_s),
      .dataOUT(DATA_OUT_direct),
      .dataOUTrdy(DATA_RDY_direct));
    //-----------------------------------------------------------------------------------------
    // ENCODING case "01": DEC8b10b
    //-----------------------------------------------------------------------------------------
    assign rst_case01 = ((RESTART_sig == 1'b0) && (ENCODING == 2'b01)) ? 1'b0 : 1'b1;
    //
    EPROC_IN2_DEC8b10b dec8b10b_case(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case01),
      .edataIN(edata_in_s),
      .dataOUT(DATA_OUT_8b10b_decoded),
      .dataOUTrdy(DATA_RDY_8b10b_decoded),
      .busyOut(busyOut));
    //-----------------------------------------------------------------------------------------
    // ENCODING case "10": HDLC
    //-----------------------------------------------------------------------------------------
    assign rst_case10 = ((RESTART_sig == 1'b0) && (ENCODING == 2'b10)) ? 1'b0 : 1'b1;
    //
    EPROC_IN2_HDLC decHDLC_case(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case10),
      .edataIN(edata_in_s),
      .dataOUT(DATA_OUT_HDLC_decoded),
      .dataOUTrdy(DATA_RDY_HDLC_decoded));
    //-----------------------------------------------------------------------------------------
    // output data/rdy according to the encoding settings
    //-----------------------------------------------------------------------------------------
    MUX4_Nbit #(
          .N(10))
    DATA_OUT_MUX4_10bit(
          .data0(DATA_OUT_direct),
      .data1(DATA_OUT_8b10b_decoded),
      .data2(DATA_OUT_HDLC_decoded),
      .data3(zeros10array),
      .sel(ENCODING),
      .data_out(DATA_OUT_s));
    MUX4 DATA_RDY_MUX4(
          .data0(DATA_RDY_direct),
      .data1(DATA_RDY_8b10b_decoded),
      .data2(DATA_RDY_HDLC_decoded),
      .data3(1'b0),
      .sel(ENCODING),
      .data_out(DATA_RDY_sig));
    assign DATA_RDY = DATA_RDY_sig;
    assign DATA_OUT = DATA_OUT_s;
        //------------------
  end
  endgenerate
  //
  //
  generate if (do_generate == false) begin: gen_disabled
      assign DATA_OUT = {10{1'b0}};
    assign DATA_RDY = 1'b0;
    assign busyOut = 1'b0;
  end
  endgenerate
endmodule

