module stack_256x16(
input wire push,
input wire pop,
output wire [15:0] dout,
input wire [15:0] din,
input wire clk
);
parameter [1:0]
  OpNone = 0,
  OpPush = 1,
  OpPop = 2;
  // Address we're using for the RAM.
reg [7:0] addr = 1'b0;  // Registered data when writing to RAM.
reg [15:0] din_r;  // Address of the free space at the top of the stack.
reg [7:0] top = 1'b0;
reg we;
wire [1:0] op;
  ram_256x16 RAM(
      .dout(dout),
    .din(din_r),
    .addr(addr),
    .we(we),
    .clk(clk));
  assign op = (push == 1'b1 && pop == 1'b0) ? OpPush : (push == 1'b0 && pop == 1'b1) ? OpPop : OpNone;
  //process (clk)
  //begin
  //    if (rising_edge(clk)) then
  //        if (push = '1' and pop = '0') then
  //            op <= OpPush;
  //        elsif (push = '0' and pop = '1') then
  //            op <= OpPop;
  //        else
  //            op <= OpNone;
  //        end if;
  //    end if;
  //end process;
  always @(posedge clk) begin
    case(op)
    OpNone : begin
      we <= 1'b0;
    end
    OpPush : begin
      addr <= top;
      top <= top + 1;
      din_r <= din;
      we <= 1'b1;
    end
    OpPop : begin
      addr <= top - 1;
      top <= top - 1;
      we <= 1'b0;
    end
    endcase
  end
endmodule

