  s2 = 3,
  s3 = 4;
reg [2:0] current_state; reg [2:0] next_state;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b0)) begin
      current_state <= inicial;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, x, eq) begin
    next_state <= current_state;
    case(current_state)
    inicial : begin
      if((x == 1'b1)) begin
        next_state <= s3;
      end
    end
    s3 : begin
      if((x == 1'b1 && eq == 1'b1)) begin
        next_state <= inicial;
      end
      else if((x == 1'b1 && eq == 1'b0)) begin
        next_state <= s2;
      end
    end
    s2 : begin
      if((x == 1'b1 && eq == 1'b1)) begin
        next_state <= inicial;
      end
      else if((x == 1'b1 && eq == 1'b0)) begin
        next_state <= s1;
      end
    end
    s1 : begin
      if((x == 1'b1 && eq == 1'b1)) begin
        next_state <= inicial;
      end
      else if((x == 1'b1 && eq == 1'b0)) begin
        next_state <= s0;
      end
    end
    s0 : begin
      next_state <= current_state;
    end
    endcase
  end
  always @(current_state, x) begin
    case(current_state)
    inicial : begin
      if((x == 1'b1)) begin
        ld <= 1'b1;
      end
      else begin
        ld <= 1'b0;
      end
      lock <= 1'b0;
      st <= 4'b0011;
    end
    s3 : begin
      ld <= 1'b0;
      st <= 4'b0011;
      lock <= 1'b1;
    end
    s2 : begin
      ld <= 1'b0;
      st <= 4'b0010;
      lock <= 1'b1;
    end
    s1 : begin
      ld <= 1'b0;
      st <= 4'b0001;
      lock <= 1'b1;
    end
    s0 : begin
      ld <= 1'b0;
      st <= 4'b0000;
      lock <= 1'b1;
    end
    endcase
  end
endmodule

