module debounce(
input wire CLK,
input wire INPUT,
output reg OUTPUT
);
parameter [31:0] wait_time=20;
// Wait_time is a fixed time to wait to validate a debounce signal
// Wait time is based on the Nexys 50 MHZ Clock
// XX : (2^xx + 2)/CLK
// 21 : 41.9ms | (2^21 + 2)/50E6
// 20 : 21.0ms | (2^20 + 2)/50E6
// 19 : 10.5ms | (2^19 + 2)/50E6
// 18 :  5.2ms | (2^18 + 2)/50E6
reg [1:0] D_STATE;
wire D_SET;
reg [wait_time:0] Count = 1'b0;
  assign D_SET = D_STATE[0] ^ D_STATE[1];
  //Check what the deboune states are
  // *if there is a change in state then D_SET will be set to a high
  always @(posedge CLK) begin
    D_STATE[0] <= INPUT;
    D_STATE[1] <= D_STATE[0];
    if((D_SET == 1'b1)) begin
      Count <= {((wait_time)-(0)+1){1'b0}};
    end
    else if((Count[wait_time] == 1'b0)) begin
      Count <= Count + 1;
    end
    else begin
      OUTPUT <= D_STATE[1];
    end
  end
endmodule

