wire orgateop0 = 1'b0; wire andgateop0 = 1'b0; wire notorgateop1 = 1'b0; wire andgateop2 = 1'b0; wire orgateop2 = 1'b0; wire op0 = 1'b0; wire op1 = 1'b0; wire op2 = 1'b0;
