module STD_06600_good(
input wire i_Clock,
input wire i_Reset_n,
input wire i_Enable,
input wire [3:0] i_Length,
output wire [3:0] o_Count
);
// Main clock signal
// Main reset signal
// Enables the counter
// Unsigned Value for Counter Period
// Counter (unsigned value)
//CODE
reg [3:0] Count;  // Counter output signal (unsigned converted)
wire [3:0] Count_Length;  // Length input signal (unsigned converted)
  assign Count_Length = i_Length;
  // Will count undefinitely from 0 to i_Length while i_Enable is asserted
  always @(posedge i_Reset_n, posedge i_Clock) begin
    if((i_Reset_n == 1'b0)) begin
      Count <= {4{1'b0}};
    end else begin
      if((Count >= Count_Length)) begin
        // Counter restarts from 0
        Count <= {4{1'b0}};
      end
      else if((i_Enable == 1'b1)) begin
        // Increment counter value
        Count <= Count + 1;
      end
    end
  end
  assign o_Count = Count;
//CODE
endmodule

