module vga(
input wire clk,
input wire reset,
input wire [2:0] RGB,
output reg HSync,
output reg VSync,
output reg R,
output reg G,
output reg B,
output reg [9:0] X,
output reg [9:0] Y
);
  always @(posedge reset, posedge clk) begin : P1
  // XCount -> holds the count for the X dimension ( monitor resolution is 640x480 )
    reg [31:0] HCount = 0;
    reg [31:0] VCount = 0;
    reg prescaler = 1'b0;
      // When resetting, set all outputs to 0
    if(reset == 1'b1) begin
      HSync <= 1'b1;
      VSync <= 1'b1;
      R <= 1'b0;
      G <= 1'b0;
      B <= 1'b0;
      X <= 10'b0000000000;
      Y <= 10'b0000000000;
    end else begin
      // Prescaler 
      if(prescaler == 1'b1) begin
        prescaler = 1'b0;
      end
      else begin
        prescaler = 1'b1;
      end
      // Counters:
      if(prescaler == 1'b0) begin
        if(HCount == 800) begin
          HCount = 0;
          if(VCount == 521) begin
            VCount = 0;
          end
          else begin
            VCount = VCount + 1;
          end
        end
        else begin
          HCount = HCount + 1;
        end
      end
      // HSync:
      if(HCount >= 654 && HCount < 752) begin
        HSync <= 1'b0;
      end
      else begin
        HSync <= 1'b1;
      end
      // VSync:
      if(VCount >= 490 && VCount < 492) begin
        VSync <= 1'b0;
      end
      else begin
        VSync <= 1'b1;
      end
      // X / Y position:
      if(HCount < 640) begin
        X <= HCount;
      end
      if(VCount < 480) begin
        Y <= VCount;
      end
      // Color:
      if(VCount < 480 && HCount < 640) begin
        R <= RGB[2];
        G <= RGB[1];
        B <= RGB[0];
      end
      else begin
        R <= 1'b0;
        G <= 1'b0;
        B <= 1'b0;
      end
    end
  end
endmodule

