      IF_ID_enable <= 1'b0;
      ID_EXE_enable <= 1'b0;
      ID_EXE_bubble <= 1'b1;
    end
    else begin
      PCReg_enable <= 1'b1;
      IF_ID_enable <= 1'b1;
      ID_EXE_enable <= 1'b1;
      ID_EXE_bubble <= 1'b0;
    end
    if(((ID_Rs == ID_EXE_Rd) && ID_EXE_regWE == 1'b1)) begin
      ALUctrl1 <= 2'b10;
    end
    else begin
      if(((ID_Rs == EXE_MEM_Rd) && EXE_MEM_regWE == 1'b1)) begin
        ALUctrl1 <= 2'b11;
      end
      else begin
        ALUCtrl1 <= 2'b00;
      end
    end
    if(((ID_Rt == ID_EXE_Rd) && ID_EXE_regWE == 1'b1)) begin
      ALUctrl2 <= 2'b10;
    end
    else begin
      if(((ID_Rt == EXE_MEM_Rd) && EXE_MEM_regWE == 1'b1)) begin
        ALUctrl2 <= 2'b11;
      end
      else begin
        ALUCtrl2 <= 2'b00;
      end
    end
  end
endmodule

module grain(
input wire CLK_I,
input wire CLKEN_I,
input wire ARESET_I,
input wire KEY_I,
input wire IV_I,
input wire INIT_I,
output wire KEYSTREAM_O,
output wire KEYSTREAM_VALID_O
);
parameter DEBUG=false;
parameter FAST=false;
// attempt manual register balancing
parameter [1:0]
  IDLE = 0,
  INIT_KEYIV = 1,
  INIT_RUN = 2;
reg [1:0] state;
reg [7:0] cnt = 1'b0;
reg cnt79 = 1'b0; reg cnt63 = 1'b0; reg cnt239 = 1'b0;
reg inject_input; reg set_injected_iv; reg allow_output;
reg add_output;
wire output_bit; reg output_bit_d; reg allow_output_d;
  assign KEYSTREAM_O = output_bit_d;
  assign KEYSTREAM_VALID_O = allow_output_d;
  generate if (FAST == false) begin: slow_design
      grain_datapath_slow #(
          .DEBUG(DEBUG))
    functions0(
          .CLK_I(CLK_I),
      .CLKEN_I(CLKEN_I),
      .ARESET_I(ARESET_I),
      .KEY_I(KEY_I),
      .IV_I(IV_I),
      .INJECT_INPUT_I(inject_input),
      .PAD_IV_I(set_injected_iv),
      .ADD_OUTPUT_I(add_output),
      .H_O(output_bit));
  end
  endgenerate
  generate if (FAST == true) begin: fast_design
      grain_datapath_fast #(
          .DEBUG(DEBUG))
    functions1(
          .CLK_I(CLK_I),
      .CLKEN_I(CLKEN_I),
      .ARESET_I(ARESET_I),
      .KEY_I(KEY_I),
      .IV_I(IV_I),
      .INJECT_INPUT_I(inject_input),
      .PAD_IV_I(set_injected_iv),
      .ADD_OUTPUT_I(add_output),
      .H_O(output_bit));
  end
  endgenerate
  // output registers:
  // (in case the "user" forgets this is at 
  //  his end and kills my fmax)
  // 
  always @(posedge CLK_I, posedge ARESET_I) begin
    if(ARESET_I == 1'b1) begin
      output_bit_d <= 1'b0;
      allow_output_d <= 1'b0;
    end else begin
      if(CLKEN_I == 1'b1) begin
        output_bit_d <= output_bit;
        allow_output_d <= allow_output;
      end
    end
  end
  // the counter:
  always @(posedge CLK_I) begin
    if(CLKEN_I == 1'b1) begin
      if(state == IDLE) begin
        cnt <= 9'b0000_0001;
      end
      else begin
        cnt <= cnt + 1;
      end
      if(cnt == 79) begin
        cnt79 <= 1'b1;
      end
      else begin
        cnt79 <= 1'b0;
      end
      if(cnt == 63) begin
        cnt63 <= 1'b1;
      end
      else begin
        cnt63 <= 1'b0;
      end
      if(cnt == 239) begin
        cnt239 <= 1'b1;
      end
      else begin
        cnt239 <= 1'b0;
      end
    end
  end
  // the controller fsm:
  always @(posedge CLK_I, posedge ARESET_I) begin
    if(ARESET_I == 1'b1) begin
      state <= IDLE;
      inject_input <= 1'b0;
      set_injected_iv <= 1'b0;
      add_output <= 1'b0;
      allow_output <= 1'b0;
    end else begin
      if(CLKEN_I == 1'b1) begin
        case(state)
        IDLE : begin
          if(INIT_I == 1'b1) begin
            state <= INIT_KEYIV;
            inject_input <= 1'b1;
            set_injected_iv <= 1'b0;
            allow_output <= 1'b0;
          end
        end
        INIT_KEYIV : begin
          if(cnt63 == 1'b1) begin
            set_injected_iv <= 1'b1;
          end
          if(cnt79 == 1'b1) begin
            state <= INIT_RUN;
            inject_input <= 1'b0;
            add_output <= 1'b1;
          end
        end
        INIT_RUN : begin
          if(cnt239 == 1'b1) begin
            state <= IDLE;
            add_output <= 1'b0;
            allow_output <= 1'b1;
          end
        end
        default : begin
          state <= IDLE;
        end
        endcase
      end
    end
  end
endmodule

