module DEMO_MPU6050(
input wire MCLK,
input wire RESET,
inout wire SDA,
inout wire SCL,
output wire LEDX,
output wire LEDY,
output wire LEDZ,
output wire LEDSIGN
);
// COMPONENTS --
// COMPONENTS --
//
// SIGNALS --
reg [7:0] XREG;
reg [7:0] YREG;
reg [7:0] ZREG;  //
//
// SIGNALS --
wire TIC;
wire SRST;
wire [7:0] DOUT;
wire RD;
wire WE;
wire QUEUED;
wire NACK;
wire STOP;
wire DATA_VALID;
wire [7:0] DIN;
wire [3:0] ADR;
wire [7:0] DATA;
wire LOAD;
wire COMPLETED;
wire RESCAN;
wire [2:0] STATUS;
wire SCL_IN;
wire SCL_OUT;
wire SDA_IN;
wire SDA_OUT;
reg [7:0] counter;  //signal counter 	: std_logic_vector(10 downto 0);
wire nRST;  //
  assign nRST =  ~(RESET);
  // PORT MAP --
  MPU6050 I_MPU6050_0(
      .MCLK(MCLK),
    .nRST(nRST),
    .TIC(TIC),
    .SRST(SRST),
    .DOUT(DIN),
    .RD(RD),
    .WE(WE),
    .QUEUED(QUEUED),
    .NACK(NACK),
    .STOP(STOP),
    .DATA_VALID(DATA_VALID),
    .DIN(DOUT),
    .ADR(ADR),
    .DATA(DATA),
    .LOAD(LOAD),
    .COMPLETED(COMPLETED),
    .RESCAN(RESCAN));
  // PORT MAP --
  I2CMASTER #(
      .DEVICE(8'h68))
  I_I2CMASTER_0(
      .MCLK(MCLK),
    .nRST(nRST),
    .SRST(SRST),
    .TIC(TIC),
    .DIN(DIN),
    .DOUT(DOUT),
    .RD(RD),
    .WE(WE),
    .NACK(NACK),
    .QUEUED(QUEUED),
    .DATA_VALID(DATA_VALID),
    .STOP(STOP),
    .STATUS(STATUS),
    .SCL_IN(SCL_IN),
    .SCL_OUT(SCL_OUT),
    .SDA_IN(SDA_IN),
    .SDA_OUT(SDA_OUT));
  // PORT MAP --
  COMPARE I_COMPARE_0(
      .MCLK(MCLK),
    .nRST(nRST),
    .TIC(TIC),
    .COMPLETED(COMPLETED),
    .RESCAN(RESCAN),
    .XREG(XREG),
    .YREG(YREG),
    .ZREG(ZREG),
    .LEDX(LEDX),
    .LEDY(LEDY),
    .LEDZ(LEDZ),
    .SIGN(LEDSIGN));
  //
  assign TIC = counter[7] & counter[5];
  // 2.56 + 0.64 uS (~300 khz ) for ~100 kbit
  //TIC <= counter(10) and counter(8);
  always @(posedge MCLK, posedge nRST) begin
    if((nRST == 1'b0)) begin
      counter <= {8{1'b0}};
    end else begin
      if((TIC == 1'b1)) begin
        counter <= {8{1'b0}};
      end
      else begin
        counter <= (counter) + 1;
        //counter <= std_logic_vector(to_unsigned(to_integer(unsigned( counter )) + 1,11));
      end
    end
  end
  always @(posedge MCLK, posedge nRST) begin
    if((nRST == 1'b0)) begin
      XREG <= {8{1'b0}};
      YREG <= {8{1'b0}};
      ZREG <= {8{1'b0}};
    end else begin
      if((TIC == 1'b1 && LOAD == 1'b1)) begin
        if((ADR == 4'h0)) begin
          XREG <= DATA;
        end
        else if((ADR == 4'h2)) begin
          YREG <= DATA;
        end
        else if((ADR == 4'h4)) begin
          ZREG <= DATA;
        end
      end
    end
  end
  //  open drain PAD pull up 1.5K needed
  assign SCL = SCL_OUT == 1'b1 ? 1'bZ : 1'b0;
  assign SCL_IN = to_UX01[SCL];
  assign SDA = SDA_OUT == 1'b1 ? 1'bZ : 1'b0;
  assign SDA_IN = to_UX01[SDA];
