module core_clock_mux(
input wire [1:0] clksel,
input wire testen,
input wire clkin,
input wire clk1x,
input wire clk2x,
input wire clk4x,
output wire clkout
);
parameter [31:0] tech;
parameter [31:0] scantest=0;
wire sel1x; wire sel2x; wire sel4x;
wire lclkm1o; wire lclkm2o;
wire selbypass; wire seltest;
  // Select testclk or not
  assign seltest = (testen == 1'b1 && scantest == 1) ? 1'b1 : 1'b0;
  // Bypass PLL
  assign selbypass = (clksel == 2'b00 || seltest == 1'b1) ? 1'b1 : 1'b0;
  // Select PLL clock if not test or bypassed
  assign sel1x = (clksel[1:0] == 2'b01 && selbypass == 1'b0 && seltest == 1'b0) ? 1'b1 : 1'b0;
  assign sel2x = (clksel[1:0] == 2'b10 && selbypass == 1'b0 && seltest == 1'b0) ? 1'b1 : 1'b0;
  assign sel4x = (clksel[1:0] == 2'b11 && selbypass == 1'b0 && seltest == 1'b0) ? 1'b1 : 1'b0;
  // Select output clock from PLL (or bypass PLL)
  clkmux #(
      .tech(tech))
  lpllclkm1(
      clkin,
    clk1x,
    sel1x,
    lclkm1o);
  clkmux #(
      .tech(tech))
  lpllclkm2(
      lclkm1o,
    clk2x,
    sel2x,
    lclkm2o);
  clkmux #(
      .tech(tech))
  lpllclkm4(
      lclkm2o,
    clk4x,
    sel4x,
    clkout);
endmodule

