module pack_16to12(
input wire clk,
input wire rst,
input wire enable,
input wire data_in_dval,
input wire [63:0] data_in,
output wire data_in_stop,
output reg data_out_dval,
output reg [63:0] data_out,
input wire data_out_stop
);
//---------------------------------------------------------------------------------
// Signal Declarations
//---------------------------------------------------------------------------------
reg [1:0] cycle;
reg [63:0] data_pr;
reg data_12_dval;
reg [63:0] data_12;
wire [11:0] data_in0;
wire [11:0] data_in1;
wire [11:0] data_in2;
wire [11:0] data_in3;
wire [11:0] data_pr0;
wire [11:0] data_pr1;
wire [11:0] data_pr2;
wire [11:0] data_pr3;
  assign data_in0 = data_in[11:0];
  assign data_in1 = data_in[27:16];
  assign data_in2 = data_in[43:32];
  assign data_in3 = data_in[59:48];
  assign data_pr0 = data_pr[11:0];
  assign data_pr1 = data_pr[27:16];
  assign data_pr2 = data_pr[43:32];
  assign data_pr3 = data_pr[59:48];
  //---------------------------------------------------------------------------------
  // Begin
  //---------------------------------------------------------------------------------
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      cycle <= {2{1'b0}};
      data_12_dval <= 1'b0;
      data_pr <= {64{1'b0}};
      data_12 <= {64{1'b0}};
      data_out_dval <= 1'b0;
      data_out <= {64{1'b0}};
    end else begin
      // When packing four input cycles goes into 3 output cycles
      // 4cycles x 4samples x 12bit = 3cycles x 64bit
      if((data_in_dval == 1'b1)) begin
        cycle <= cycle + 1;
      end
      // Output data on the 2nd, 3rd, and 4th cycle
      if((data_in_dval == 1'b1 && cycle != 0)) begin
        data_12_dval <= 1'b1;
      end
      else begin
        data_12_dval <= 1'b0;
      end
      // Keep the input data for one clock cycle
      data_pr <= data_in;
      // Generate output data on the 2nd, 3rd, and 4th cycle
      if((data_in_dval == 1'b1)) begin
        case(cycle)
        2'b01 : begin
          data_12 <= {data_in1[3:0],data_in0,data_pr3,data_pr2,data_pr1,data_pr0};
        end
        2'b10 : begin
          data_12 <= {data_in2[7:0],data_in1,data_in0,data_pr3,data_pr2,data_pr1[11:4]};
        end
        2'b11 : begin
          data_12 <= {data_in3,data_in2,data_in1,data_in0,data_pr3,data_pr2[11:8]};
        end
        default : begin
        end
        endcase
      end
      // Output Multiplexer
      if((enable == 1'b1)) begin
        data_out_dval <= data_12_dval;
        data_out <= data_12;
      end
      else begin
        data_out_dval <= data_in_dval;
        data_out <= data_in;
      end
    end
  end
  assign data_in_stop = data_out_stop;
    //---------------------------------------------------------------------------------
  // End
  //---------------------------------------------------------------------------------
endmodule

module ALU_ram(
input wire clk,
input wire rst,
input wire [3:0] reg_addr,
input wire [7:0] mem_addr,
input wire [7:0] result,
input wire [1:0] operand,
output reg [3:0] reg_addr_out,
output reg [7:0] reg_data_out,
output reg reg_write_enable,
output wire mem_re,
output wire mem_we,
output wire [7:0] mem_read_out
);
reg [7:0] mem_write_addr;
reg [7:0] mem_read_addr;
reg [7:0] mem_result;
reg mem_write_enable;
reg mem_read_enable;
reg [7:0] mem_data_out;
  ram c0(
      clk,
    rst,
    mem_result,
    mem_write_addr,
    mem_read_addr,
    mem_write_enable,
    mem_read_enable,
    mem_data_out);
  //For Debug
  assign mem_re = mem_read_enable;
  assign mem_we = mem_write_enable;
  assign mem_read_out = mem_data_out;
  always @(reg_addr, mem_addr, result, operand) begin
    case(operand)
    2'b00 : begin
      //no op
      mem_write_addr <= 8'b00000000;
      mem_read_addr <= 8'b00000000;
      mem_result <= 8'b00000000;
      mem_write_enable <= 1'b0;
      mem_read_enable <= 1'b0;
      mem_data_out <= 8'b00000000;
      reg_addr_out <= 4'b0000;
      reg_data_out <= 8'b00000000;
      reg_write_enable <= 1'b0;
    end
    2'b01 : begin
      //R <= ALU
      mem_write_enable <= 1'b0;
      mem_read_enable <= 1'b0;
      reg_addr_out <= reg_addr;
      reg_data_out <= result;
      reg_write_enable <= 1'b1;
    end
    2'b10 : begin
      //R <= Mem
      mem_read_addr <= mem_addr;
      mem_read_enable <= 1'b1;
      mem_write_enable <= 1'b0;
      reg_addr_out <= reg_addr;
      reg_write_enable <= 1'b1;
      reg_data_out <= mem_data_out;
    end
    2'b11 : begin
      //Mem <= R
      mem_write_addr <= mem_addr;
      mem_write_enable <= 1'b1;
      mem_read_enable <= 1'b0;
      reg_write_enable <= 1'b0;
      mem_result <= result;
    end
    default : begin
      mem_write_addr <= 8'b00000000;
      mem_read_addr <= 8'b00000000;
      mem_result <= 8'b00000000;
      mem_write_enable <= 1'b0;
      mem_read_enable <= 1'b0;
      mem_data_out <= 8'b00000000;
      reg_addr_out <= 4'b0000;
      reg_data_out <= 8'b00000000;
      reg_write_enable <= 1'b0;
    end
    endcase
  end
endmodule

