module clock(
input wire clk_50Mhz,
input wire rst,
output wire clk_2Hz
);
reg [23:0] prescaler;
reg clk_2Hz_i;
  always @(posedge clk_50Mhz, posedge rst) begin
      // process gen_clk
    if(rst == 1'b1) begin
      clk_2Hz_i <= 1'b0;
      prescaler <= {24{1'b0}};
    end else begin
      // rising clock edge
      if(prescaler == 8'h10) begin
        // 12 500 000 in hex
        prescaler <= {24{1'b0}};
        clk_2Hz_i <=  ~clk_2Hz_i;
      end
      else begin
        prescaler <= prescaler + 1'b1;
      end
    end
  end
  assign clk_2Hz = clk_2Hz_i;
endmodule

