module logical_unit(
input wire [15:0] RA,
input wire [15:0] RB,
input wire [2:0] OP,
output wire [15:0] LOG_OUT,
output wire [3:0] SREG_OUT
);
reg [15:0] result = 1'b0;
wire zro = 1'b0;
  always @(*) begin
    case(OP)
      3'b011 : result <= RA | RB;
  // OR
      3'b010 : result <= RA & RB;
  // AND
      3'b110 : result <= RA & RB;
  // ANDI
      3'b100 : result <= RB;
  // MOV
      default : result <= RA | RB;
    endcase
  end
  // SAFE (I guess)
  assign zro = result[15:0] == 32'h00000000 ? 1'b1 : 1'b0;
  // Zero
  assign LOG_OUT = result;
  assign SREG_OUT = {1'b0,zro,2'b00};
endmodule

module decoder(
input wire [7:0] instruction_in,
output reg s_exec_nop,
output reg s_exec_sta,
output reg s_exec_lda,
output reg s_exec_add,
output reg s_exec_or,
output reg s_exec_shr,
output reg s_exec_shl,
output reg s_exec_mul,
output reg s_exec_and,
output reg s_exec_not,
output reg s_exec_jmp,
output reg s_exec_jn,
output reg s_exec_jz,
output reg s_exec_hlt
);
//decod_instr : out  STD_LOGIC_VECTOR(3 downto 0);
  // decod_instr	<= instruction_in(7 downto 4);
  // 0000 -> NOP
  // 0001 -> STA
  // 0010 -> LDA
  // 0011 -> ADD
  // 0100 -> OR
  // 0101 -> AND
  // 0110 -> NOT
  // 0111 -> SHR
  // 1000 -> JMP
  // 1001 -> JN
  // 1010 -> JZ
  // 1011 -> SHL
  // 1100 -> MUL
  // 1111 -> HLT
  always @(instruction_in[7:4]) begin
    // Set all as zero
    s_exec_nop <= 1'b0;
    s_exec_sta <= 1'b0;
    s_exec_lda <= 1'b0;
    s_exec_add <= 1'b0;
    s_exec_or <= 1'b0;
    s_exec_and <= 1'b0;
    s_exec_not <= 1'b0;
    s_exec_jmp <= 1'b0;
    s_exec_jn <= 1'b0;
    s_exec_jz <= 1'b0;
    s_exec_hlt <= 1'b0;
    s_exec_shr <= 1'b0;
    s_exec_shl <= 1'b0;
    s_exec_mul <= 1'b0;
    if((instruction_in[7:4] == 4'b0000)) begin
      // NOP
      s_exec_nop <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0001)) begin
      // STA
      s_exec_sta <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0010)) begin
      // LDA
      s_exec_lda <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0011)) begin
      // ADD
      s_exec_add <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0100)) begin
      // OR
      s_exec_or <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0101)) begin
      // AND
      s_exec_and <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0110)) begin
      // NOT
      s_exec_not <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1000)) begin
      // JMP
      s_exec_jmp <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1001)) begin
      // JN
      s_exec_jn <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1010)) begin
      // JZ
      s_exec_jz <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1111)) begin
      // HLT
      s_exec_hlt <= 1'b1;
      // Challenge instructions SHR, SHL e MUL
    end
    else if((instruction_in[7:4] == 4'b0111)) begin
      // SHR
      s_exec_shr <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1011)) begin
      // SHL
      s_exec_shl <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1100)) begin
      // MUL
      s_exec_mul <= 1'b1;
      // End challenge
    end
  end
endmodule

