module Freq_Div(
input wire in_rst,
input wire in_clk,
output reg out_time_base
);
// constants
parameter FOSC = 100000000;
parameter FDIV = 1000000;
parameter CTAMAX = FOSC / FDIV;  // internal signals
reg [31:0] cont;
  always @(posedge in_Rst, posedge in_Clk) begin
    if(in_rst == 1'b1) begin
      cont <= 0;
    end else begin
      if(cont == CTAMAX) begin
        cont <= 0;
        out_time_base <= 1'b1;
      end
      else begin
        cont <= cont + 1;
        out_time_base <= 1'b0;
      end
    end
  end
endmodule

