module sync_buffer(
input wire rst,
input wire clk,
input wire en,
input wire din,
output wire dout,
output reg redge,
output reg fedge
);
parameter RSTDEF=1'b1;
// reset, RSTDEF active
// clock, rising edge
// enable, high active
// data bit, input
// data bit, output
// rising  edge on din detected
// falling edge on din detected
// sync_buffer waits 2**CNTLEN clock cycles until it puts din on dout
// length of counter
parameter CNTLEN = 5;  // after 32 clock cycles value is applied
parameter CNTFULL = 1'b1;  // counter until input is applied to output
reg [CNTLEN - 1:0] cnt = 1'b0;  // debounced input signal
reg din_deb = 1'b0;  // output signal of flipflop1
wire q1 = 1'b0;  // output signal of flipflop2
wire q2 = 1'b0;
  // signal is chained through 2 flipflops to sync with clock
  flipflop #(
      .RSTDEF(RSTDEF))
  flipflop1(
      .rst(rst),
    .clk(clk),
    .en(en),
    .d(din),
    .q(q1));
  flipflop #(
      .RSTDEF(RSTDEF))
  flipflop2(
      .rst(rst),
    .clk(clk),
    .en(en),
    .d(q1),
    .q(q2));
  // connect debounced signal to out port
  assign dout = din_deb;
  always @(posedge rst, posedge clk) begin
    if(rst == RSTDEF) begin
      din_deb <= 1'b0;
      cnt <= {((CNTLEN - 1)-(0)+1){1'b0}};
      redge <= 1'b0;
      fedge <= 1'b0;
    end else begin
      redge <= 1'b0;
      fedge <= 1'b0;
      if(en == 1'b1) begin
        // only start counting if q2 != din_deb
        // signal has to stay stable for 2**CNTLEN cycles before it is
        // applied. Otherwise counter will be reset again.
        if(din_deb == q2) begin
          cnt <= {((CNTLEN - 1)-(0)+1){1'b0}};
        end
        else begin
          cnt <= cnt + 1;
        end
        if(cnt == CNTFULL) begin
          // counter is full, apply signal and set if it is a rising
          // or falling edge
          redge <= q2;
          fedge <=  ~q2;
          din_deb <= q2;
        end
      end
    end
  end
endmodule

