module top_nto1_ddr_se_rx(
input wire reset,
input wire [7:0] datain,
input wire clkin1,
input wire clkin2,
output wire [63:0] dummy_out
);
// reset (active high)
// single ended data inputs
// TWO single ended clock input
// dummy outputs
// constants for serdes factor and number of IO pins
parameter S = 8;  // Set the serdes factor to 8
parameter D = 8;  // Set the number of inputs and outputs
parameter DS = (D * S) - 1;  // Used for bus widths = serdes factor * number of inputs - 1
wire rst;
wire [DS:0] rxd;  // Data from serdeses
reg [DS:0] rxr;  // signalistered Data from serdeses
reg state;
reg bslip;
reg [3:0] count;
wire rxioclkp;
wire rxioclkn;
wire rx_serdesstrobe;
wire rx_bufg_x1;
  assign rst = reset;
  // active high reset pin
  assign dummy_out = rxr;
  // Clock Input. Generate ioclocks via BUFIO2
  serdes_1_to_n_clk_ddr_s8_se #(
      .S(S))
  inst_clkin(
      .clkin1(clkin1),
    .clkin2(clkin2),
    .rxioclkp(rxioclkp),
    .rxioclkn(rxioclkn),
    .rx_serdesstrobe(rx_serdesstrobe),
    .rx_bufg_x1(rx_bufg_x1));
  // Data Inputs
  serdes_1_to_n_data_ddr_s8_se #(
      .S(S),
    .D(D),
    .USE_PD(TRUE))
  inst_datain(
      .use_phase_detector(1'b1),
    // '1' enables the phase detector logic
    .datain(datain),
    .rxioclkp(rxioclkp),
    .rxioclkn(rxioclkn),
    .rxserdesstrobe(rx_serdesstrobe),
    .gclk(rx_bufg_x1),
    .bitslip(bslip),
    .reset(rst),
    .data_out(rxd),
    .debug_in(2'b00),
    .debug(/* open */));
  always @(posedge rx_bufg_x1, posedge rst) begin : P2
  // example bitslip logic, if required
    if(rst == 1'b1) begin
      state <= 1'b0;
      bslip <= 1'b1;
      count <= 4'b0000;
    end else begin
      if(state == 1'b0) begin
        if(rxd[63:60] != 4'b0011) begin
          bslip <= 1'b1;
          // bitslip needed
          state <= 1'b1;
          count <= 4'b0000;
        end
      end
      else if(state == 1'b1) begin
        bslip <= 1'b0;
        // bitslip low
        count <= count + 1;
        if(count == 4'b1111) begin
          state <= 1'b0;
        end
      end
    end
  end
  always @(posedge rx_bufg_x1) begin : P1
  // process received data
    rxr <= rxd;
  end
