module CNE_02000_good(
input wire i_Clock,
input wire i_Reset_n,
input wire i_Start,
input wire i_Stop
);
// Clock input
// Reset input
// Start counter signal
// Stop counter signal
parameter c_Length = 1'b1;  // How long we should count
//CODE
parameter [1:0]
  init = 0,
  loading = 1,
  enabled = 2,
  finished = 3;
  // Enumerated type for state encoding
reg [1:0] sm_State;  // State signal
//CODE
reg Raz;  // Load the length value and initialize the counter
reg Enable;  // Counter enable signal
reg [3:0] Length;  // Counter length for counting
wire End_Count;  // End signal of counter
  // A simple counter with loading length and enable signal
  Counter Counter(
      .i_Clock(i_Clock),
    .i_Reset_n(i_Reset_n),
    .i_Raz(Raz),
    .i_Enable(Enable),
    .i_Length(Length),
    .o_Done(End_Count));
  // FSM process controlling the counter. Start or stop it in function of the input (i_Start & i_Stop), 
  // load the length value, and wait for it to finish
  always @(posedge i_Reset_n, posedge i_Clock) begin
    if((i_Reset_n == 1'b0)) begin
      sm_State <= init;
    end else begin
      case(sm_State)
      init : begin
        // Set the length value
        Length <= c_Length;
        sm_State <= loading;
      end
      loading : begin
        // Load the counter and initialize it
        Raz <= 1'b1;
        sm_State <= enabled;
      end
      enabled : begin
        // Start or stop counting depending on inputs until it finishes
        Raz <= 1'b0;
        if((End_Count == 1'b0)) begin
          Enable <= i_Start ^  ~i_Stop;
          sm_State <= Enabled;
        end
        else begin
          Enable <= 1'b0;
          sm_State <= finished;
        end
      end
      default : begin
        sm_State <= init;
      end
      endcase
    end
  end
endmodule

module hex2seg(
input wire clk,
input wire en,
input wire [3:0] hex,
output wire [6:0] seg
);
// Clock of the display (30-100Hz?)
// HEX number you want to display 0-F
// 7-Segment output, bit0=segment a, .. ,bit 6=segment g. Output is modulated with clock!
reg [6:0] segments;  // '1' for every segment that should be switched on (not modulated)
wire [6:0] clockvec;  // just "clk" on every bit of the vector
  assign clockvec = {7{clk}};
  // "Copy" clock to every bit of the vector
  // Switch on the hex char, and decide which segments should be on
  always @(*) begin
    case(hex)
      4'b0000 : segments <= 7'b0111111;
  //Ziffer 0
      4'b0001 : segments <= 7'b0000110;
  //Ziffer 1
      4'b0010 : segments <= 7'b1011011;
  //Ziffer 2
      4'b0011 : segments <= 7'b1001111;
  //Ziffer 3
      4'b0100 : segments <= 7'b1100110;
  //Ziffer 4
      4'b0101 : segments <= 7'b1101101;
  //Ziffer 5
      4'b0110 : segments <= 7'b1111101;
  //Ziffer 6
      4'b0111 : segments <= 7'b0000111;
  //Ziffer 7
      4'b1000 : segments <= 7'b1111111;
  //Ziffer 8
      4'b1001 : segments <= 7'b1101111;
  //Ziffer 9
      4'b1010 : segments <= 7'b1110111;
  //Ziffer A
      4'b1011 : segments <= 7'b1111100;
  //Ziffer B
      4'b1100 : segments <= 7'b0111001;
  //Ziffer C
      4'b1101 : segments <= 7'b1011110;
  //Ziffer D
      4'b1110 : segments <= 7'b1111001;
  //Ziffer E
      4'b1111 : segments <= 7'b1110001;
  //Ziffer F
      default : segments <= 7'b0000000;
    endcase
  end
  // Assign seg (modulated). 
  // All segments which must be on, will have the inverse polarity of the clock. The others go with the clock. We can use xor for that.
  assign seg = en == 1'b1 ? clockvec ^ segments : clockvec;
endmodule

