module control_path(
input wire start,
output reg complete,
input wire clk,
input wire reset,
output reg [0:36] T
);
parameter [2:0]
  init = 0,
  S0 = 1,
  S1 = 2,
  S2 = 3,
  S3 = 4,
  S4 = 5,
  S5 = 6,
  done = 7;
reg [2:0] nQ = init; reg [2:0] Q = init;
  always @(posedge clk) begin
    Q <= nQ;
  end
  always @(reset, start, Q) begin
    nQ <= Q;
    if((reset == 1'b1)) begin
      nQ <= init;
    end
    else begin
      case(Q)
      init : begin
        if((start == 1'b1)) begin
          nQ <= S0;
        end
      end
      S0 : begin
        nQ <= S1;
      end
      S1 : begin
        nQ <= S2;
      end
      S2 : begin
        nQ <= S3;
      end
      S3 : begin
        nQ <= S4;
      end
      S4 : begin
        nQ <= S5;
      end
      S5 : begin
        nQ <= done;
      end
      done : begin
        nQ <= init;
      end
      default : begin
        nQ <= init;
      end
      endcase
    end
  end
  always @(Q) begin
    T <= {37{1'b0}};
    complete <= 1'b0;
    case(Q)
    init : begin
      T[12] <= 1'b1;
      T[13] <= 1'b1;
      T[14] <= 1'b1;
      T[15] <= 1'b1;
    end
    S0 : begin
      T[16] <= 1'b1;
      T[17] <= 1'b1;
      T[6:8] <= 3'b110;
      T[9:11] <= 3'b111;
      T[23:24] <= 2'b10;
      T[29:30] <= 2'b01;
      T[35:35] <= 1'b1;
    end
    S1 : begin
      T[18] <= 1'b1;
      T[19] <= 1'b1;
      T[23:24] <= 2'b10;
      T[29:30] <= 2'b01;
      T[31:31] <= 1'b1;
      T[32:32] <= 1'b1;
    end
    S2 : begin
      T[20] <= 1'b1;
      T[21] <= 1'b1;
      T[22] <= 1'b1;
      T[0:2] <= 3'b100;
      T[3:5] <= 3'b101;
      T[23:24] <= 2'b11;
      T[25:26] <= 2'b01;
      T[27:28] <= 2'b10;
      T[29:30] <= 2'b10;
      T[31:31] <= 1'b1;
      T[32:32] <= 1'b1;
      T[33:33] <= 1'b1;
      T[34:34] <= 1'b1;
      T[36:36] <= 1'b1;
    end
    S3 : begin
      T[16] <= 1'b1;
      T[17] <= 1'b1;
      T[3:5] <= 3'b111;
      T[25:26] <= 2'b10;
      T[27:28] <= 2'b01;
      T[33:33] <= 1'b1;
      T[34:34] <= 1'b1;
    end
    S4 : begin
      T[21] <= 1'b1;
      T[25:26] <= 2'b10;
    end
    S5 : begin
      T[20] <= 1'b1;
      T[0:2] <= 3'b110;
      T[23:24] <= 2'b01;
      T[25:26] <= 2'b01;
    end
    done : begin
      complete <= 1'b1;
    end
    endcase
  end
endmodule

