module rgb565_to_rgb888(
input wire [15:0] rgb_565,
output reg [23:0] rgb_888
);
wire [7:0] red = 8'b00000000; wire [7:0] green = 8'b00000000; wire [7:0] blue = 8'b00000000;
  assign red[4:0] = rgb_565[15:11];
  assign green[5:0] = rgb_565[10:5];
  assign blue[4:0] = rgb_565[4:0];
  always @(red, green, blue) begin : P1
    reg [7:0] r_1, r_2, g_1, g_2, b_1, b_2;
    r_1 = (red) << 3;
    r_2 = (red) >> 2;
    g_1 = (green) << 2;
    g_2 = (green) >> 4;
    b_1 = (blue) << 3;
    b_2 = (blue) << 2;
    rgb_888[23:16] <= r_1 | r_2;
    rgb_888[15:8] <= g_1 | g_2;
    rgb_888[7:0] <= b_1 | b_1;
  end
endmodule

module PS2_RX(
input wire CLK,
input wire RST,
input wire PS2C,
input wire PS2D,
output wire [7:0] PS2RX_DATA,
output reg PS2RX_VALID
);
// Vychozi hodinovy signal
// Vychozi reset
// Hodinovy signal z PS2 portu
// Seriova vstupni data z PS2 portu
// Vystupni data
// Data jsou pripravena na vycteni
wire ps2_valid;
reg parity_valid;
wire parity_ctrl;
reg parity_ps2;
reg [3:0] ps2_bit_count;
reg [7:0] sig_ps2rx_data;
reg [7:0] sig_ps2rx_data2;
parameter [1:0]
  idle = 0,
  dps = 1,
  load = 2;
reg [1:0] present_st;
reg [1:0] next_st;
  //--------------------------------------------------------------------------
  // FALLING EDGE DETECTOR OF PS/2 CLOCK
  //--------------------------------------------------------------------------
  FALLING_EDGE_DETECTOR falling_edge_detector_i(
      .CLK(CLK),
    .VSTUP(PS2C),
    .VYSTUP(ps2_valid));
  //--------------------------------------------------------------------------
  // PS2 RX FSM
  //--------------------------------------------------------------------------
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      present_st <= idle;
    end else begin
      present_st <= next_st;
    end
  end
  // Rozhodovaci cast stavoveho automatu
  always @(present_st, PS2D, ps2_valid, ps2_bit_count) begin
    case(present_st)
    idle : begin
      if((ps2_valid == 1'b1 && PS2D == 1'b0)) begin
        next_st <= dps;
      end
      else begin
        next_st <= idle;
      end
    end
    dps : begin
      if(((ps2_bit_count) == 11)) begin
        next_st <= load;
      end
      else begin
        next_st <= dps;
      end
    end
    load : begin
      next_st <= idle;
    end
    endcase
  end
  // Vystupni cast stavoveho automatu
  always @(present_st, parity_valid) begin
    case(present_st)
    idle : begin
      PS2RX_VALID <= 1'b0;
    end
    dps : begin
      PS2RX_VALID <= 1'b0;
    end
    load : begin
      PS2RX_VALID <= parity_valid;
    end
    endcase
  end
  //--------------------------------------------------------------------------
  // BIT COUNTER
  //--------------------------------------------------------------------------
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      ps2_bit_count <= {4{1'b0}};
    end else begin
      if(((ps2_bit_count) == 11)) begin
        ps2_bit_count <= {4{1'b0}};
      end
      else if((ps2_valid == 1'b1)) begin
        ps2_bit_count <= ps2_bit_count + 1;
      end
    end
  end
  //--------------------------------------------------------------------------
  // PS/2 DATA
  //--------------------------------------------------------------------------
  always @(posedge CLK) begin
    if((ps2_valid == 1'b1)) begin
      if(((ps2_bit_count) > 0 && (ps2_bit_count) < 9)) begin
        sig_ps2rx_data[7:0] <= {PS2D,sig_ps2rx_data[7:1]};
      end
    end
  end
  always @(posedge CLK) begin
    if((ps2_valid == 1'b1)) begin
      if(((ps2_bit_count) == 9)) begin
        parity_ps2 <= PS2D;
      end
    end
  end
  // Propagace PS2 dat na vystup
  always @(posedge CLK) begin
    if(((ps2_bit_count) == 10)) begin
      sig_ps2rx_data2 <= sig_ps2rx_data;
    end
  end
  assign PS2RX_DATA = sig_ps2rx_data2;
  //--------------------------------------------------------------------------
  // DATA PARITY CHECK
  //--------------------------------------------------------------------------
  assign parity_ctrl = sig_ps2rx_data2[7] ^ sig_ps2rx_data2[6] ^ sig_ps2rx_data2[5] ^ sig_ps2rx_data2[4] ^ sig_ps2rx_data2[3] ^ sig_ps2rx_data2[2] ^ sig_ps2rx_data2[1] ^ sig_ps2rx_data2[0] ^ 1'b1;
  // Kontrola parity
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      parity_valid <= 1'b0;
    end else begin
      if((parity_ctrl == parity_ps2)) begin
        parity_valid <= 1'b1;
      end
      else begin
        parity_valid <= 1'b0;
      end
    end
  end
endmodule

module Control(
input wire [5:0] Opcode,
output reg RegDst,
output reg Branch,
output reg MemRead,
output reg MemtoReg,
output reg MemWrite,
output reg ALUSrc,
output reg RegWrite,
output reg Jump,
output reg [1:0] ALUOp
);
  always @(Opcode) begin
    case(Opcode)
    6'b000000 : begin
      //add/sub
      RegDst <= 1'b1;
      Branch <= 1'b0;
      MemRead <= 1'b0;
      MemtoReg <= 1'b0;
      MemWrite <= 1'b0;
      ALUSrc <= 1'b0;
      RegWrite <= 1'b1;
      Jump <= 1'b0;
      ALUOp <= 2'b10;
    end
    6'b100011 : begin
      //lw
      RegDst <= 1'b0;
      Branch <= 1'b0;
      MemRead <= 1'b1;
      MemtoReg <= 1'b1;
      MemWrite <= 1'b0;
      ALUSrc <= 1'b1;
      RegWrite <= 1'b1;
      Jump <= 1'b0;
      ALUOp <= 2'b00;
    end
    6'b000100 : begin
      //beq
      RegDst <= 1'b0;
      Branch <= 1'b1;
      MemRead <= 1'b0;
      MemtoReg <= 1'b0;
      MemWrite <= 1'b0;
      ALUSrc <= 1'b0;
      RegWrite <= 1'b0;
      Jump <= 1'b0;
      ALUOp <= 2'b01;
    end
    6'b000010 : begin
      //j
      RegDst <= 1'b0;
      Branch <= 1'b0;
      MemRead <= 1'b0;
      MemtoReg <= 1'b0;
      MemWrite <= 1'b0;
      ALUSrc <= 1'b0;
      RegWrite <= 1'b0;
      Jump <= 1'b1;
      ALUOp <= 2'b00;
    end
    6'b101011 : begin
      //sw
      RegDst <= 1'b0;
      Branch <= 1'b0;
      MemRead <= 1'b0;
      MemtoReg <= 1'b0;
      MemWrite <= 1'b1;
      ALUSrc <= 1'b1;
      RegWrite <= 1'b0;
      Jump <= 1'b0;
      ALUOp <= 2'b00;
    end
    default : begin
    end
    endcase
  end
endmodule

