module delay(
input wire rst,
input wire clk,
input wire din,
output wire dout
);
parameter RSTDEF=1'b0;
parameter [31:0] DELAYLEN=8;
// reset, RSTDEF active
// clock, rising edge
// data in
// data out
// vector through which signal is chained
reg [DELAYLEN - 1:0] dvec = 1'b0;
  assign dout = dvec[DELAYLEN - 1];
  always @(posedge rst, posedge clk) begin
    if(rst == RSTDEF) begin
      dvec <= {((DELAYLEN - 1)-(0)+1){1'b0}};
    end else begin
      dvec <= {dvec[DELAYLEN - 2:0],din};
    end
  end
endmodule

module pic(
input wire CLK,
input wire [7:0] IRQ_in,
output reg [7:0] IAK_out,
output reg IRQ_out,
input wire IAK_in,
input wire CS,
input wire RW,
input wire [31:0] Din,
output reg [31:0] Dout,
input wire [2:0] DTYPE,
output wire RDY
);
// 0: read, 1: write
reg enable_back = 1'b0;
reg enable_forward = 1'b1;
reg [31:0] int_device;
  always @(posedge CLK) begin
    if((enable_back == enable_forward)) begin
      if((IAK_in == 1'b1)) begin
        // disable PIC
        enable_back <=  ~enable_back;
        // select the interrupting device and handle IAK
        if((IRQ_in[0] == 1'b1)) begin
          int_device <= 32'h00000000;
          IAK_out <= 8'b00000001;
        end
        else if((IRQ_in[1] == 1'b1)) begin
          int_device <= 32'h00000001;
          IAK_out <= 8'b00000010;
        end
        else if((IRQ_in[2] == 1'b1)) begin
          int_device <= 32'h00000002;
          IAK_out <= 8'b00000100;
        end
        else if((IRQ_in[3] == 1'b1)) begin
          int_device <= 32'h00000003;
          IAK_out <= 8'b00001000;
        end
        else if((IRQ_in[4] == 1'b1)) begin
          int_device <= 32'h00000004;
          IAK_out <= 8'b00010000;
        end
        else if((IRQ_in[5] == 1'b1)) begin
          int_device <= 32'h00000005;
          IAK_out <= 8'b00100000;
        end
        else if((IRQ_in[6] == 1'b1)) begin
          int_device <= 32'h00000006;
          IAK_out <= 8'b01000000;
        end
        else begin
          int_device <= 32'h00000007;
          IAK_out <= 8'b10000000;
        end
        // stop IRQ request
        IRQ_out <= 1'b0;
      end
      else if((IRQ_in == 8'h00)) begin
        // no pending IRQ request
        IRQ_out <= 1'b0;
      end
      else begin
        // an IRQ is pending
        IRQ_out <= 1'b1;
      end
    end
    else begin
      // stop IAK
      IAK_out <= 8'b00000000;
    end
    // bus interface
    if((CS == 1'b1)) begin
      if((RW == 1'b1)) begin
        if((Din[0] == 1'b1)) begin
          // enable
          enable_forward <= enable_back;
        end
        else begin
          // disable
          enable_forward <=  ~enable_back;
        end
      end
      else begin
        Dout <= int_device;
      end
    end
    else begin
      Dout <= 32'h00000000;
    end
  end
endmodule

