module blink(
input wire [6:0] binIn,
output reg [6:0] binOut,
input wire clk,
input wire reset,
output reg outLed
);
reg [6:0] last_binIn;
reg [31:0] counter;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      counter <= 0;
      last_binIn <= 7'b0000000;
    end else begin
      outLed <= 1'b1;
      if((last_binIn == 7'b1100011 && !(binIn == 7'b1100011))) begin
        outLed <= 1'b0;
        if((counter == 8 || counter == 10 || counter == 12)) begin
          binOut <= {7{1'b1}};
          counter <= counter + 1;
        end
        else if((counter == 7 || counter == 9 || counter == 11 || counter == 13)) begin
          binOut <= 7'b1111110;
          counter <= counter + 1;
        end
        else begin
          binOut <= {7{1'b1}};
          counter <= 0;
        end
      end
      else begin
        if((!(last_binIn == binIn))) begin
          last_binIn <= binIn;
          counter <= 0;
        end
        if((counter == 1 || counter == 3 || counter == 5)) begin
          binOut <= {7{1'b1}};
          counter <= counter + 1;
        end
        else if((counter == 0 || counter == 2 || counter == 4 || counter == 6)) begin
          binOut <= binIn;
          counter <= counter + 1;
        end
        else begin
          binOut <= {7{1'b1}};
        end
      end
    end
  end
endmodule

