module frame_builder(
input wire [31:0] player,
input wire [31:0] obst_low,
input wire [31:0] obst_high,
input wire [31:0] obst_pos,
output wire [31:0] obst_id,
input wire [31:0] lin,
input wire [31:0] col,
input wire enable,
output wire [2:0] colour
);
parameter [31:0] H_RES=128;
parameter [31:0] V_RES=96;
parameter [31:0] N_OBST=4;
parameter [31:0] P_POS=20;
// Player Horizontal position
// Game state data.
reg [2:0] c;
reg [31:0] id;
  // Process that determines the colour of each pixel.
  always @(lin, col) begin : P1
    reg [31:0] curr_id;
    // Background colour is black
    c <= 3'b000;
    // Determine current obstacle.
    curr_id = col / (H_RES / N_OBST);
    id <= curr_id;
    if(lin == player && col == P_POS) begin
      // Player colour
      c <= 3'b110;
    end
    else if(col == (curr_id * (H_RES / N_OBST) + obst_pos)) begin
      // Obstacles colour
      if(lin < obst_high) begin
        // Top obstacle
        c <= 3'b010;
      end
      else if(lin > ((V_RES - 1) - obst_low)) begin
        // Bottom obstacle
        c <= 3'b010;
      end
    end
  end
  assign colour = enable == 1'b1 ? c : 3'bZZZ;
  assign obst_id = enable == 1'b1 ? id : 0;
endmodule

