      .size(32))
  reg_3(
      .clock(clock),
    .enable(enable3),
    .reset(reset),
    .data(reg3),
    .output(output3));
  assign enable0 = (( ~sel[0]) & ( ~sel[1])) & enable;
  assign enable1 = (sel[0] & ( ~sel[1])) & enable;
  assign enable2 = (( ~sel[0]) & sel[1]) & enable;
  assign enable3 = (sel[0] & sel[1]) & enable;
