module led(
input wire clk,
input wire tick_1M,
input wire reset,
input wire [7:0] brightness,
input wire invert,
output wire led
);
// system clock (48MHz)
// 1MHz tick
// reset (sync)
// led pwm value
// invert output
// led output
reg [7:0] count;  //pwm counter
reg led_int;
  always @(posedge clk) begin
    if((reset == 1'b1)) begin
      count <= {8{1'b0}};
      //clear counter
      led_int <= 1'b0;
      //turn off led
    end
    else if((tick_1M == 1'b1)) begin
      //increment counter
      count <= count + 1;
      //update led
      if((count == (brightness))) begin
        led_int <= 1'b1;
      end
      else if((count == 0)) begin
        led_int <= 1'b0;
      end
    end
  end
  assign led = led_int ^ invert;
endmodule

module ServoControl(
input wire [7:0] Angulo,
input wire Clk,
input wire Rst,
output wire Senal
);
//Embedded Signal needed by Frequency divider
//Frequency divider counter declaration
parameter MaxCta = 2000000;  //definir valor de acuerda a la tableta
reg [31:0] ContDiv;  //Embedded Signal neede for DivDisp
wire [31:0] PulsoNecesario;
  assign PulsoNecesario = 100000 + (Angulo) * 392;
  //Frequency divider section
  always @(posedge Rst, posedge Clk) begin
      //Asinchronous Reset
    if((Rst == 1'b1)) begin
      ContDiv <= 0;
    end else begin
      //Check if counter has reached the final count
      if((ContDiv == MaxCta)) begin
        ContDiv <= 0;
      end
      else begin
        //no ha transcurrido un segundo, seguir incrementando el contador
        ContDiv <= ContDiv + 1;
      end
    end
  end
  assign Senal = ContDiv < PulsoNecesario ? 1'b1 : 1'b0;
endmodule

