module control(
input wire c_clk,
input wire c_rst,
input wire c_cpu_wr,
input wire c_cpu_sc,
input wire parity,
output reg c_address_enable,
output reg c_wr_enable,
output reg wr_strobe
);
//stored_enable: out  STD_LOGIC;
parameter [3:0]
  idle = 0,
  hold0 = 1,
  load_addr = 2,
  hold1 = 3,
  strobe = 4,
  hold2 = 5,
  hold3 = 6,
  write_data = 7,
  write_data2 = 8;
reg [3:0] nState; reg [3:0] cState;
  always @(posedge c_clk, posedge c_rst) begin
    if((c_rst == 1'b1)) begin
      cState <= idle;
    end else begin
      cState <= nState;
    end
  end
  always @(cState, parity, c_cpu_sc, c_cpu_wr) begin : P1
  //, parity, c_cpu_sc
    case(cState)
    idle : begin
      c_address_enable <= 1'b1;
      c_wr_enable <= 1'b0;
      //stored_enable<= '0';
      wr_strobe <= 1'b1;
      if((c_cpu_sc == 1'b1) && (parity == 1'b1) && (c_cpu_wr == 1'b1)) begin
        // if still '1' 
        nState <= hold0;
      end
      else begin
        nState <= idle;
      end
    end
    hold0 : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b0;
      //stored_enable<= '0';
      wr_strobe <= 1'b1;
      //if (c_cpu_wr = '1') then
      nState <= load_addr;
      //	else nState <= idle;
      //	end if;
    end
    load_addr : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b0;
      //stored_enable<= '0';
      wr_strobe <= 1'b1;
      nState <= hold1;
    end
    hold1 : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b0;
      //stored_enable<= '0';
      wr_strobe <= 1'b1;
      nState <= strobe;
    end
    strobe : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b0;
      //stored_enable<= '1';
      wr_strobe <= 1'b0;
      nState <= hold2;
    end
    hold2 : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b0;
      //stored_enable <= '0';
      wr_strobe <= 1'b1;
      nState <= hold3;
    end
    hold3 : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b0;
      wr_strobe <= 1'b1;
      nState <= write_data;
    end
    write_data : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b1;
      wr_strobe <= 1'b1;
      nState <= idle;
    end
    default : begin
      c_address_enable <= 1'b0;
      c_wr_enable <= 1'b0;
      wr_strobe <= 1'b1;
      nState <= idle;
    end
    endcase
  end
endmodule

module controller(
output reg register_load,
output reg register_shift,
input wire clk,
input wire rst
);
parameter [2:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3,
  S4 = 4;
reg [2:0] current_state;
reg [2:0] next_state;
  // next to current
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      current_state <= S0;
    end else begin
      current_state <= next_state;
    end
  end
  // next based on state
  always @(current_state) begin
    case(current_state)
    S0 : begin
      next_state <= S1;
      register_load <= 1'b1;
      register_shift <= 1'b0;
    end
    S1 : begin
      next_state <= S2;
      register_load <= 1'b0;
      register_shift <= 1'b1;
    end
    S2 : begin
      next_state <= S3;
    end
    S3 : begin
      next_state <= S4;
    end
    S4 : begin
      next_state <= S0;
    end
    endcase
  end
endmodule

module debounce(
input wire clk,
input wire button,
output reg result
);
parameter [31:0] counter_size;
//! counter size (19 bits gives 10.5ms with 50MHz clock)
//! input clock
//! input signal to be debounced
//! debounced signal
reg [1:0] flipflops;  //input flip flops
wire counter_set;  //sync reset to zero
reg [counter_size:0] counter_out = 1'b0;  //counter output 
  assign counter_set = flipflops[0] ^ flipflops[1];
  //determine when to start/reset counter
  always @(posedge clk) begin
    flipflops[0] <= button;
    flipflops[1] <= flipflops[0];
    if((counter_set == 1'b1)) begin
      //reset counter because input is changing
      counter_out <= {((counter_size)-(0)+1){1'b0}};
    end
    else if((counter_out[counter_size] == 1'b0)) begin
      //stable input time is not yet met
      counter_out <= counter_out + 1;
    end
    else begin
      //stable input time is met
      result <= flipflops[1];
    end
  end
endmodule

module rc_counter(
input wire Clk,
input wire RSTn,
input wire En,
output reg [31:0] ColPos,
output reg [31:0] RowPos
);
parameter [31:0] num_cols=512;
parameter [31:0] num_rows=512;
  always @(posedge RSTn, posedge Clk, posedge En) begin : P1
    reg [31:0] ColPos_var = 0;
    reg [31:0] RowPos_var = 0;
    if(RSTn == 1'b0) begin
      ColPos_var =  -1;
      ColPos <= 0;
      RowPos_var = 0;
      RowPos <= 0;
    end else begin
      if(En == 1'b1) begin
        ColPos_var = ColPos_var + 1;
        if(ColPos_var == num_cols) begin
          RowPos_var = RowPos_var + 1;
          ColPos_var = 0;
          if(RowPos_var == num_rows) begin
            RowPos_var = 0;
          end
        end
        ColPos <= ColPos_var;
        RowPos <= RowPos_var;
      end
    end
  end
endmodule

module conv_24to8(
input wire clk_in,
input wire reset_in,
input wire [23:0] data24_in,
input wire valid24_in,
output reg ready24_out,
output reg [7:0] data8_out,
output reg valid8_out,
input wire ready8_in
);
// System clock & reset
// 24-bit data coming in
// 8-bit data going out
parameter [1:0]
  S_WRITE_MSB = 0,
  S_WRITE_MID = 1,
  S_WRITE_LSB = 2;
reg [1:0] state = S_WRITE_MSB;
reg [1:0] state_next;
reg [7:0] lsb = 1'b0;
reg [7:0] lsb_next;
reg [7:0] mid = 1'b0;
reg [7:0] mid_next;
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      state <= S_WRITE_MSB;
      lsb <= {8{1'b0}};
      mid <= {8{1'b0}};
    end
    else begin
      state <= state_next;
      lsb <= lsb_next;
      mid <= mid_next;
    end
  end
  // Next state logic
  always @(state, lsb, mid, data24_in, valid24_in, ready8_in) begin
    state_next <= state;
    valid8_out <= 1'b0;
    lsb_next <= lsb;
    mid_next <= mid;
    case(state)
        // Write the LSB and return to MSB:
    S_WRITE_LSB : begin
      ready24_out <= 1'b0;
      // not ready for data from 24-bit side
      data8_out <= lsb;
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE_MSB;
      end
      // Write the mid byte and move on to LSB
    end
    S_WRITE_MID : begin
      ready24_out <= 1'b0;
      // not ready for data from 24-bit side
      data8_out <= mid;
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE_LSB;
      end
      // When a word arrives, write the MSB and move on to mid byte:				
    end
    default : begin
      ready24_out <= ready8_in;
      // ready for data from 24-bit side
      data8_out <= data24_in[23:16];
      valid8_out <= valid24_in;
      if((valid24_in == 1'b1 && ready8_in == 1'b1)) begin
        mid_next <= data24_in[15:8];
        lsb_next <= data24_in[7:0];
        state_next <= S_WRITE_MID;
      end
    end
    endcase
  end
endmodule

