module pos_loader(
input wire clock,
input wire reset,
input wire enable,
input wire start,
input wire [15:0] data_in,
output reg go_ram,
input wire busy_ram,
input wire RxRdy_ram,
output reg RxRdy_out,
output reg [15:0] x,
output reg [15:0] y,
output reg [15:0] z
);
// Para indicar qué coordenada se está cargando
parameter [1:0]
  IDLE = 0,
  X_st = 1,
  Y_st = 2,
  Z_st = 3;
reg [1:0] estado = IDLE;
  always @(posedge clock, posedge reset, posedge start, posedge RxRdy_ram, posedge busy_ram) begin
      // reset
    if(reset == 1'b1) begin
      go_ram <= 1'b0;
      estado <= IDLE;
    end else begin
      RxRdy_out <= 1'b0;
      go_ram <= 1'b0;
      if(enable == 1'b1) begin
        case(estado)
        IDLE : begin
          if(start == 1'b1 && busy_ram == 1'b0) begin
            // pido X
            go_ram <= 1'b1;
            estado <= X_st;
          end
        end
        X_st : begin
          if(RxRdy_ram == 1'b1) begin
            // Ya X, pido Y
            x <= data_in;
            go_ram <= 1'b1;
            estado <= Y_st;
          end
        end
        Y_st : begin
          if(RxRdy_ram == 1'b1) begin
            // Ya Y, pido Z
            y <= data_in;
            go_ram <= 1'b1;
            estado <= Z_st;
          end
        end
        Z_st : begin
          if(RxRdy_ram == 1'b1) begin
            // Ya Z, vuelvo a IDLE
            z <= data_in;
            RxRdy_out <= 1'b1;
            // Posición lista
            go_ram <= 1'b1;
            estado <= X_st;
            //-
          end
        end
        endcase
      end
    end
  end
endmodule

