  assign nextPrevSclEnable = sclEnable;
  assign scl = sclReg;
  always @(posedge clk, posedge resetN) begin
    if(resetN == 1'b0) begin
      count <= {9{1'b0}};
      prevSclEnable <= 1'b0;
      sclReg <= 1'b0;
    end else begin
      count <= nextcount;
      prevSclEnable <= nextPrevSclEnable;
      sclReg <= nextSclReg;
    end
  end
  always @(count, sclEnable, sclSpeed, sclReg) begin
    tsrEnable <= 1'b0;
    nextSclReg <= 1'b0;
    // Polarity = 0
    if(sclEnable == 1'b1) begin
      // scl
      if(sclSpeed == 1'b0) begin
        //slow mode
        if(((count) >= 0) && ((count) < ((spiDivSlow) / 2))) begin
          nextSclReg <= 1'b1;
        end
        else if((count) >= ((spiDivSlow) / 2)) begin
          nextSclReg <= 1'b0;
        end
      end
      else begin
        //fast mode
        if(((count) >= 0) && ((count) < ((spiDivFast) / 2))) begin
          nextSclReg <= 1'b1;
        end
        else if((count) >= ((spiDivFast) / 2)) begin
          nextSclReg <= 1'b0;
        end
      end
    end
    // Phase = 0;
    if(sclEnable == 1'b1) begin
      // tsrEnable logic
      if(sclSpeed == 1'b0) begin
        //slow mode
        if((count) == ((spiDivSlow) / 2)) begin
          tsrEnable <= 1'b1;
        end
      end
      else begin
        //fast mode
        if((count) == ((spiDivFast) / 2)) begin
          tsrEnable <= 1'b1;
        end
      end
    end
  end
  assign nextcount = sclEnable == 1'b0 ? {9{1'b0}} : count >= (spiDivSlow - 1) && sclSpeed == 1'b0 ? {9{1'b0}} : count >= (spiDivFast - 1) && sclSpeed == 1'b1 ? {9{1'b0}} : count + 1;
endmodule

module alu(
input wire [31:0] a,
input wire [31:0] b,
input wire [5:0] opcode,
output reg [31:0] result,
input wire clk
);
  always @(a, b, opcode) begin : P1
  // Action when a, b, or opcode is changed.
    case(opcode)
    6'b000100 : begin
      result <= a + b;
    end
    6'b001110 : begin
      result <= a - b;
    end
    6'b001111 : begin
      result <= ( ( $signed(a) < 0 ) ? -$signed(a) : a );
    end
    6'b001000 : begin
      result <=  -a;
    end
    6'b000010 : begin
      result <= ( ( $signed(b) < 0 ) ? -$signed(b) : b );
    end
    6'b001010 : begin
      result <=  -b;
    end
    6'b001100 : begin
      result <= a | b;
    end
    6'b000110 : begin
      result <=  ~a;
    end
    6'b000011 : begin
      result <=  ~b;
    end
    6'b001011 : begin
      result <= a & b;
    end
    6'b000101 : begin
      result <= a ^ b;
    end
    default : begin
      result <= 32'bXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX;
      // Output X(unknown) when opcode is invalid,
    end
    endcase
    // and register will enable written protection automatic.
  end
endmodule

