module PS2KEYBOARD(
input wire CLK,
input wire RST,
input wire PS2_KBCLK,
input wire PS2_KBDAT,
output wire [7:0] KEYCODE,
output reg CODE_ENABLE
);
parameter [3:0]
  START_BIT = 0,
  DATA0 = 1,
  DATA1 = 2,
  DATA2 = 3,
  DATA3 = 4,
  DATA4 = 5,
  DATA5 = 6,
  DATA6 = 7,
  DATA7 = 8,
  PARITY_BIT = 9,
  STOP_BIT = 10;
reg [1:0] PS2CLK;
reg [7:0] KEYCODE_BUF;
reg [3:0] STATE;
wire PARITY;
  assign KEYCODE = KEYCODE_BUF;
  assign PARITY = KEYCODE_BUF[0] ^ KEYCODE_BUF[1] ^ KEYCODE_BUF[2] ^ KEYCODE_BUF[3] ^ KEYCODE_BUF[4] ^ KEYCODE_BUF[5] ^ KEYCODE_BUF[6] ^ KEYCODE_BUF[7] ^ 1'b1;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b0)) begin
      PS2CLK <= 2'b00;
      STATE <= START_BIT;
      KEYCODE_BUF <= {8{1'b0}};
      CODE_ENABLE <= 1'b0;
    end else begin
      PS2CLK <= {PS2CLK[0],PS2_KBCLK};
      if((PS2CLK == 2'b10)) begin
        case(STATE)
        START_BIT : begin
          if((PS2_KBDAT == 1'b0)) begin
            STATE <= DATA0;
            CODE_ENABLE <= 1'b0;
          end
          else begin
            STATE <= START_BIT;
          end
        end
        DATA0 : begin
          STATE <= DATA1;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        DATA1 : begin
          STATE <= DATA2;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        DATA2 : begin
          STATE <= DATA3;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        DATA3 : begin
          STATE <= DATA4;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        DATA4 : begin
          STATE <= DATA5;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        DATA5 : begin
          STATE <= DATA6;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        DATA6 : begin
          STATE <= DATA7;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        DATA7 : begin
          STATE <= PARITY_BIT;
          KEYCODE_BUF <= {PS2_KBDAT,KEYCODE_BUF[7:1]};
        end
        PARITY_BIT : begin
          if((PS2_KBDAT == PARITY)) begin
            STATE <= STOP_BIT;
          end
          else begin
            STATE <= START_BIT;
          end
        end
        STOP_BIT : begin
          if((PS2_KBDAT == 1'b1)) begin
            STATE <= START_BIT;
            CODE_ENABLE <= 1'b1;
          end
          else begin
            STATE <= START_BIT;
          end
        end
        endcase
      end
    end
  end
endmodule

