module ledc8x8(
input wire SMCLK,
input wire RESET,
output reg [0:7] ROW,
output reg [0:7] LED
);
// 5 bitovy citac
reg [4:0] citac = 1'b0;
wire clock_enable;
reg [2:0] row_cnt = 1'b0;
  // Delic frekvencie
  always @(posedge SMCLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      citac <= {5{1'b0}};
    end else begin
      citac <= citac + 1;
    end
  end
  // Paralelne priradenie
  assign clock_enable = citac == 5'b11111 ? 1'b1 : 1'b0;
  //-------------------------------------------------
  // Citac aktualneho riadku, inkrementuje sa len ked
  // delic frekvencie prave preteka
  always @(posedge SMCLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      row_cnt <= {3{1'b0}};
    end else begin
      if(clock_enable == 1'b1) begin
        row_cnt <= row_cnt + 1;
      end
    end
  end
  //-------------------------------------------------
  // one-hot convertor
  always @(*) begin
    case(row_cnt)
      3'b000 : ROW <= 8'b10000000;
      3'b001 : ROW <= 8'b01000000;
      3'b010 : ROW <= 8'b00100000;
      3'b011 : ROW <= 8'b00010000;
      3'b100 : ROW <= 8'b00001000;
      3'b101 : ROW <= 8'b00000100;
      3'b110 : ROW <= 8'b00000010;
      3'b111 : ROW <= 8'b00000001;
      default : ROW <= 8'bXXXXXXXX;
    endcase
  end
  // samotne rozsvietenie diody podla aktualneho riadku
  // invertovane !
  always @(*) begin
    case(row_cnt)
      3'b000 : LED <= 8'b00011111;
      3'b001 : LED <= 8'b01101111;
      3'b010 : LED <= 8'b01101111;
      3'b011 : LED <= 8'b01101110;
      3'b100 : LED <= 8'b00000100;
      3'b101 : LED <= 8'b11101010;
      3'b110 : LED <= 8'b11101110;
      3'b111 : LED <= 8'b11101110;
      default : LED <= 8'bXXXXXXXX;
    endcase
  end
endmodule

module shift(
input wire [1:0] mode,
input wire [4:0] shift,
input wire [31:0] input,
output wire carry,
output wire [31:0] output
);
//0:LSLS 1:LSRS 2:ASRS 3:RORS
wire [31:0] R1s;
wire [31:0] R2s;
wire [31:0] R4s;
wire [31:0] R8s;
wire [31:0] R16s;
wire [31:0] R1;
wire [31:0] R2;
wire [31:0] R4;
wire [31:0] R8;
wire [31:0] R16;
wire input1s;
wire [1:0] input2s;
wire [3:0] input4s;
wire [7:0] input8s;
wire [15:0] input16s;
  assign carry = shift == 4'b0000 ? 1'b0 : 1'b1;
  //input(32 - conv_integer(shift)) when mode = "00" else
  //input(conv_integer(shift) - 1);
  assign input1s = mode == 2'b10 ? input[31] : mode == 2'b11 ? input[0] : 1'b0;
  assign R1s = mode == 2'b00 ? {input[30:0],input1s} : {input1s,input[31:1]};
  assign input2s = mode == 2'b11 ? R1[1:0] : {input1s,input1s};
  assign R2s = mode == 2'b00 ? {R1[29:0],input2s} : {input2s,R1[31:2]};
  assign input4s = mode == 2'b11 ? R2[3:0] : {input2s,input2s};
  assign R4s = mode == 2'b00 ? {R2[27:0],input4s} : {input4s,R2[31:4]};
  assign input8s = mode == 2'b11 ? R4[7:0] : {input4s,input4s};
  assign R8s = mode == 2'b00 ? {R4[23:0],input8s} : {input8s,R4[31:8]};
  assign input16s = mode == 2'b11 ? R8[15:0] : {input8s,input8s};
  assign R16s = mode == 2'b00 ? {R8[15:0],input16s} : {input16s,R8[31:16]};
  assign R1 = shift[0] == 1'b0 ? input : R1s;
  assign R2 = shift[1] == 1'b0 ? R1 : R2s;
  assign R4 = shift[2] == 1'b0 ? R2 : R4s;
  assign R8 = shift[3] == 1'b0 ? R4 : R8s;
  assign output = shift[4] == 1'b0 ? R8 : R16s;
endmodule

