module vga_game_dec(
input wire [1:0] game_state,
input wire [7:0] element,
output reg [5:0] elemidx
);
// Estado do jogo
// Tipo do elemento e indice na ROM
wire w; wire e; wire f; wire c; wire m;
  // Vitoria
  assign w = game_state[0];
  // Fim do jogo
  assign e = game_state[1];
  // Elemento mina
  assign m = element[3:0] == 4'b1111 ? 1'b1 : 1'b0;
  assign f = element[4];
  assign c = element[5];
  always @(w, e, f, c, m) begin
    if((( ~c &  ~e &  ~f &  ~w) | ( ~c &  ~f &  ~m &  ~w)) == 1'b1) begin
      // Bloco fechado
      elemidx <= 6'b001001;
    end
    else if(((c & e &  ~f &  ~m) | (c &  ~f &  ~m &  ~w)) == 1'b1) begin
      // Bloco de numero
      elemidx <= {2'b00,element[3:0]};
    end
    else if((c &  ~f & m &  ~w) == 1'b1) begin
      // Explosao
      elemidx <= 6'b001101;
    end
    else if((( ~c & e & f & m) | ( ~c & e & m & w) | ( ~c &  ~e & f &  ~w)) == 1'b1) begin
      // Bandeira
      elemidx <= 6'b001010;
    end
    else if(( ~c & e &  ~f & m &  ~w) == 1'b1) begin
      // Mina
      elemidx <= 6'b001011;
    end
    else if(( ~c & e & f &  ~m &  ~w) == 1'b1) begin
      // Bandeira errada
      elemidx <= 6'b001100;
    end
    else begin
      // Situacao de erro
      elemidx <= 6'b001110;
    end
  end
endmodule

