module synchronizer(
input wire iArst,
input wire iClk,
input wire iAsync,
output wire oSync
);
//! Stages
parameter [31:0] gStages=2;
parameter gInit=cInactivated;
//! Asynchronous reset
//! Clock
//! Asynchronous input
//! Synchronous output
//! Meta registers used to synchronize input signal
reg [gStages - 1:0] metaReg;  //! Meta registers next
wire [gStages - 1:0] metaReg_next;
  // handle wrong stage generic
  // output last synchronizer stage
  assign oSync = metaReg[(gStages - 1)];
  // assign asynchronous signal to metaRegisters
  assign metaReg_next = {metaReg[(gStages - 1) - 1:0],iAsync};
  always @(posedge iArst, posedge iClk) begin
    if(iArst == cActivated) begin
      metaReg <= {((gStages - 1)-(0)+1){gInit}};
    end else begin
      metaReg <= metaReg_next;
    end
  end
endmodule

