module turnsignals_anim(
input wire clk,
input wire reset,
input wire en,
output reg [2:0] led_out
);
parameter [2:0]
  s0 = 0,
  s1 = 1,
  s2 = 2,
  s3 = 3,
  s4 = 4,
  s5 = 5;
reg [2:0] s;
  always @(posedge clk) begin : P1
    reg [31:0] i = 0;
    if((reset == 1'b1) || (en == 1'b0)) begin
      s <= s0;
      led_out <= 3'b000;
    end
    else begin
      case(s)
      s0 : begin
        i = i + 1;
        led_out <= 3'b000;
        if((i == 6250000)) begin
          i = 0;
          s <= s1;
        end
      end
      s1 : begin
        i = i + 1;
        led_out <= 3'b100;
        if((i == 6250000)) begin
          i = 0;
          s <= s2;
        end
      end
      s2 : begin
        i = i + 1;
        led_out <= 3'b110;
        if((i == 6250000)) begin
          s <= s3;
          i = 0;
        end
      end
      s3 : begin
        i = i + 1;
        led_out <= 3'b111;
        if((i == 6250000)) begin
          i = 0;
          s <= s4;
        end
      end
      s4 : begin
        i = i + 1;
        led_out <= 3'b011;
        if((i == 6250000)) begin
          i = 0;
          s <= s5;
        end
      end
      s5 : begin
        i = i + 1;
        led_out <= 3'b001;
        if((i == 6250000)) begin
          i = 0;
          s <= s0;
        end
      end
      endcase
    end
  end
endmodule

