module PS2(
input wire CLK,
input wire RST,
input wire PS2C,
input wire PS2D,
output wire KEY_W,
output wire KEY_S,
output wire KEY_A,
output wire KEY_D,
output wire KEY_SPACE
);
// Vychozi hodinovy signal
// Vychozi synchronni reset
// Hodinovy signal z PS2 portu
// Seriova vstupni data z PS2 portu
// Znaci ze byla stisknuta klavesa W
// Znaci ze byla stisknuta klavesa S
// Znaci ze byla stisknuta klavesa A
// Znaci ze byla stisknuta klavesa D
// Znaci ze byla stisknuta klavesa SPACE
wire sig_ps2c_deb;
wire sig_ps2rx_valid;
wire [7:0] sig_ps2rx_data;
wire [7:0] sig_key_code;
reg sig_key_w;
reg sig_key_s;
reg sig_key_a;
reg sig_key_d;
reg sig_key_space;
  //--------------------------------------------------------------------
  // Propojeni vnitrnich podkomponent
  //--------------------------------------------------------------------
  // PS2 Debouncer
  DEBOUNCER ps2_debouncer_i(
      .CLK(CLK),
    .RST(RST),
    .DIN(PS2C),
    .DOUT(sig_ps2c_deb));
  // Prijem seriovych dat z PS2
  PS2_RX ps2_rx_1(
      .CLK(CLK),
    .RST(RST),
    .PS2C(sig_ps2c_deb),
    .PS2D(PS2D),
    .PS2RX_DATA(sig_ps2rx_data),
    .PS2RX_VALID(sig_ps2rx_valid));
  // Ziskani kodu klavesy
  KB_CODE kb_code_1(
      .CLK(CLK),
    .RST(RST),
    .PS2RX_DATA(sig_ps2rx_data),
    .PS2RX_VALID(sig_ps2rx_valid),
    .KEY_CODE(sig_key_code));
  //--------------------------------------------------------------------
  // Generovani vystupnich signalu
  //--------------------------------------------------------------------
  // Generovani signalu o zmacknute klavesy W
  always @(posedge CLK) begin
    if((RST == 1'b1)) begin
      sig_key_w <= 1'b0;
    end
    else if((sig_key_code == 8'h1D)) begin
      sig_key_w <= 1'b1;
    end
    else begin
      sig_key_w <= 1'b0;
    end
  end
  RISING_EDGE_DETECTOR rised1(
      .CLK(CLK),
    .VSTUP(sig_key_w),
    .VYSTUP(KEY_W));
  // Generovani signalu o zmacknute klavesy S
  always @(posedge CLK) begin
    if((RST == 1'b1)) begin
      sig_key_s <= 1'b0;
    end
    else if((sig_key_code == 8'h1B)) begin
      sig_key_s <= 1'b1;
    end
    else begin
      sig_key_s <= 1'b0;
    end
  end
  RISING_EDGE_DETECTOR rised2(
      .CLK(CLK),
    .VSTUP(sig_key_s),
    .VYSTUP(KEY_S));
  // Generovani signalu o zmacknute klavesy A
  always @(posedge CLK) begin
    if((RST == 1'b1)) begin
      sig_key_a <= 1'b0;
    end
    else if((sig_key_code == 8'h1C)) begin
      sig_key_a <= 1'b1;
    end
    else begin
      sig_key_a <= 1'b0;
    end
  end
  RISING_EDGE_DETECTOR rised3(
      .CLK(CLK),
    .VSTUP(sig_key_a),
    .VYSTUP(KEY_A));
  // Generovani signalu o zmacknute klavesy D
  always @(posedge CLK) begin
    if((RST == 1'b1)) begin
      sig_key_d <= 1'b0;
    end
    else if((sig_key_code == 8'h23)) begin
      sig_key_d <= 1'b1;
    end
    else begin
      sig_key_d <= 1'b0;
    end
  end
  RISING_EDGE_DETECTOR rised4(
      .CLK(CLK),
    .VSTUP(sig_key_d),
    .VYSTUP(KEY_D));
  // Generovani signalu o zmacknute klavesy SPACE
  always @(posedge CLK) begin
    if((RST == 1'b1)) begin
      sig_key_space <= 1'b0;
    end
    else if((sig_key_code == 8'h29)) begin
      sig_key_space <= 1'b1;
    end
    else begin
      sig_key_space <= 1'b0;
    end
  end
  RISING_EDGE_DETECTOR rised5(
      .CLK(CLK),
    .VSTUP(sig_key_space),
    .VYSTUP(KEY_SPACE));
endmodule

module WB(
input wire clock,
input wire reset,
input wire [31:0] data_from_MEM,
input wire [5:0] cntl_from_ID,
output wire [31:0] rfile_write_data_to_ID,
output wire [4:0] rfile_write_addr_to_ID,
output wire rfile_write_e_to_ID
);
//These two outputs also used for
//forwarding logic
////Component Declarations\\--
//Generic rising-edge-triggered register
//\\Component Declarations//--
////Signal Declarations\\--
//These signals are used between the three registers that make up the three-stage
//buffer that delays the incoming control signals from the instruction decoder
wire [5:0] buffer_1_2;
wire [5:0] buffer_2_3;
wire [5:0] buffer_out;  //\\Signal Declarations//--
  //The input register for the stage
  GenReg #(
      .size(32))
  in_reg(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(data_from_MEM),
    .output(rfile_write_data_to_ID));
  //The buffer's registers
  GenReg #(
      .size(6))
  buf1(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(cntl_from_ID),
    .output(buffer_1_2));
  GenReg #(
      .size(6))
  buf2(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(buffer_1_2),
    .output(buffer_2_3));
  GenReg #(
      .size(6))
  buf3(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(buffer_2_3),
    .output(buffer_out));
  //These signals, the write address and write enable for the register
  //file, go straight to the ID stage. The data to be written is simply
  //the output of the input register
  assign rfile_write_addr_to_ID = buffer_out[5:1];
  assign rfile_write_e_to_ID = buffer_out[0];
endmodule

module alu(
input wire clk,
input wire [7:0] operandA,
input wire [7:0] operandB,
input wire [2:0] operatorSelect,
input wire carryIn,
output reg carryOut,
output reg zeroOut,
output reg signOut,
output reg parityOut,
output reg auxCarryOut,
output reg [7:0] result
);
  always @(negedge clk) begin : P1
    reg [8:0] tempResult;
      //if (rising_edge(clk)) then -- not sure this needs to be clocked really
    // not sure this needs to be clocked really
    auxCarryOut <= 1'b0;
    carryOut <= 1'b0;
    if((operatorSelect[2:1] == 2'b00)) begin
      // add / add with carry 
      tempResult = ({operandA[7],operandA}) + ({operandB[7],operandB});
      //auxCarryOut <= (((operandA(3 downto 0) + operandB(3 downto 0)) >> 4 and 1
      if(((operatorSelect[0] & carryIn) == 1'b1)) begin
        tempResult = (tempResult) + 1;
      end
      carryOut <= tempResult[8];
      result <= tempResult[7:0];
      // auxcar = (((opra[3:0]+oprb[3:0]) >> 4) & 1'b1) ? 1'b1 : 1'b0 ; 
      // auxcar = (((opra[3:0]+oprb[3:0]+cin) >> 4) & 1'b1) ? 1'b1 : 1'b0;
      auxCarryOut <= 1'b0;
    end
    else if((operatorSelect[2:1] == 2'b01)) begin
      // sub / sub with borrow
      tempResult = ({operandA[7],operandA}) - ({operandB[7],operandB});
      if(((operatorSelect[0] & carryIn) == 1'b1)) begin
        tempResult = (tempResult) - 1;
      end
      carryOut <= tempResult[8];
      result <= tempResult[7:0];
      auxCarryOut <= 1'b0;
    end
    else if((operatorSelect == 3'b100)) begin
      // and
      tempResult = {1'b0,operandA & operandB};
      result <= operandA & operandB;
    end
    else if((operatorSelect == 3'b101)) begin
      // xor
      tempResult = {1'b0,operandA ^ operandB};
      result <= operandA ^ operandB;
    end
    else if((operatorSelect == 3'b110)) begin
      // or
      tempResult = {1'b0,operandA | operandB};
      result <= operandA | operandB;
    end
    else begin
      // "111" -- compare 
      tempResult = ({operandA[7],operandA}) - ({operandB[7],operandB});
      carryOut <= tempResult[8];
      result <= operandA;
      //tempResult(7 downto 0);
      auxCarryOut <= 1'b0;
    end
    if(((tempResult) == 0)) begin
      zeroOut <= 1'b1;
    end
    else begin
      zeroOut <= 1'b0;
    end
    signOut <= tempResult[7];
    parityOut <=  ~(tempResult[7] ^ tempResult[6] ^ tempResult[5] ^ tempResult[4] ^ tempResult[3] ^ tempResult[2] ^ tempResult[1] ^ tempResult[0]);
  end
endmodule

