output reg [1:0] AluCtr
);
//AluOp(1) es 1
  always @(AluOp, funct) begin
    // tipo R
    AluCtr <= 2'b00;
    if(AluOp == 3'b010) begin
      if(funct == 6'b100000) begin
        //suma
        AluCtr <= 2'b10;
      end
      else if(funct == 6'b100010) begin
        //resta
        AluCtr <= 2'b11;
      end
      else if(funct == 6'b100100) begin
        //and
        AluCtr <= 2'b00;
      end
      else if(funct == 6'b100101) begin
        //or
        AluCtr <= 2'b01;
      end
      // beq,bne,bgt,blt,subi
    end
    else if(AluOp == 3'b001) begin
      //resta
      AluCtr <= 2'b11;
      // lw, sw, addi
    end
    else if(AluOp == 3'b000) begin
      //suma
      AluCtr <= 2'b10;
      //	andi
    end
    else if(AluOp == 3'b100) begin
      AluCtr <= 2'b00;
      // ori
    end
    else if(AluOp == 3'b101) begin
      AluCtr <= 2'b01;
    end
    else begin
      AluCtr <= 2'b10;
    end
  end
