module bin2bcd_12bit(
input wire [11:0] binIN,
output reg [3:0] ones,
output reg [3:0] tens,
output reg [3:0] hundreds,
output reg [3:0] thousands
);
  always @(binIN) begin : P1
  // temporary variable
    reg [11:0] temp;
  // variable to store the output BCD number
  // organized as follows
  // thousands = bcd(15 downto 12)
  // hundreds = bcd(11 downto 8)
  // tens = bcd(7 downto 4)
  // units = bcd(3 downto 0)
    reg [15:0] bcd = 1'b0;
  // by
  // https://en.wikipedia.org/wiki/Double_dabble
    // zero the bcd variable
    bcd = {1{1'b0}};
    // read input into temp variable
    temp[11:0] = binIN;
    // cycle 12 times as we have 12 input bits
    // this could be optimized, we dont need to check and add 3 for the 
    // first 3 iterations as the number can never be >4
    for (i=0; i <= 11; i = i + 1) begin
      if(bcd[3:0] > 4) begin
        bcd[3:0] = bcd[3:0] + 3;
      end
      if(bcd[7:4] > 4) begin
        bcd[7:4] = bcd[7:4] + 3;
      end
      if(bcd[11:8] > 4) begin
        bcd[11:8] = bcd[11:8] + 3;
      end
      // thousands can't be >4 for a 12-bit input number
      // so don't need to do anything to upper 4 bits of bcd
      // shift bcd left by 1 bit, copy MSB of temp into LSB of bcd
      bcd = {bcd[14:0],temp[11]};
      // shift temp left by 1 bit
      temp = {temp[10:0],1'b0};
    end
    // set outputs
    ones <= bcd[3:0];
    tens <= bcd[7:4];
    hundreds <= bcd[11:8];
    thousands <= bcd[15:12];
  end
endmodule

module FSM_control(
input wire CLK,
input wire RESET,
input wire END_BONUS,
input wire END_TIME,
input wire ENTER,
input wire TARGET,
output reg [1:0] SEL_DISP,
output reg [4:0] STATESS,
output reg SEL_LED,
output reg SET_ROLL,
output reg EN_TIME,
output reg RST
);
//Definir arquitetura
parameter [1:0]
  E0 = 0,
  E1 = 1,
  E2 = 2,
  E3 = 3;
reg [1:0] EA; reg [1:0] PE;
  //Processo 1 para Clock e Reset
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b0) begin
      EA <= E0;
    end else begin
      EA <= PE;
    end
  end
  //Processo 2 para estados
  always @(EA, TARGET, ENTER, END_TIME, END_BONUS) begin
    case(EA)
        //ESTADO INIT
    E0 : begin
      STATESS <= 5'b00000;
      SEL_LED <= 1'b0;
      SEL_DISP <= 2'b10;
      SET_ROLL <= 1'b0;
      EN_TIME <= 1'b0;
      RST <= 1'b0;
      if(ENTER == 1'b0) begin
        PE <= E1;
      end
      else if(ENTER == 1'b1) begin
        PE <= E0;
      end
      //ESTADO SETUP
    end
    E1 : begin
      STATESS <= 5'b00001;
      SEL_LED <= 1'b0;
      SEL_DISP <= 2'b01;
      SET_ROLL <= 1'b0;
      EN_TIME <= 1'b0;
      RST <= 1'b1;
      if(ENTER == 1'b0) begin
        PE <= E2;
      end
      else if(ENTER == 1'b1) begin
        PE <= E1;
      end
      //ESTADO GAME
    end
    E2 : begin
      STATESS <= 5'b00010;
      SEL_LED <= 1'b1;
      SEL_DISP <= 2'b00;
      SET_ROLL <= 1'b1;
      EN_TIME <= 1'b1;
      RST <= 1'b1;
      if(TARGET == 1'b1 || END_TIME == 1'b1 || END_BONUS == 1'b1) begin
        PE <= E3;
      end
      else begin
        PE <= E2;
      end
      //ESTADO END
    end
    E3 : begin
      STATESS <= 5'b00011;
      SEL_LED <= 1'b0;
      SEL_DISP <= 2'b11;
      SET_ROLL <= 1'b0;
      EN_TIME <= 1'b0;
      RST <= 1'b1;
      if(ENTER == 1'b0) begin
        PE <= E0;
      end
      else if(ENTER == 1'b1) begin
        PE <= E3;
      end
    end
    endcase
  end
endmodule

module alu32(
input wire [31:0] ia,
input wire [31:0] ib,
input wire [4:0] shamt,
input wire shdir,
output wire C,
input wire [3:0] control,
output wire [31:0] output,
output wire Z,
output wire S,
output wire V
);
wire [32:0] temp_c;
wire [31:0] temp_o;
wire [31:0] temp_less;
wire [31:0] temp_out;
wire [31:0] temp_shift;
wire sh_en;
  genvar i;
  generate for (i=0; i <= 30; i = i + 1) begin: alu
      //generate 32 1-bit adders for alu32 entity
    alu1 alu(
          .ia(ia[i]),
      .ib(ib[i]),
      .less(temp_less[i]),
      .cout(temp_c[i + 1]),
      // Cin will be previous value temp signal 
      .cin(temp_c[i]),
      // cout will feed into cin
      .control(control),
      .output(temp_o[i]));
  end
  endgenerate
  alu1_last alu32(
      .ia(ia[31]),
    .ib(ib[31]),
    .less(temp_less[31]),
    .cout(temp_c[32]),
    // Cin will be previous value temp signal 
    .cin(temp_c[31]),
    // cout will feed into cin
    .control(control),
    .slt_en(temp_less[0]),
    .output(temp_o[31]));
  shifter shift(
      .ib(ib),
    .shdir(shdir),
    .shamt(shamt),
    .q(temp_shift));
  mux_gen #(
      .width(32))
  mux(
      .in0(temp_o),
    .in1(temp_shift),
    .sel(sh_en),
    .output(temp_out));
  assign temp_c[0] = control[2];
  // Set cin to first adder to 0. Leaving it blank will result in an 'X' for sum(0)
  assign C = temp_c[32];
  // Z flag
  assign Z =  ~(temp_out[31] | temp_out[30] | temp_out[29] | temp_out[28] | temp_out[27] | temp_out[26] | temp_out[25] | temp_out[24] | temp_out[23] | temp_out[22] | temp_out[21] | temp_out[20] | temp_out[19] | temp_out[18] | temp_out[17] | temp_out[16] | temp_out[15] | temp_out[14] | temp_out[13] | temp_out[12] | temp_out[11] | temp_out[10] | temp_out[9] | temp_out[8] | temp_out[7] | temp_out[6] | temp_out[5] | temp_out[4] | temp_out[3] | temp_out[2] | temp_out[1] | temp_out[0]);
  // S flag 
  assign S = temp_out[31];
  // V flag
  assign V = temp_c[32] ^ temp_c[31];
  // shift enable 
  assign sh_en =  ~control[3] &  ~control[2] & control[1] & control[0];
  assign temp_less[31:1] = {31{1'b0}};
  assign output = temp_out;
endmodule

