module divisor2(
input wire reset,
input wire clk,
output wire reloj,
input wire velocidad0,
input wire velocidad1
);
// reloj de entrada de la entity superior
// reloj que se utiliza en los process del programa principal
reg [24:0] cuenta;
reg clk_aux;
  assign reloj = clk_aux;
  always @(posedge reset, posedge clk) begin
    if((reset == 1'b1)) begin
      cuenta <= {25{1'b0}};
    end else begin
      if(velocidad0 == 1'b0 && velocidad1 == 1'b0) begin
        if((cuenta == 25'b1111111111111111111111111)) begin
          clk_aux <=  ~clk_aux;
          cuenta <= {25{1'b0}};
        end
        else begin
          cuenta <= cuenta + 1'b1;
        end
      end
      else if(velocidad0 == 1'b1 && velocidad1 == 1'b0) begin
        if((cuenta == 25'b0111111111111111111111111)) begin
          clk_aux <=  ~clk_aux;
          cuenta <= {25{1'b0}};
        end
        else begin
          cuenta <= cuenta + 1'b1;
        end
      end
      else if(velocidad0 == 1'b0 && velocidad1 == 1'b1) begin
        if((cuenta == 25'b0011111111111111111111111)) begin
          clk_aux <=  ~clk_aux;
          cuenta <= {25{1'b0}};
        end
        else begin
          cuenta <= cuenta + 1'b1;
        end
      end
      else begin
        if((cuenta == 25'b0001111111111111111111111)) begin
          clk_aux <=  ~clk_aux;
          cuenta <= {25{1'b0}};
        end
        else begin
          cuenta <= cuenta + 1'b1;
        end
      end
    end
  end
endmodule

