module BLOCK_WORD_COUNTER(
input wire CLK,
input wire RESET,
input wire RESTART,
input wire BW_RDY,
output wire EOB_MARK,
output reg [15:0] BLOCK_HEADER_OUT,
output wire BLOCK_HEADER_OUT_RDY,
output wire BLOCK_COUNT_RDY
);
parameter [31:0] GBTid=0;
parameter [31:0] egroupID=0;
parameter [31:0] epathID=0;
// Block Word Ready Enable
//-----------
// End Of Block flag to send the trailer
//> sending block header
//> sending block header
//-----------
reg [9:0] count_sig = 1'b0;
reg [4:0] seq_num = 1'b0;
wire SOB_MARK; wire SOB_MARK0; wire seqCNTcase; wire seqCNTtrig; wire EOB_MARK_sig;
reg SOB_MARK1 = 1'b0; reg blockCountRdy = 1'b0;
wire [31:0] BLOCK_HEADER;  // two first words are always sent in the beginning of a block transmittion
parameter count_offset = 10'b0000000001;  //(others => '0'); 
  always @(posedge CLK) begin
    if(RESET == 1'b1 || RESTART == 1'b1) begin
      blockCountRdy <= 1'b0;
    end
    else if(SOB_MARK1 == 1'b1) begin
      blockCountRdy <= 1'b1;
    end
  end
  //
  assign BLOCK_COUNT_RDY = blockCountRdy;
  //------------------------------------------------------------
  // counting block words, data partition
  //------------------------------------------------------------
  always @(posedge CLK) begin
    if(RESET == 1'b1) begin
      count_sig <= {10{1'b0}};
    end
    else begin
      if(EOB_MARK_sig == 1'b1 || RESTART == 1'b1) begin
        count_sig <= count_offset;
      end
      else if(BW_RDY == 1'b1) begin
        count_sig <= count_sig + 1;
      end
    end
  end
  //------------------------------------------------------------
  // End Of Block trigger out for the 
  // sub-chunk data manager to insert a trailer
  //------------------------------------------------------------
  assign EOB_MARK_sig = (count_sig == BLOCK_WORDn) ? 1'b1 : 1'b0;
  // there is one more space left, for the trailer
  assign EOB_MARK = EOB_MARK_sig;
  // to output
  //------------------------------------------------------------
  // Block Sequence counter, 5 bit
  //------------------------------------------------------------
  assign seqCNTcase = EOB_MARK_sig | RESTART;
  pulse_pdxx_pwxx #(
      .pd(2),
    .pw(1))
  seqCNTtrig_pulse(
      CLK,
    seqCNTcase,
    seqCNTtrig);
  //
  always @(posedge CLK) begin
    if(RESET == 1'b1) begin
      seq_num <= {5{1'b0}};
    end
    else begin
      if(seqCNTtrig == 1'b1) begin
        seq_num <= seq_num + 1;
      end
    end
  end
  //------------------------------------------------------------
  // Start Of Block Mark to insert block header
  //------------------------------------------------------------
  assign SOB_MARK = (count_sig == count_offset) ? 1'b1 : 1'b0;
  //------------------------------------------------------------
  // Start Of Block produces 2 triggers 
  // to send 2 words, as header is 32bit
  //------------------------------------------------------------
  pulse_pdxx_pwxx #(
      .pd(0),
    .pw(1))
  SOB_MARK0_PULSE(
      CLK,
    SOB_MARK,
    SOB_MARK0);
  // FIFO WE to send word0
  always @(posedge CLK) begin
    SOB_MARK1 <= SOB_MARK0;
    // FIFO WE to send word1
  end
  //
  // [0xABCD_16]  [[block_counter_5]  [GBTid_5   egroupID_3   epathID_3]]
  assign BLOCK_HEADER = {16'b1010101111001101,seq_num,GBTid,egroupID,epathID};
  //
  always @(posedge CLK) begin
    if(SOB_MARK0 == 1'b1) begin
      BLOCK_HEADER_OUT <= BLOCK_HEADER[31:16];
    end
    else begin
      BLOCK_HEADER_OUT <= BLOCK_HEADER[15:0];
    end
  end
  //
  assign BLOCK_HEADER_OUT_RDY = SOB_MARK0 | SOB_MARK1;
    //
endmodule

module EPROC_OUT4_direct(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
output wire getDataTrig,
input wire [9:0] edataIN,
input wire edataINrdy,
output wire [3:0] EdataOUT
);
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
parameter zeros4bit = 1'b0;
reg [7:0] byte_r;
reg request_cycle_cnt = 1'b0; reg send_count = 1'b0;
reg send_out_trig = 1'b0;
wire inp_request_trig; wire inp_request_trig_out;
  //-----------------------------------------------------------------------------------------
  // input handshaking, request cycle 2 CLKs
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(rst == 1'b1) begin
      request_cycle_cnt <= 1'b0;
    end
    else begin
      request_cycle_cnt <=  ~request_cycle_cnt;
    end
  end
  //
  assign inp_request_trig = request_cycle_cnt;
  //
  pulse_pdxx_pwxx #(
      .pd(0),
    .pw(1))
  inp_reques1clk(
      bitCLKx4,
    inp_request_trig,
    inp_request_trig_out);
  assign getDataTrig = inp_request_trig_out;
  //
  always @(posedge bitCLK) begin
    send_out_trig <= inp_request_trig;
  end
  //
  //-----------------------------------------------------------------------------------------
  // sending out 2 bits @ bitCLK
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(send_out_trig == 1'b1) begin
      byte_r <= edataIN[7:0];
    end
  end
  //
  always @(posedge bitCLK) begin
    if(send_out_trig == 1'b1) begin
      send_count <= 1'b0;
    end
    else begin
      send_count <=  ~send_count;
    end
  end
  //
  MUX2_Nbit #(
      .N(4))
  outmux(
      .data0(byte_r[3:0]),
    .data1(byte_r[7:4]),
    .sel(send_count),
    .data_out(EdataOUT));
    //
endmodule

module clk2Hz(
input wire CLK_IN,
input wire RST,
output wire CLK_OUT
);
reg clkdv = 1'b0;
reg [31:0] counter = 0;
  always @(posedge RST, posedge CLK_IN) begin
    if((RST == 1'b1)) begin
      clkdv <= 1'b0;
      counter <= 0;
    end else begin
      if((counter == 25000000)) begin
        if((clkdv == 1'b0)) begin
          clkdv <= 1'b1;
        end
        else begin
          clkdv <= 1'b0;
        end
        counter <= 0;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
  assign CLK_OUT = clkdv;
endmodule

