module char_mem_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
parameter [31:0] C_ROM_SYNTH=1;
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [14:0] ADDRA = 1'b0;
reg [14:0] ADDRA_R = 1'b0;
wire [0:0] DOUTA;
wire CHECKER_EN = 1'b0;
wire CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
