module clock_generator(
input wire clock,
input wire reset_n,
input wire enable,
output wire clock_out
);
parameter [31:0] GV_CLOCK_DIV=50;
reg [to_log2[GV_CLOCK_DIV] - 1:0] counter; wire [to_log2[GV_CLOCK_DIV] - 1:0] counter_nxt;
  always @(posedge clock, posedge reset_n) begin
    if(reset_n == 1'b0) begin
      counter <= {((to_log2[GV_CLOCK_DIV] - 1)-(0)+1){1'b0}};
    end else begin
      counter <= counter_nxt;
    end
  end
  assign counter_nxt = (counter == (GV_CLOCK_DIV - 1)) || (enable == 1'b0) ? {((to_log2[GV_CLOCK_DIV] - 1)-(0)+1){1'b0}} : counter + 1;
  assign clock_out = (counter >= (GV_CLOCK_DIV / 2)) && (enable == 1'b1) ? 1'b1 : 1'b0;
endmodule

module fp_log(
input wire sysclk,
input wire reset,
input wire enable,
input wire signin,
input wire [8:1] exponentin,
input wire [23:1] mantissain,
output wire signout,
output wire [8:1] exponentout,
output wire [23:1] mantissaout,
output wire nanout,
output wire overflowout,
output wire zeroout
);
parameter [31:0] synthesize=1;
//------------------------------------------------
parameter expwidth = 8;
parameter manwidth = 23;
parameter coredepth = 19;
reg [2:1] signinff;
reg [manwidth:1] maninff;
reg [expwidth:1] expinff;
wire signnode;
wire [24:1] mantissanode;
wire [8:1] exponentnode;
wire zeronode;  // conditions
wire [manwidth:1] zeroman;
wire [expwidth:1] zeroexp;
wire [expwidth:1] maxexp;
reg zeromaninff;
reg zeroexpinff;
reg maxexpinff;
reg naninff;
reg [coredepth - 3:1] nanff;
reg infinityinff;
reg [coredepth - 3:1] infinityff;
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= manwidth; k = k + 1) begin
        maninff[k] <= 1'b0;
      end
      for (k=1; k <= expwidth; k = k + 1) begin
        expinff[k] <= 1'b0;
      end
      signinff <= 2'b00;
    end else begin
      if((enable == 1'b1)) begin
        maninff <= mantissain;
        expinff <= exponentin;
        signinff[1] <= signin;
        signinff[2] <= signinff[1];
      end
    end
  end
  //********************
  //*** CHECK INPUTS ***
  //********************
  assign zeroman[1] = maninff[1];
  genvar k;
  generate for (k=2; k <= manwidth; k = k + 1) begin: gca
      assign zeroman[k] = zeroman[k - 1] | maninff[k];
  end
  endgenerate
  assign zeroexp[1] = expinff[1];
  genvar k;
  generate for (k=2; k <= expwidth; k = k + 1) begin: gcb
      assign zeroexp[k] = zeroexp[k - 1] | expinff[k];
  end
  endgenerate
  assign maxexp[1] = expinff[1];
  genvar k;
  generate for (k=2; k <= expwidth; k = k + 1) begin: gcc
      assign maxexp[k] = maxexp[k - 1] & expinff[k];
  end
  endgenerate
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      zeromaninff <= 1'b0;
      zeroexpinff <= 1'b0;
      maxexpinff <= 1'b0;
      naninff <= 1'b0;
      for (k=1; k <= coredepth - 3; k = k + 1) begin
        nanff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        zeromaninff <=  ~(zeroman[manwidth]);
        zeroexpinff <=  ~(zeroexp[expwidth]);
        maxexpinff <= maxexp[expwidth];
        // infinity when exp = zero
        // nan when man != 0, exp = max
        // all ffs '1' when condition true
        naninff <= (zeromaninff & maxexpinff) | signinff[2];
        infinityinff <= zeroexpinff | maxexpinff;
        // nan output when nan input
        nanff[1] <= naninff;
        for (k=2; k <= coredepth - 3; k = k + 1) begin
          nanff[k] <= nanff[k - 1];
        end
        infinityff[1] <= infinityinff;
        for (k=2; k <= coredepth - 3; k = k + 1) begin
          infinityff[k] <= infinityff[k - 1];
        end
      end
    end
  end
  //***************
  //*** LN CORE ***
  //***************
  fp_ln_core #(
      .synthesize(synthesize))
  lncore(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    .aaman(mantissain),
    .aaexp(exponentin),
    .ccman(mantissanode),
    .ccexp(exponentnode),
    .ccsgn(signnode),
    .zeroout(zeronode));
  //************************
  //*** ROUND AND OUTPUT ***
  //************************
  fp_lnrnd rndout(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    .signln(signnode),
    .exponentln(exponentnode),
    .mantissaln(mantissanode),
    .nanin(nanff[coredepth - 3]),
    .infinityin(infinityff[coredepth - 3]),
    .zeroin(zeronode),
    .signout(signout),
    .exponentout(exponentout),
    .mantissaout(mantissaout),
    .nanout(nanout),
    .overflowout(overflowout),
    .zeroout(zeroout));
endmodule

