module HEX_TO_LED(
input wire RESET,
input wire GCLKP1,
input wire [3:0] LED0,
input wire [3:0] LED1,
input wire [3:0] LED2,
input wire [3:0] LED3,
output reg [7:0] LEDOut,
output reg [3:0] DigitSelect
);
// Reset & Clock Signal 
// 50 MHz 
// LED8 PIN 
// LED Segment 
// LED Digit 
//-------------------------------------------------------------------------------------------------
//-------------------------------------------------------------------------------------------------
// The Architecture of Entity Declarations 
reg [3:0] LED;
reg [1:0] Cathod;
reg cathod_clk;
  //----------------------------------------------------------------------------
  // Clock 
  //----------------------------------------------------------------------------
  always @(posedge RESET, posedge GCLKP1) begin : P1
    reg [31:0] Count;
      //----------------------------------
    //Period: 1uS 
    if((RESET == 1'b1)) begin
      Count = 0;
    end else begin
      if((Count > 511)) begin
        Count = 0;
        cathod_clk <= 1'b1;
      end
      else begin
        Count = Count + 1;
        cathod_clk <= 1'b0;
      end
    end
  end
  //-----------------------------------------------
  // Encoder 
  //-----------------------------------------------
  // HEX-to-seven-segment decoder 
  // segment encoding 
  //      0 
  //     ---  
  //  5 |   | 1
  //     --- <------6
  //  4 |   | 2
  //     ---  
  //      3
  always @(LED) begin
    case(LED)
    4'b0000 : begin
      LEDOut <= 8'b11000000;
      //'0'
    end
    4'b0001 : begin
      LEDOut <= 8'b11111001;
      //'1'
    end
    4'b0010 : begin
      LEDOut <= 8'b10100100;
      //'2'
    end
    4'b0011 : begin
      LEDOut <= 8'b10110000;
      //'3'
    end
    4'b0100 : begin
      LEDOut <= 8'b10011001;
      //'4'
    end
    4'b0101 : begin
      LEDOut <= 8'b10010010;
      //'5'
    end
    4'b0110 : begin
      LEDOut <= 8'b10000010;
      //'6'
    end
    4'b0111 : begin
      LEDOut <= 8'b11111000;
      //'7'
    end
    4'b1000 : begin
      LEDOut <= 8'b10000000;
      //'8'
    end
    4'b1001 : begin
      LEDOut <= 8'b10010000;
      //'9'
    end
    4'b1010 : begin
      LEDOut <= 8'b10001000;
      //'A'
    end
    4'b1011 : begin
      LEDOut <= 8'b10000011;
      //'b'
    end
    4'b1100 : begin
      LEDOut <= 8'b11000110;
      //'C'
    end
    4'b1101 : begin
      LEDOut <= 8'b10100001;
      //'d'
    end
    4'b1110 : begin
      LEDOut <= 8'b10000110;
      //'E'
    end
    4'b1111 : begin
      LEDOut <= 8'b10001110;
      //'F'
    end
    default : begin
      LEDOut <= 8'bXXXXXXXX;
      //' '
    end
    endcase
  end
  //-----------------------------------------------
  // Dynamic indacator  
  always @(posedge RESET, posedge GCLKP1) begin
    if((RESET == 1'b1)) begin
      Cathod <= 2'b00;
    end else begin
      if((cathod_clk == 1'b1)) begin
        case(Cathod)
        2'b11 : begin
          DigitSelect <= 4'b0001;
        end
        2'b10 : begin
          DigitSelect <= 4'b0010;
        end
        2'b01 : begin
          DigitSelect <= 4'b0100;
        end
        2'b00 : begin
          DigitSelect <= 4'b1000;
        end
        default : begin
          DigitSelect <= 4'bXXXX;
        end
        endcase
        Cathod <= Cathod + 1;
      end
    end
  end
  always @(Cathod, LED0, LED1, LED2, LED3) begin
    case(Cathod)
    2'b01 : begin
      LED <= LED3;
    end
    2'b10 : begin
      LED <= LED2;
    end
    2'b11 : begin
      LED <= LED1;
    end
    2'b00 : begin
      LED <= LED0;
    end
    default : begin
      LED <= 4'b1111;
    end
    endcase
  end
endmodule

