module UART_RX_CTRL(
input wire UART_RX,
input wire CLK,
output reg [7:0] DATA,
output reg READ_DATA,
input wire RESET_READ
);
parameter FREQ = 100000000;  // 100MHz Nexys4 CLK
parameter BAUD = 9600;
reg [31:0] count = 0;
parameter sample_0 = 3 * FREQ / (BAUD * 2) - 1;
parameter sample_1 = 5 * FREQ / (BAUD * 2) - 1;
parameter sample_2 = 7 * FREQ / (BAUD * 2) - 1;
parameter sample_3 = 9 * FREQ / (BAUD * 2) - 1;
parameter sample_4 = 11 * FREQ / (BAUD * 2) - 1;
parameter sample_5 = 13 * FREQ / (BAUD * 2) - 1;
parameter sample_6 = 15 * FREQ / (BAUD * 2) - 1;
parameter sample_7 = 17 * FREQ / (BAUD * 2) - 1;
parameter stop_bit = 19 * FREQ / (BAUD * 2) - 1;
reg [7:0] byte = 1'b0;
  always @(posedge CLK) begin
    if((RESET_READ == 1'b1)) begin
      READ_DATA <= 1'b0;
    end
    case(count)
    sample_0 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_1 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_2 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_3 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_4 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_5 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_6 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_7 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    stop_bit : begin
      if(UART_RX == 1'b1) begin
        DATA <= byte;
        READ_DATA <= 1'b1;
      end
    end
    default : begin
    end
    endcase
    if(count == stop_bit) begin
      count <= 0;
    end
    else if(count == 0) begin
      if(UART_RX == 1'b0) begin
        count <= count + 1;
      end
    end
    else begin
      count <= count + 1;
    end
  end
endmodule

module vga_nmsuppression(
input wire clk,
input wire enable,
input wire active,
input wire [9:0] x_addr_in,
input wire [9:0] y_addr_in,
input wire [31:0] hessian_in,
output reg [9:0] x_addr_out,
output reg [9:0] y_addr_out,
output reg [31:0] hessian_out
);
parameter [31:0] ROW_WIDTH=5;
reg [31:0] hessian[ROW_WIDTH * 2 + 2:0];
  always @(posedge clk) begin : P1
    reg [31:0] center = 32'h00000000;
    if(active == 1'b1) begin
      // compare
      center = hessian[ROW_WIDTH + 1];
      if(enable == 1'b1 && ((hessian_in) > center || (hessian[0]) > center || (hessian[1]) > center || (hessian[ROW_WIDTH]) > center || (hessian[ROW_WIDTH + 2]) > center || (hessian[ROW_WIDTH * 2 - 1]) > center || (hessian[ROW_WIDTH * 2]) > center || (hessian[ROW_WIDTH * 2 + 1]) > center)) begin
        hessian_out <= 32'h00000000;
      end
      else begin
        hessian_out <= center;
      end
      x_addr_out <= (x_addr_in) - 1;
      y_addr_out <= (y_addr_in) - 1;
      // shift
      for (i=0; i <= ROW_WIDTH * 2; i = i + 1) begin
        hessian[i + 1] <= hessian[i];
      end
      hessian[0] <= hessian_in;
    end
  end
endmodule

