module Eth_GMII_RXTest(
input wire [3:0] botones,
output wire [3:0] leds,
input wire gmii_int,
output wire gmii_reset,
output wire gmii_mdc,
inout wire gmii_mdio,
output wire gmii_tx_clk,
output wire gmii_tx_en,
output wire [7:0] gmii_tx_data,
output wire gmii_tx_err,
input wire gmii_rx_clk,
input wire gmii_rx_crs,
input wire gmii_rx_col,
input wire [7:0] gmii_rx_data,
input wire gmii_rx_dataValid,
input wire gmii_rx_err,
input wire sysclk_n,
input wire sysclk_p
);
//Interfaz hacia el PHY
reg [3:0] packetCounter = 4'b0000;
reg gmii_rx_dataValid_previous;
wire tx_clk;
reg packetAlreadyReaded = 1'b0;
wire porta_wr;
wire [9:0] porta_waddr;
wire [7:0] porta_din = 1'b0;
wire porta_rd;
wire [9:0] porta_raddr;
wire [7:0] porta_dout;
wire portb_rd;
wire [9:0] portb_addr;
wire [7:0] portb_dout;
reg [9:0] storeCounter = 1'b0;
  BinarySearchBRAM #(
      .DATA_WIDTH(8),
    .ADDR_WIDTH(10))
  memory(
      .clk(gmii_rx_clk),
    .porta_wr(porta_wr),
    .porta_waddr(porta_waddr),
    .porta_din(porta_din),
    .porta_rd(porta_rd),
    .porta_raddr(porta_raddr),
    .porta_dout(/* open */),
    .portb_rd(portb_rd),
    .portb_addr(portb_addr),
    .portb_dout(portb_dout));
  assign porta_wr = gmii_rx_dataValid &  ~(packetAlreadyReaded);
  assign porta_waddr = storeCounter;
  assign porta_din = gmii_rx_data[7:0];
  assign porta_rd = 1'b0;
  assign porta_raddr = {10{1'b0}};
  assign portb_rd = 1'b0;
  assign portb_addr = {10{1'b0}};
  always @(posedge gmii_rx_clk, posedge gmii_rx_dataValid, posedge gmii_rx_data, posedge storeCounter, posedge gmii_rx_dataValid_previous, posedge packetCounter) begin
    if((gmii_rx_dataValid == 1'b1)) begin
      //leds(3 downto 0) <= gmii_rx_data(3 downto 0);
      storeCounter <= storeCounter + 1;
    end
    gmii_rx_dataValid_previous <= gmii_rx_dataValid;
    if(((gmii_rx_dataValid == 1'b1) && (gmii_rx_dataValid_previous == 1'b0))) begin
      packetCounter <= packetCounter + 1;
    end
    else if(((gmii_rx_dataValid == 1'b0) && (gmii_rx_dataValid_previous == 1'b1))) begin
      packetAlreadyReaded <= 1'b1;
    end
  end
  assign leds = packetCounter;
  assign gmii_reset = 1'b1;
  assign gmii_tx_en = 1'b0;
  assign gmii_tx_data = {8{1'b0}};
  assign gmii_tx_err = 1'b0;
  assign gmii_mdc = 1'b0;
  assign gmii_mdio = 1'bZ;
  clk_wiz_v3_6_0 txClkGenerator(
      // Clock in ports
    .CLK_IN1_P(sysclk_p),
    .CLK_IN1_N(sysclk_n),
    // Clock out ports
    .CLK_OUT1(tx_clk));
  ODDR2 gmii_tx_clk_ddr_iob(
      .D0(1'b0),
    .D1(1'b1),
    .C0(tx_clk),
    .C1(1'b0),
    .CE(1'b1),
    .R(1'b0),
    .S(1'b0),
    .Q(gmii_tx_clk));
endmodule

