module sub_580(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

module mult32(
input wire [31:0] a,
input wire [31:0] b,
output reg [63:0] op
);
// Describe the behavior of the unsigned 32-bit
// multiplier
  always @(a, b) begin : P1
  // Temporary variables to store the operands
  // and the product
    reg [31:0] a_reg;
    reg [31:0] b_reg;
    reg [63:0] res_reg;
    // Store¡¡operands temporarily in these variables
    a_reg = 32'b11111111111111111111111111111111 & a;
    b_reg = 32'b11111111111111111111111111111111 & b;
    // Perform the following operations for each
    // bit of the multiplicand/multiplier reg,
    // which are assumed to have the same
    // bit-vector size.
    // Since the multiplicand/multiplier reg is
    // 32-bit wide, perform this loop 32 times.
    for (num_rep=0; num_rep <= 32; num_rep = num_rep + 1) begin
      // If bit multiplier[0] == 0,
      if(b[0] == 1'b1) begin
        // pdt reg = pdt reg + multiplier reg
        res_reg = res_reg + a;
      end
      // Shift multiplicand reg left 1 bit
      //			a_reg := a_reg sll 1;
      a_reg = {a_reg[30:0],1'b0};
      // Shift multiplier reg right 1 bit
      //			b_reg := b_reg srl 1;
      b_reg = {1'b0,b_reg[31:1]};
    end
    // Place the contents of the temporary output
    // register in "op"
    op <= res_reg;
  end
endmodule

