module rs232_sender(
input wire clock_115200Hz,
input wire send_start,
input wire [7:0] send_data,
output reg ack,
output reg output
);
// a pulse notification
parameter [1:0]
  STATE_IDLE = 0,
  STATE_START_BIT = 1,
  STATE_SENDING = 2,
  STATE_END_BIT = 3;
reg [1:0] state;
reg power_on = 1'b0;
reg [31:0] bit_count;
  always @(posedge clock_115200Hz) begin
    if((power_on == 1'b0)) begin
      // init
      power_on <= 1'b1;
      state <= STATE_IDLE;
    end
    else begin
      // non-init
      case(state)
      STATE_IDLE : begin
        output <= 1'b1;
        ack <= 1'b0;
        // different!
        if((send_start == 1'b1)) begin
          ack <= 1'b0;
          state <= STATE_START_BIT;
        end
      end
      STATE_START_BIT : begin
        bit_count <= 0;
        output <= 1'b0;
        state <= STATE_SENDING;
      end
      STATE_SENDING : begin
        output <= send_data[bit_count];
        bit_count <= bit_count + 1;
        if((bit_count >= 7)) begin
          state <= STATE_END_BIT;
        end
      end
      STATE_END_BIT : begin
        output <= 1'b1;
        ack <= 1'b1;
        state <= STATE_IDLE;
      end
      endcase
    end
    // init / non-init
  end
endmodule

module adder_full(
input wire in_0,
input wire in_1,
input wire carry_in,
output wire sum,
output wire carry_out
);
wire i0_xor_i1;
wire i0_and_i1;
wire ci_and_xor;
  assign i0_xor_i1 = in_0 ^ in_1;
  assign i0_and_i1 = in_0 & in_1;
  assign ci_and_xor = i0_xor_i1 & carry_in;
  assign sum = i0_xor_i1 ^ carry_in;
  assign carry_out = ci_and_xor | i0_and_i1;
endmodule

module segment(
input wire clock,
output wire [7:0] segment_data
);
reg [3:0] number;  // decimal 0 to 15
reg [15:0] count;
  always @(posedge clock) begin
    count <= count + 1;
    if(count == 0) begin
      number <= number + 1;
    end
  end
  assign segment_data = number == 0 ? 8'b01000000 : number == 1 ? 8'b01111001 : number == 2 ? 8'b00100100 : number == 3 ? 8'b00110000 : number == 4 ? 8'b00011001 : number == 5 ? 8'b00010010 : number == 6 ? 8'b00000010 : number == 7 ? 8'b01111000 : number == 8 ? 8'b00000000 : number == 9 ? 8'b00010000 : number == 10 ? 8'b00001000 : number == 11 ? 8'b00000011 : number == 12 ? 8'b01000110 : number == 13 ? 8'b00100001 : number == 14 ? 8'b00000110 : 8'b00001110;
    //F
endmodule

