module gray2angleinc(
input wire clk,
input wire reset,
input wire [0:0] bit_in,
input wire ok_bit_in,
input wire [2:0] modulation,
output wire [2:0] anginc_out,
output reg ok_anginc_out
);
parameter [1:0]
  bit_0 = 0,
  bit_1 = 1,
  bit_2 = 2,
  salida_valida = 3;
reg [1:0] estado_actual;
reg [1:0] estado_nuevo;
reg [2:0] anginc_int; reg [2:0] p_anginc_int;
  assign anginc_out = anginc_int;
  always @(estado_actual, bit_in, ok_bit_in, anginc_int, modulation) begin
    p_anginc_int <= anginc_int;
    ok_anginc_out <= 1'b0;
    estado_nuevo <= estado_actual;
    case(estado_actual)
    bit_0 : begin
      if(ok_bit_in == 1'b1) begin
        p_anginc_int[2] <= bit_in[0];
        if(modulation == 3'b100) begin
          // gray a decimal multiplicado por 4 (desplazamiento bits izq *2)
          //					p_anginc_int(2) <= bit_in; --(gray a decimal) *2
          p_anginc_int[1:0] <= 2'b00;
          estado_nuevo <= salida_valida;
        end
        else begin
          //					p_anginc_int(0) <= bit_in;
          estado_nuevo <= bit_1;
        end
      end
    end
    bit_1 : begin
      if(ok_bit_in == 1'b1) begin
        p_anginc_int[1] <= anginc_int[2] ^ bit_in[0];
        if(modulation == 3'b010) begin
          // gray a decimal multiplicado por 2 (desplazamiento bits izq)
          //--					p_anginc_int(2) <= anginc_int(0);
          //					p_anginc_int(1) <= anginc_int(0) xor bit_in;
          p_anginc_int[0] <= 1'b0;
          estado_nuevo <= salida_valida;
        end
        else begin
          //					p_anginc_int(1) <= bit_in;
          estado_nuevo <= bit_2;
        end
      end
    end
    bit_2 : begin
      p_anginc_int[0] <= anginc_int[1] ^ bit_in[0];
      if(ok_bit_in == 1'b1) begin
        // gray a decimal
        //				p_anginc_int(2) <= bit_in; --bin2 = gray2
        //				p_anginc_int(1) <= anginc_int(1) xor bit_in; --bin1 = gray1 xor bin2(=gray2)
        //				p_anginc_int(0) <= anginc_int(0) xor anginc_int(1) xor bit_in; --bin0 = gray0 xor bin1(=gray1 xor bin2) 
        estado_nuevo <= salida_valida;
      end
    end
    salida_valida : begin
      ok_anginc_out <= 1'b1;
      estado_nuevo <= bit_0;
    end
    endcase
  end
  always @(posedge reset, posedge clk) begin
    if((reset == 1'b1)) begin
      anginc_int <= 3'b000;
      estado_actual <= bit_0;
    end else begin
      anginc_int <= p_anginc_int;
      estado_actual <= estado_nuevo;
    end
  end
endmodule

