module i2s_data_interface(
input wire clk,
input wire [15:0] audio_l_in,
input wire [15:0] audio_r_in,
output reg [15:0] audio_l_out,
output reg [15:0] audio_r_out,
output reg new_sample,
input wire i2s_bclk,
output reg i2s_d_out,
input wire i2s_d_in,
input wire i2s_lr
);
wire [5:0] bit_counter = 1'b0;
reg [9:0] bclk_delay = 1'b0;
wire [9:0] lr_delay = 1'b0;
reg [126:0] sr_in = 1'b0;
reg [63:0] sr_out = 1'b0;
reg i2s_lr_last = 1'b0;
reg i2s_d_in_last = 1'b0;
  always @(posedge clk) begin
      // Process to predict when the falling edge of i2s_bclk should be
    new_sample <= 1'b0;
    //----------------------------
    // is there a rising edge two cycles ago? If so the data bit is 
    // validand we can capture a bit
    //----------------------------
    if(bclk_delay[(9) - 1:(9) - 2] == 2'b10) begin
      sr_in <= {sr_in[(126) - 1:0],i2s_d_in_last};
    end
    //----------------------------
    // Was there a rising edge on BCLK 9 cycles ago?
    // If so, this should be about the falling edge so 
    // the output can change.
    //----------------------------
    if(bclk_delay[1:0] == 2'b10) begin
      i2s_d_out <= sr_out[(63)];
      // if we are starting a new frame, then load the samples into the shift register
      if(i2s_lr == 1'b1 && i2s_lr_last == 1'b0) begin
        audio_l_out <= sr_in[(126):(126) - 15];
        audio_r_out <= sr_in[(126) - 32:(126) - 15 - 32];
        sr_out <= {audio_l_in,16'h0000,audio_r_in,16'h0000};
        new_sample <= 1'b1;
      end
      else begin
        sr_out <= {sr_out[(63) - 1:0],1'b0};
      end
      // remember what lr was, for edge detection
      i2s_lr_last <= i2s_lr;
    end
    bclk_delay <= {i2s_bclk,bclk_delay[(9):1]};
    i2s_d_in_last <= i2s_d_in;
  end
endmodule

