module zpuino_uart_rx(
input wire clk,
input wire rst,
input wire rx,
input wire rxclk,
input wire read,
output wire [7:0] data,
output wire data_av
);
wire rxf;
wire baudtick;
reg [7:0] rxd;
reg [2:0] datacount;
reg baudreset;
wire filterreset;
reg [7:0] datao;
reg dataready;
reg start;
wire debug_synctick_q;
wire debug_baudreset_q;  // State
parameter [1:0]
  rx_idle = 0,
  rx_start = 1,
  rx_data = 2,
  rx_end = 3;
reg [1:0] state;
  assign data = datao;
  assign data_av = dataready;
  zpuino_uart_mv_filter #(
      .bits(4),
    .threshold(10))
  rxmvfilter(
      .clk(clk),
    .rst(rst),
    .sin(rx),
    .sout(rxf),
    .clear(filterreset),
    .enable(rxclk));
  assign filterreset = baudreset | baudtick;
  //istart <= start;
  uart_brgen baudgen(
      .clk(clk),
    .rst(baudreset),
    .en(rxclk),
    .count(16'h000f),
    .clkout(baudtick));
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      state <= rx_idle;
      dataready <= 1'b0;
      baudreset <= 1'b0;
      start <= 1'b0;
    end
    else begin
      baudreset <= 1'b0;
      start <= 1'b0;
      if(read == 1'b1) begin
        dataready <= 1'b0;
      end
      case(state)
      rx_idle : begin
        if(rx == 1'b0) begin
          // Start bit
          state <= rx_start;
          baudreset <= 1'b1;
          start <= 1'b1;
        end
      end
      rx_start : begin
        if(baudtick == 1'b1) begin
          // Check filtered output.
          if(rxf == 1'b0) begin
            datacount <= 3'b111;
            state <= rx_data;
            // Valid start bit.
          end
          else begin
            state <= rx_idle;
          end
        end
      end
      rx_data : begin
        if(baudtick == 1'b1) begin
          rxd[7] <= rxf;
          rxd[6:0] <= rxd[7:1];
          datacount <= datacount - 1;
          if(datacount == 0) begin
            state <= rx_end;
          end
        end
      end
      rx_end : begin
        // Check for framing errors ?
        // Do fast recovery here.
        if(rxf == 1'b1) begin
          dataready <= 1'b1;
          datao <= rxd;
          state <= rx_idle;
        end
        if(baudtick == 1'b1) begin
          // Framing error.
          state <= rx_idle;
        end
      end
      default : begin
      end
      endcase
    end
  end
endmodule

module Cntrl_cont(
