module vga_640x480(
input wire clk,
input wire clr,
output wire hsync,
output wire vsync,
output wire [9:0] hc,
output wire [9:0] vc,
output wire [22:0] pix,
output wire vidon
);
parameter hpixels = 10'b1100100000;  //Pixels in a horizontal line = 800
parameter vlines = 10'b1000001001;  //Lines in the image = 521
parameter hbp = 10'b0010010000;  //Horizontal back porch = 144
parameter hfp = 10'b1100010000;  //Horiztonal front porch = 748
parameter vbp = 10'b0000011111;  //Vertical back porch = 31
parameter vfp = 10'b0111111111;  //Vertical front porch = 511
reg [9:0] hcs; reg [9:0] vcs;  //Horiztonal and vertical counters
reg vsenable;  //Enable for the vertical counter
wire hsync_s; wire vsync_s; wire vidon_s;
reg [22:0] pix_count; reg [22:0] pix_count_next;
reg pix_count_clr;
  //Counter for the horizontal sync signal
  always @(posedge clk, posedge clr) begin
    if(clr == 1'b1) begin
      hcs <= 10'b0000000000;
      pix_count <= {23{1'b0}};
      pix_count_next <= {23{1'b0}};
    end else begin
      if(hcs == (hpixels - 1)) begin
        //The counter has reached the end of pixel count, reset
        hcs <= 10'b0000000000;
        //Enable the vertical counter
        vsenable <= 1'b1;
      end
      else begin
        //Increment the horizontal counter
        hcs <= hcs + 1;
        //Increment the pixel counter
        if(pix_count_clr == 1'b1) begin
          pix_count_next <= {23{1'b0}};
        end
        else if(vidon_s == 1'b1) begin
          pix_count_next <= pix_count_next + 1;
        end
        //Leave vsenable off
        vsenable <= 1'b0;
        pix_count <= pix_count_next;
      end
    end
  end
  //Horizontal sync pulse is low when hc is 0-127
  assign hsync_s = hcs < 128 ? 1'b0 : 1'b1;
  //Counter for the vertical sync signal
  always @(posedge clk, posedge clr) begin
    if(clr == 1'b1) begin
      vcs <= 10'b0000000000;
      pix_count_clr <= 1'b0;
    end else begin
      //Increment when enabled
      if(vcs == (vlines - 1)) begin
        //Reset when the number of lines is reached
        vcs <= 10'b0000000000;
        pix_count_clr <= 1'b1;
      end
      else begin
        //Increment vertical counter
        vcs <= vcs + 1;
        pix_count_clr <= 1'b0;
      end
    end
  end
  //Vertical sync pulse is low when vc is 0 or 1
  assign vsync_s = vcs < 2 ? 1'b0 : 1'b1;
  //Enable video out when within the porches
  assign vidon_s = (((hcs < hfp) && (hcs >= hbp)) && ((vcs < vfp) && (vcs >= vbp))) ? 1'b1 : 1'b0;
  //vidon_s <= (vsync_s and hsync_s); 
  assign vidon = vidon_s;
  //Output horizontal and vertical counters
  assign hc = hcs;
  assign vc = vcs;
  assign hsync = hsync_s;
  assign vsync = vsync_s;
  assign pix = pix_count;
endmodule

