module watchdog_timer(
input wire OPB_select,
input wire OPB_xferAck,
input wire OPB_retry,
input wire OPB_toutSup,
output reg OPB_timeout,
input wire Clk,
input wire Rst
);
//---------------------------------------------------------------------------
// Architecture section
//---------------------------------------------------------------------------
//-----------------------------------------------------------------------------
//  Constant Declarations
//-----------------------------------------------------------------------------
// Constants used in this design are found in opb_arbiter_pkg.vhd
//-----------------------------------------------------------------------------
// Signal and Type Declarations
//-----------------------------------------------------------------------------
reg [0:3] timeout_cnt;  // output from counter
//---------------------------------------------------------------------------
// Begin architecture
//---------------------------------------------------------------------------
  //-----------------------------------------------------------------------------
  // WATCHDOG_TIMER_PROCESS
  //-----------------------------------------------------------------------------
  // This process counts clocks after OPB_select is asserted while OPB_xferAck
  // and OPB_retry are negated. The assertion of OPB_toutSup suspends the counter.
  //-----------------------------------------------------------------------------
  always @(posedge Clk, posedge Rst, posedge OPB_select, posedge OPB_retry, posedge OPB_xferAck, posedge OPB_toutSup, posedge timeout_cnt) begin
    //  active high, synchronous reset
    if(Rst == RESET_ACTIVE) begin
      timeout_cnt <= {4{1'b0}};
    end
    else if(OPB_select == 1'b1 && OPB_retry == 1'b0 && OPB_xferAck == 1'b0) begin
      //  Enable timeout counter once OPB_select asserts
      //  and OPB_retry and OPB_xferAck are negated.
      //  Reset counter if either OPB_retry or
      //  OPB_xferAck assert while OPB_select
      //  is asserted
      if(OPB_toutSup == 1'b0) begin
        timeout_cnt <= timeout_cnt + 1;
      end
      else begin
        timeout_cnt <= timeout_cnt;
      end
    end
    else begin
      timeout_cnt <= {4{1'b0}};
    end
  end
  //-----------------------------------------------------------------------------
  // TIMEOUT_PROCESS
  //-----------------------------------------------------------------------------
  // This process asserts the OPB_timeout signal when the output of the watchdog
  // timer is OPB_TIMEOUTCNT-2 (0-14=15 clocks) and OPB_toutSup is negated.
  // OPB_timeout is registered to improve FPGA implementation timing
  //-----------------------------------------------------------------------------
  always @(posedge Clk, posedge Rst) begin
      // process
    //  Assert OPB_timeout OPB_TIMEOUT_CNT-2 clocks
    //  after OPB_select asserts if OPB_toutSup is negated
    if(Rst == RESET_ACTIVE) begin
      OPB_Timeout <= 1'b0;
    end
    else if(timeout_cnt == (OPB_TIMEOUT_CNT - 2) && OPB_toutSup == 1'b0 && OPB_select == 1'b1 && OPB_retry == 1'b0 && OPB_xferAck == 1'b0) begin
      OPB_timeout <= 1'b1;
    end
    else begin
      OPB_timeout <= 1'b0;
    end
  end
endmodule

