module vga_sync(
input wire clk_25,
input wire rst,
output wire active,
output wire hsync,
output wire vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
);
// The default values are for 640x480
parameter [31:0] H_SIZE=640;
parameter [31:0] H_FRONT_DELAY=16;
parameter [31:0] H_BACK_DELAY=48;
parameter [31:0] H_RETRACE_DELAY=96;
parameter [31:0] V_SIZE=480;
parameter [31:0] V_FRONT_DELAY=10;
parameter [31:0] V_BACK_DELAY=33;
parameter [31:0] V_RETRACE_DELAY=2;
// sync counters
reg [9:0] v_count_reg; reg [9:0] v_count_next;
reg [9:0] h_count_reg; reg [9:0] h_count_next;  // output buffer
reg v_sync_reg; reg h_sync_reg;
wire v_sync_next; wire h_sync_next;  // status signal
wire h_end; wire v_end; wire pixel_tick;
  // registers
  always @(posedge clk_25, posedge rst) begin
    if(rst == 1'b1) begin
      v_count_reg <= {10{1'b0}};
      h_count_reg <= {10{1'b0}};
      v_sync_reg <= 1'b1;
      h_sync_reg <= 1'b1;
    end else begin
      v_count_reg <= v_count_next;
      h_count_reg <= h_count_next;
      v_sync_reg <= v_sync_next;
      h_sync_reg <= h_sync_next;
    end
  end
  // status 
  assign h_end = h_count_reg == (H_SIZE + H_FRONT_DELAY + H_BACK_DELAY + H_RETRACE_DELAY - 1) ? 1'b1 : 1'b0;
  assign v_end = v_count_reg == (V_SIZE + V_FRONT_DELAY + V_BACK_DELAY + V_RETRACE_DELAY - 1) ? 1'b1 : 1'b0;
  // mod-800 horizontal sync counter
  always @(h_count_reg, h_end) begin
    h_count_next <= h_count_reg;
    if(h_end == 1'b1) begin
      h_count_next <= {10{1'b0}};
    end
    else begin
      h_count_next <= h_count_reg + 1;
    end
  end
  // mod-525 vertical sync counter
  always @(v_count_reg, h_end, v_end) begin
    if(h_end == 1'b1) begin
      if((v_end == 1'b1)) begin
        v_count_next <= {10{1'b0}};
      end
      else begin
        v_count_next <= v_count_reg + 1;
      end
    end
    else begin
      v_count_next <= v_count_reg;
    end
  end
  // horizontal and vertical sync, buffered to avoid glitch
  assign h_sync_next = (h_count_reg >= (H_SIZE + H_FRONT_DELAY)) && (h_count_reg <= (H_SIZE + H_FRONT_DELAY + H_RETRACE_DELAY - 1)) ? 1'b1 : 1'b0;
  assign v_sync_next = (v_count_reg >= (V_SIZE + V_FRONT_DELAY)) && (v_count_reg <= (V_SIZE + V_FRONT_DELAY + V_RETRACE_DELAY - 1)) ? 1'b1 : 1'b0;
  // video on/off
  assign active = (h_count_reg < H_SIZE) && (v_count_reg < V_SIZE) ? 1'b1 : 1'b0;
  // output signal
  assign hsync = h_sync_reg;
  assign vsync = v_sync_reg;
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
endmodule

