output reg [15:0] f1_do_o,
output reg f1_wren_o,
output reg [15:0] f2_do_o,
output reg f2_wren_o
);
//-- master_control interface ----
//triggers spi cycle
//triggers spi cycle
//-- spi 1 interface ----
//-- spi 2 interface ----
//-- fifo 1 interface ----
//-- fifo 2 interface ----
  // If rdreq_1_o is high data is feed to the master control, if it is low
  // data is stored in the corresponding fifo.
  always @(rdreq_1_i, s1_di_i, s1_drdy_i) begin
    if(rdreq_1_i == 1'b1) begin
      do_1_o <= s1_di_i;
      f1_do_o <= 16'h0000;
      f1_wren_o <= 1'b0;
    end
    else begin
      do_1_o <= 16'h0000;
      f1_do_o <= s1_di_i;
      f1_wren_o <= s1_drdy_i;
    end
  end
  always @(rdreq_2_i, s2_di_i, s2_drdy_i) begin
    if(rdreq_2_i == 1'b1) begin
      do_2_o <= s2_di_i;
      f2_do_o <= 16'h0000;
      f2_wren_o <= 1'b0;
    end
    else begin
      do_2_o <= 16'h0000;
      f2_do_o <= s2_di_i;
      f2_wren_o <= s2_drdy_i;
    end
  end
  // fixed signals
  assign drdy_1_o = s1_drdy_i;
  assign drdy_2_o = s2_drdy_i;
  assign s1_do_o = di_1_i;
  assign s1_wren_o = wren_1_i;
