  // registrador
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      contagem <= 0;
    end else begin
      contagem <= prox_contagem;
    end
  end
  // logica de proximo estado
  assign prox_contagem = contagem == (M - 1) ? 0 : contagem + 1;
