reg [31:0] cnt = 0;
  always @(posedge rst_i, posedge clk_i) begin
    if(rst_i == 1'b1) begin
      pulse <= 1'b0;
      cnt <= 0;
    end else begin
      if(pulse == 1'b1) begin
        if(cnt == (duration_g - 1)) begin
          pulse <= 1'b0;
          cnt <= 0;
        end
        else begin
          cnt <= cnt + 1;
        end
      end
      if(stb_i == 1'b1) begin
        pulse <= 1'b1;
        cnt <= 0;
      end
    end
  end
  assign pulse_o = pulse;
endmodule

