module minus_one(
input wire A15,
input wire A14,
input wire A13,
input wire A12,
input wire A11,
input wire A10,
input wire A9,
input wire A8,
input wire A3,
input wire A2,
input wire A1,
input wire A0,
input wire [7:0] D,
input wire nRST,
input wire PHI0,
input wire RnW,
output wire cart0_nOE,
output wire cart2_nOE,
output wire cart4_nOE,
output wire cart_nOE2,
output wire cart_ROMQA,
output wire cart_nINFC,
output wire cart_nINFD,
output wire cart_nROMSTB,
input wire GPIO1,
input wire GPIO2,
input wire GPIO3
);
// can't use a std_logic_vector here because we're missing A7-4 :(
// '1' when A = &8000-BFFF, i.e. sideways address space
wire sideways_select;  // high byte on the address bus
wire [7:0] A_high;  // low nybble on the address bus
wire [3:0] A_low;  // register: currently selected bank
reg [3:0] bank = 4'b1101;
  assign A_high = {A15,A14,A13,A12,A11,A10,A9,A8};
  assign A_low = {A3,A2,A1,A0};
  // '1' when A = &8000-BFFF
  assign sideways_select = ({A15,A14} == 2'b10) ? 1'b1 : 1'b0;
  // nOE for all cartridges
  assign cart0_nOE = sideways_select == 1'b1 && (bank[3:1] == 3'b000) ? 1'b0 : 1'b1;
  assign cart2_nOE = sideways_select == 1'b1 && (bank[3:1] == 3'b001) ? 1'b0 : 1'b1;
  assign cart4_nOE = sideways_select == 1'b1 && (bank[3:1] == 3'b010) ? 1'b0 : 1'b1;
  // bank select within cartridge address space
  assign cart_ROMQA = bank[0];
  // nOE2 (shared by all cartridges)
  assign cart_nOE2 = sideways_select == 1'b1 && bank == 4'b1101 ? 1'b0 : 1'b1;
  // '0' when A = FCxx
  assign cart_nINFC = (A_high == 8'hFC) ? 1'b0 : 1'b1;
  // '0' when A = FDxx
  assign cart_nINFD = (A_high == 8'hFD) ? 1'b0 : 1'b1;
  // nROMSTB is not implemented
  assign cart_nROMSTB = 1'b1;
  always @(negedge PHI0) begin
    if(nRST == 1'b0) begin
      // default to something that'll deactivate all cartridges
      bank <= 4'b1010;
    end else begin
      // ROM bank is selected by writing "0000xxxx" to &FEx5
      if(RnW == 1'b0 && A_high == 8'hFE && A_low == 4'h5 && D[7:4] == 4'b0000) begin
        bank <= D[3:0];
      end
    end
  end
endmodule

