module AD_DA(
input wire Clk,
input wire ResetN,
input wire Loopthru,
output wire [7:0] Data_from_AD,
input wire [7:0] Data_to_DA,
output wire AD_Clk,
input wire [7:0] AD_Input,
output wire DA_Clk,
output reg [7:0] DA_Out
);
//------------------------------------------------------------------------------------------
//																			ARCHITECTURE
//------------------------------------------------------------------------------------------
reg clk_int;
reg [7:0] ad_data; reg [7:0] da_data;
  //------------------------------------------------------generate slow ad and da clock
  //																156.250 Mhz / 12 =  ca. 13 Mhz
  always @(posedge Clk, posedge ResetN) begin : P1
    reg [31:0] clk_div = 0;
    if((ResetN == 1'b0)) begin
      clk_int <= 1'b0;
    end else begin
      if((clk_div == 6)) begin
        clk_div = 0;
        clk_int <=  ~clk_int;
      end
      else begin
        clk_div = clk_div + 1;
      end
    end
  end
  //------------------------------------------------------sample/latch AD Converter on falling AD Clock
  always @(negedge clk_int) begin
    ad_data <= AD_Input;
  end
  //------------------------------------------------------prepare Data for DA_Converter on falling DA Clock
  always @(posedge clk_int) begin
    DA_Out <= da_data;
  end
  assign AD_Clk = clk_int;
  assign DA_Clk =  ~clk_int;
  assign Data_from_AD = ad_data;
  //	da_data <= Data_to_DA;
  always @(*) begin
    case(Loopthru)
      1'b1 : da_data <= ad_data;
  // loop through
      1'b0 : da_data <= Data_to_DA;
      default : da_data <= 8'b11111111;
    endcase
  end
endmodule

module resultDistributor(
input wire clk,
input wire vblank,
output wire [8:0] resultAddr,
input wire [31:0] resultData,
input wire busy,
output reg outputReady,
output wire [7:0] outputAddr,
output wire [23:0] outputData
);
reg lastbusy;
reg lastvblank;
reg [7:0] count = 1'b0;
  always @(posedge clk) begin
    outputReady <= 1'b0;
    if((vblank == 1'b1 && lastvblank == 1'b0)) begin
      count <= {8{1'b0}};
      outputReady <= 1'b1;
    end
    else if((busy == 1'b0 && lastbusy == 1'b1 && count != 8'b11111111)) begin
      //"11111111") then
      count <= (count) + 1;
      outputReady <= 1'b1;
    end
    lastbusy <= busy;
    lastvblank <= vblank;
  end
  assign resultAddr = {1'b0,count};
  assign outputAddr = resultData[31:24];
  assign outputData = resultData[23:0];
endmodule

