module outputswitcher(
input wire sel_raw,
input wire sel_decoded,
input wire dclk,
input wire [19:0] data,
output wire seg6_en,
output wire [3:0] seg6,
output wire seg5_en,
output wire [3:0] seg5,
output wire seg4_en,
output wire [3:0] seg4,
output wire seg3_en,
output wire [3:0] seg3,
output wire seg2_en,
output wire [3:0] seg2,
output wire seg1_en,
output wire [3:0] seg1,
output wire dp
);
reg [7:0] decoded;
wire [3:0] decoded_z;
wire [3:0] decoded_e;
  always @(*) begin
    case(data)
      20'b00001001110100011111 : decoded <= 8'b00000001;
  // 1:  Bright Down
      20'b00001001110100011110 : decoded <= 8'b00000010;
  // 2:  Bright Up
      20'b00001001110100001111 : decoded <= 8'b00000011;
  // 3:  Vertical Down
      20'b00001001110100001110 : decoded <= 8'b00000100;
  // 4:  Vertical Up
      20'b00001001110100101001 : decoded <= 8'b00000101;
  // 5:  Height Down
      20'b00001001110100101000 : decoded <= 8'b00000110;
  // 6:  Height Up
      20'b00001001110100101101 : decoded <= 8'b00000111;
  // 7:  Convergence Down
      20'b00001001110100101100 : decoded <= 8'b00001000;
  // 8:  Convergence Up
      20'b00001001110100010001 : decoded <= 8'b00001001;
  // 9:  Tilt left Down
      20'b00001001110100010000 : decoded <= 8'b00010000;
  // 10: Tilt right Down
      20'b00001001110100011001 : decoded <= 8'b00010001;
  // 11: Contrast Down
      20'b00001001110100011000 : decoded <= 8'b00010010;
  // 12: Contrast Up
      20'b00001001110100001101 : decoded <= 8'b00010011;
  // 13: Horizontal Left
      20'b00001001110100001100 : decoded <= 8'b00010100;
  // 14: Horizontal Right
      20'b00001001110100100111 : decoded <= 8'b00010101;
  // 15: With Left
      20'b00001001110100100110 : decoded <= 8'b00010110;
  // 16: With Right
      20'b00001001110100101011 : decoded <= 8'b00010111;
  // 17: Convergence Left
      20'b00001001110100101010 : decoded <= 8'b00011000;
  // 18: Convergence Right
      20'b00001001110100111000 : decoded <= 8'b00011001;
  // 19: Size Down
      20'b00001001110100110111 : decoded <= 8'b00100000;
  // 20: Size Up
      default : decoded <= 8'b11101110;
    endcase
  end
  // output EE-hex to mark error
  assign decoded_e = decoded[3:0];
  //one's digit
  assign decoded_z = decoded[7:4];
  //ten's digit
  // Segments 6 (lowest digit) to Segment 3 will always show the raw value, as long as sel_raw = 1
  assign seg6 = data[3:0];
  assign seg5 = data[7:4];
  assign seg4 = data[11:8];
  assign seg3 = data[15:12];
  assign seg6_en = sel_raw;
  assign seg5_en = sel_raw;
  assign seg4_en = sel_raw;
  assign seg3_en = sel_raw;
  // The separator is only shown when both modes are active together (sel_raw=sel_decoded=1)
  assign dp = sel_raw == 1'b1 && sel_decoded == 1'b1 ?  ~dclk : dclk;
  // Segment 2 has 3 different modes: 
  assign seg2 = sel_raw == 1'b1 && sel_decoded == 1'b0 ? data[19:16] : decoded_e;
  // shows the lowest digit of the decoded message, if sel_decoded is active
  assign seg2_en = sel_raw == 1'b1 || sel_decoded == 1'b1 ? 1'b1 : 1'b0;
  // only active when at least one of the two modes is selected  
  // Segment 1 (highest digit of display) will always show the ten's part of the decoded message     
  assign seg1 = sel_decoded == 1'b1 ? decoded_z : {4{1'b0}};
  assign seg1_en = sel_decoded;
endmodule

module programCounter(
input wire [9:0] D_IN,
input wire PC_OE,
input wire PC_LD,
input wire PC_INC,
input wire RST,
input wire CLK,
output wire [9:0] PC_COUNT,
output wire [9:0] PC_TRI
);
reg [9:0] pcCountSig;
  always @(posedge PC_LD, posedge PC_INC, posedge pcCountSig, posedge CLK) begin
    if((RST == 1'b1)) begin
      pcCountSig <= 10'b0000000000;
    end
    else if((PC_LD == 1'b1)) begin
      pcCountSig <= D_IN;
    end
    else if((PC_INC == 1'b1)) begin
      pcCountSig <= pcCountSig + 1;
    end
  end
  assign PC_COUNT = pcCountSig;
  assign PC_TRI = PC_OE == 1'b1 ? pcCountSig : {10{1'bZ}};
endmodule

module tcp_engine_add_data(
input wire clk,
output reg read_en,
input wire empty,
input wire [15:0] in_src_port,
input wire [31:0] in_dst_ip,
input wire [15:0] in_dst_port,
input wire [31:0] in_seq_num,
input wire [31:0] in_ack_num,
input wire [15:0] in_window,
input wire in_flag_urg,
input wire in_flag_ack,
input wire in_flag_psh,
input wire in_flag_rst,
input wire in_flag_syn,
input wire in_flag_fin,
input wire [15:0] in_urgent_ptr,
input wire [15:0] in_data_addr,
input wire [10:0] in_data_len,
output reg out_hdr_valid,
output reg [15:0] out_src_port,
output reg [31:0] out_dst_ip,
output reg [15:0] out_dst_port,
output reg [31:0] out_seq_num,
output reg [31:0] out_ack_num,
output reg [15:0] out_window,
output reg out_flag_urg,
output reg out_flag_ack,
output reg out_flag_psh,
output reg out_flag_rst,
output reg out_flag_syn,
output reg out_flag_fin,
output reg [15:0] out_urgent_ptr,
output reg out_data_valid,
output wire [7:0] out_data
);
parameter [2:0]
  waiting = 0,
  reading = 1,
  new_packet = 2,
  first_data = 3,
  adding_data = 4,
  no_data = 5;
reg [2:0] state = waiting;
reg [15:0] address = 1'b0;
reg [10:0] data_left_to_go = 1'b0;
  always @(posedge clk) begin
    read_en <= 1'b0;
    out_hdr_valid <= 1'b0;
    out_data_valid <= 1'b0;
    address <= (address) + 1;
    data_left_to_go <= data_left_to_go - 1;
    case(state)
    waiting : begin
      if(empty == 1'b0) begin
        read_en <= 1'b1;
        state <= reading;
      end
    end
    reading : begin
      state <= new_packet;
    end
    new_packet : begin
      out_src_port <= in_src_port;
      out_dst_ip <= in_dst_ip;
      out_dst_port <= in_dst_port;
      out_seq_num <= in_seq_num;
      out_ack_num <= in_ack_num;
      out_window <= in_window;
      out_flag_urg <= in_flag_urg;
      out_flag_ack <= in_flag_ack;
      out_flag_psh <= in_flag_psh;
      out_flag_rst <= in_flag_rst;
      out_flag_syn <= in_flag_syn;
      out_flag_fin <= in_flag_fin;
      out_urgent_ptr <= in_urgent_ptr;
      if((in_data_len) == 0) begin
        state <= no_data;
      end
      else begin
        state <= first_data;
        address <= in_data_addr;
        data_left_to_go <= (in_data_len) - 1;
      end
    end
    first_data : begin
      out_hdr_valid <= 1'b1;
      out_data_valid <= 1'b1;
      if(data_left_to_go == 0) begin
        state <= waiting;
      end
      else begin
        state <= adding_data;
      end
    end
    adding_data : begin
      out_data_valid <= 1'b1;
      if(data_left_to_go == 0) begin
        state <= waiting;
      end
      else begin
        state <= adding_data;
      end
    end
    no_data : begin
      out_hdr_valid <= 1'b1;
      state <= waiting;
    end
    default : begin
      state <= waiting;
    end
    endcase
  end
  tcp_engine_content_memory i_tcp_engine_content_memory(
      .clk(clk),
    .address(address),
    .data(out_data));
endmodule

module Cont_asc(
input wire clk,
input wire rst,
output wire [15:0] s
);
//a lógica de reset do contador ascendente está definida no topo contador.
reg [3:0] s0 = 4'b0000; reg [3:0] s1 = 4'b0000; reg [3:0] m0 = 4'b0000; reg [3:0] m1 = 4'b0000;  //signals definidos para receber a contagem de segundos e minutos.
  assign s = {m1,m0,s1,s0};
  //signals concatenados atribuídos a saída "s" do contador.
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b0) begin
      s0 <= 4'b0000;
      s1 <= 4'b0000;
      m0 <= 4'b0000;
      m1 <= 4'b0000;
    end else begin
      s0 <= s0 + 1'b1;
      if(s0 == 4'b1001) begin
        s0 <= 4'b0000;
        s1 <= s1 + 1;
        if(s1 == 4'b0101) begin
          s1 <= 4'b0000;
          m0 <= m0 + 1;
          if(m0 == 4'b1001) begin
            m0 <= 4'b0000;
            m1 <= m1 + 1;
            if(m1 == 4'b0101) begin
              m1 <= 4'b0000;
            end
          end
        end
      end
    end
  end
endmodule

module g05_minimum3(
input wire [2:0] N,
input wire [2:0] M,
output wire [2:0] min
);
wire AltB; wire AeqB; wire AgtB;
wire [2:0] i;
  assign i =  ~(N ^ M);
  assign AeqB = i[0] & i[1] & i[2];
  assign AgtB = (N[2] &  ~M[2]) | (N[1] &  ~M[1] & i[2]) | (N[0] &  ~M[0] & i[2] & i[1]);
  assign AltB =  ~(AeqB | AgtB);
  assign min = AltB == 1'b0 ? M : N;
endmodule

