module uart(
output wire txd_p,
input wire rxd_p,
input wire [7:0] din_p,
input wire empty_p,
output wire re_p,
output wire [7:0] dout_p,
output wire we_p,
output wire error_p,
input wire full_p,
input wire clk_en,
input wire clk
);
//-----------------------------------------------------------------------------
wire busy = 1'b0;
reg clk_tx_en = 1'b0;
  // 1/5 clock divider for generating the transmission clock
  always @(posedge clk) begin : P1
    reg [31:0] counter = 0;
    if(clk_en == 1'b1) begin
      counter = counter + 1;
      if(counter == 5) begin
        counter = 0;
        clk_tx_en <= 1'b1;
      end
    end
    else begin
      clk_tx_en <= 1'b0;
    end
  end
  // Receiver
  uart_rx rx(
      .rxd_p(rxd_p),
    .disable_p(busy),
    .data_p(dout_p),
    .we_p(we_p),
    .error_p(error_p),
    .full_p(full_p),
    .clk_rx_en(clk_en),
    .clk(clk));
  // Transmitter
  uart_tx tx(
      .txd_p(txd_p),
    .busy_p(busy),
    .data_p(din_p),
    .empty_p(empty_p),
    .re_p(re_p),
    .clk_tx_en(clk_tx_en),
    .clk(clk));
endmodule

