module rgb565_to_rgb888(
input wire clk,
input wire [15:0] rgb_565,
output reg [23:0] rgb_888
);
wire [7:0] red = 8'b00000000; wire [7:0] green = 8'b00000000; wire [7:0] blue = 8'b00000000;
  assign red[4:0] = rgb_565[15:11];
  assign green[5:0] = rgb_565[10:5];
  assign blue[4:0] = rgb_565[4:0];
  always @(posedge clk) begin : P1
    reg [7:0] r_1, r_2, g_1, g_2, b_1, b_2;
    r_1 = (red) << 3;
    r_2 = (red) >> 2;
    g_1 = (green) << 2;
    g_2 = (green) >> 4;
    b_1 = (blue) << 3;
    b_2 = (blue) << 2;
    rgb_888[23:16] <= r_1 | r_2;
    rgb_888[15:8] <= g_1 | g_2;
    rgb_888[7:0] <= b_1 | b_1;
  end
endmodule

