module fg_tb_synth(
input wire CLK,
input wire RESET,
output wire SIM_DONE,
output wire [7:0] STATUS
);
parameter [31:0] FREEZEON_ERROR=0;
parameter [31:0] TB_STOP_CNT=0;
parameter [31:0] TB_SEED=1;
// FIFO interface signal declarations
wire clk_i;
wire rst;
wire prog_full;
wire wr_en;
wire rd_en;
wire [64 - 1:0] din;
wire [64 - 1:0] dout;
wire full;
wire empty;  // TB Signals
wire [64 - 1:0] wr_data;
wire [64 - 1:0] dout_i;
wire wr_en_i = 1'b0;
wire rd_en_i = 1'b0;
wire full_i = 1'b0;
wire empty_i = 1'b0;
wire almost_full_i = 1'b0;
wire almost_empty_i = 1'b0;
wire prc_we_i = 1'b0;
wire prc_re_i = 1'b0;
wire dout_chk_i = 1'b0;
wire rst_int_rd = 1'b0;
wire rst_int_wr = 1'b0;
wire rst_s_wr3 = 1'b0;
wire rst_s_rd = 1'b0;
wire reset_en = 1'b0;
reg rst_async_rd1 = 1'b0;
reg rst_async_rd2 = 1'b0;
reg rst_async_rd3 = 1'b0;
  //-- Reset generation logic -----
  assign rst_int_wr = rst_async_rd3 | rst_s_rd;
  assign rst_int_rd = rst_async_rd3 | rst_s_rd;
  //Testbench reset synchronization
  always @(posedge clk_i, posedge RESET) begin
    if((RESET == 1'b1)) begin
      rst_async_rd1 <= 1'b1;
      rst_async_rd2 <= 1'b1;
      rst_async_rd3 <= 1'b1;
