module PSR_MOD(
input wire [31:0] alurs,
input wire ope1,
input wire ope2,
input wire [5:0] aluop,
output reg [3:0] nzvc
);
  always @(alurs, ope1, ope2, aluop) begin
    //ADDcc ADDXcc
    if((aluop == 6'b100001 || aluop == 6'b100011)) begin
      nzvc[3] <= alurs[31];
      if((alurs == 32'h00000000)) begin
        nzvc[2] <= 1'b1;
      end
      else begin
        nzvc[2] <= 1'b0;
      end
      nzvc[1] <= (ope1 & ope2 & ( ~alurs[31])) | ((ope1) & ( ~ope2) & alurs[31]);
      nzvc[0] <= (ope1 & ope2) | (( ~alurs[31]) & (ope1 | ope2));
      //SUBcc SUBXcc 
    end
    else if((aluop == 6'b100101 || aluop == 6'b100111)) begin
      nzvc[3] <= alurs[31];
      if((alurs == 32'h00000000)) begin
        nzvc[2] <= 1'b1;
      end
      else begin
        nzvc[2] <= 1'b0;
      end
      nzvc[1] <= (ope1 & ( ~ope2) & ( ~alurs[31])) | (( ~ope1) & ope2 & alurs[31]);
      nzvc[0] <= (( ~ope1) & ope2) | (alurs[31] & (( ~ope1) | ope2));
      //ANDcc ANDNcc ORcc ORNcc XORcc XNORcc
    end
    else if((aluop == 6'b101001 || aluop == 6'b101011 || aluop == 6'b101101 || aluop == 6'b101111 || aluop == 6'b110001 || aluop == 6'b110011)) begin
      nzvc[3] <= alurs[31];
      if((alurs == 32'h00000000)) begin
        nzvc[2] <= 1'b1;
      end
      else begin
        nzvc[2] <= 1'b0;
      end
      nzvc[1] <= 1'b0;
      nzvc[0] <= 1'b0;
      //		--RESTO DE OPERACIONES
      //		else
      //				nzvc <= "0000";
    end
  end
endmodule

