input wire [32 - 1:0] t1_data_in,
input wire t1_load_in,
input wire [0:0] t1_opcode_in,
output wire [32 - 1:0] r1_data_out
);
// External signals
// Architectural ports
parameter OPC_GET_READ_IDX_LOW = 1'b0;
parameter OPC_INC_READ_IDX = 1'b1;
reg [64 - 1:0] read_idx_r;
reg [32 - 1:0] result_r;
  assign read_idx_out = read_idx_r;
  assign r1_data_out = result_r;
  always @(posedge clk, posedge rstx) begin
    if(rstx == 1'b0) begin
      read_idx_r <= {((64 - 1)-(0)+1){1'b0}};
      result_r <= {((32 - 1)-(0)+1){1'b0}};
    end else begin
      if(read_idx_clear_in == 1'b1) begin
        read_idx_r <= {((64 - 1)-(0)+1){1'b0}};
      end
      if(glock == 1'b0) begin
        if(t1_load_in == 1'b1) begin
          case(t1_opcode_in)
          OPC_GET_READ_IDX_LOW : begin
            result_r <= read_idx_r[32 - 1:0];
          end
          default : begin
            // Increment
            read_idx_r <= (read_idx_r) + (t1_data_in);
          end
          endcase
        end
      end
    end
  end
