module ALU_Toplevel(
input wire [15:0] RA,
input wire [15:0] RB,
input wire [3:0] OP,
input wire CLK,
input wire RST,
output reg [15:0] ALU_OUT,
output wire [3:0] SREG,
output wire [15:0] LDST_DAT,
output wire [15:0] LDST_ADR,
output reg BRANCH
);
wire [15:0] ARITH = 1'b0;
wire [3:0] SREG_AR = 1'b0;
wire [15:0] LOGIC = 1'b0;
wire [3:0] SREG_LG = 1'b0;
wire [15:0] SHIFT = 1'b0;
wire [3:0] SREG_SH = 1'b0;
wire [15:0] LD_MEM = 1'b0;
wire [15:0] WORD_OUT = 1'b0;
wire [7:0] LDST_ADR_8 = 1'b0;
wire BR = 1'b0;
reg [3:0] CCR = 1'b0;
wire [3:0] LATCHEDCCR = 1'b0;
  assign LDST_ADR = {8'h00,LDST_ADR_8};
  arith_unit arith_unit(
      .RA(RA),
    .RB(RB),
    .OP(OP[2:0]),
    .AR_OUT(ARITH),
    .SREG_OUT(SREG_AR));
  logical_unit logical_unit(
      .RA(RA),
    .RB(RB),
    .OP(OP[2:0]),
    .LOG_OUT(LOGIC),
    .SREG_OUT(SREG_LG));
  shift_unit shift_unit(
      .RA(RA),
    .SHIFT(RB[7:0]),
    .OP(OP[3]),
    .SHIFT_OUT(SHIFT),
    .SREG_OUT(SREG_SH));
  word_unit word_unit(
      .DATAIN(RA),
    .IMMAddr(RB[7:0]),
    .CLK(CLK),
    .OP(OP),
    .RESULT(WORD_OUT),
    .DST_ADR(LDST_ADR_8),
    .STORE_DATA(LDST_DAT));
  jump_unit jump_unit(
      .CLK(CLK),
    .OP(OP),
    .CCR(LATCHEDCCR),
    .MASK(RA[3:0]),
    .IMMD(RB),
    .BRSIG(BR));
  PipelineRegisters #(
      .dataWidth(4))
  CCR_Latch(
      .Clk(CLK),
    .Ena(1'b1),
    .Rst(RST),
    .Din(CCR),
    .Dout(LATCHEDCCR));
  always @(*) begin
    case(OP)
      4'b0000 : ALU_OUT <= ARITH;
  // ADD (ARITHMETIC)
      4'b0001 : ALU_OUT <= ARITH;
  // SUB (ARITHMETIC)
      4'b0010 : ALU_OUT <= LOGIC;
  // AND (LOGICAL)
      4'b0011 : ALU_OUT <= LOGIC;
  // OR  (LOGICAL)
      4'b0100 : ALU_OUT <= LOGIC;
  // MOV (LOGICAL)
      4'b0101 : ALU_OUT <= ARITH;
  // ADDI (ARITHMETIC)
      4'b0110 : ALU_OUT <= LOGIC;
  // ANDI (LOGICAL)
      4'b0111 : ALU_OUT <= SHIFT;
  // SL (SHIFT)
      4'b1000 : ALU_OUT <= SHIFT;
  // SR (SHIFT)
      4'b1001 : ALU_OUT <= WORD_OUT;
  // LW (WORD)
      4'b1010 : ALU_OUT <= RA;
  // SW (WORD)
      default : ALU_OUT <= 16'h0000;
    endcase
  end
  always @(*) begin
    case(OP)
      4'b0000 : CCR <= SREG_AR;
  // ADD (ARITHMETIC)
      4'b0001 : CCR <= SREG_AR;
  // SUB (ARITHMETIC)
      4'b0010 : CCR <= SREG_LG;
  // AND (LOGICAL)
      4'b0011 : CCR <= SREG_LG;
  // OR  (LOGICAL)
      4'b0100 : CCR <= SREG_LG;
  // MOV (LOGICAL)
      4'b0101 : CCR <= SREG_AR;
  // ADDI (ARITHMETIC)
      4'b0110 : CCR <= SREG_LG;
  // ANDI (LOGICAL)
      4'b0111 : CCR <= SREG_SH;
  // SL (SHIFT)
      4'b1000 : CCR <= SREG_SH;
  // SR (SHIFT)
      default : CCR <= 4'h0;
    endcase
  end
  always @(*) begin
    case(OP)
      4'b1111 : BRANCH <= BR;
      default : BRANCH <= 1'b0;
    endcase
  end
  assign SREG = CCR;
endmodule

