module TCAM_Cell(
input wire clk,
input wire rst,
input wire we,
input wire cell_search_bit,
input wire cell_dont_care_bit,
input wire cell_match_bit_in,
output reg cell_match_bit_out
);
reg FF;
  always @(clk, rst, we, cell_search_bit, cell_dont_care_bit, cell_match_bit_in) begin
    //reset data most important
    if(rst == 1'b1) begin
      FF <= 1'b0;
      cell_match_bit_out <= 1'b0;
      // write data from search 
    end
    else if(we == 1'b1) begin
      FF <= cell_search_bit;
      cell_match_bit_out <= 1'b0;
      //search
      //previous result is wrong therefore nothing matches
    end
    else if(cell_match_bit_in == 1'b0) begin
      cell_match_bit_out <= 1'b0;
      //previous result matches
    end
    else if(cell_match_bit_in == 1'b1) begin
      //check if search input is dont care
      if(cell_dont_care_bit == 1'b1) begin
        cell_match_bit_out <= 1'b1;
        //if search is not a dont care
      end
      else begin
        //check current cell if match
        if(FF == cell_search_bit) begin
          cell_match_bit_out <= 1'b1;
        end
        else begin
          //current cell doesnt match 
          cell_match_bit_out <= 1'b0;
        end
      end
    end
  end
endmodule

