module divider(
input wire fclk,
output reg fclkn
);
parameter [31:0] n=400;
// generic parameter to specify the factor
// input clock
// output clock
reg [15:0] counter = 1'b0;  // counter signal which acts as temporary storage
  // purpose : produces an output frequency with 50% duty cycle by dividing the input frequency
  // type    : sequential (on fclk)
  // inputs  : fclk
  // outputs : fclkn
  always @(posedge fclk) begin
    // when fclk rises
    if((counter < ((n / 2) - 1))) begin
      // as long as the counter is smaller than half the division factor
      counter <= counter + 1;
      // increment counter
      fclkn <= 1'b0;
      // set output to zero
    end
    else if((counter < (n - 1))) begin
      // as long as the counter is smaller the full division factor
      counter <= counter + 1;
      // increment counter
      fclkn <= 1'b1;
      // set the output
    end
    else begin
      fclkn <= 1'b0;
      // reset the output
      counter <= {16{1'b0}};
      // set the counter to 0
    end
  end
endmodule

