module led_display(
input wire i_clk,
input wire i_srst,
input wire [6:0] i_db_addr,
input wire [7:0] i_db_wdata,
output reg [7:0] o_db_rdata,
input wire i_db_rstrb,
input wire i_db_wstrb,
output wire [7:0] o_led
);
parameter [31:0] led_reg_addr=0;
// address for the led display module to use
// Databus signals ------------------
// LED output -----------------------
// signals
reg [7:0] led_reg;
wire [6:0] led_reg_addr_stl;
  // output tie to local signal register.
  assign o_led = led_reg;
  assign led_reg_addr_stl = led_reg_addr;
  // update led_reg depending on databus activity.
  always @(posedge i_clk) begin
    if((i_srst == 1'b1)) begin
      // reset state
      led_reg <= {8{1'b0}};
    end
    else begin
      // write have priority over reads here..
      if((i_db_wstrb == 1'b1)) begin
        if((i_db_addr == led_reg_addr_stl)) begin
          led_reg <= i_db_wdata;
        end
      end
      else begin
        if((i_db_rstrb == 1'b1)) begin
          if((i_db_addr == led_reg_addr_stl)) begin
            o_db_rdata <= led_reg;
          end
          else begin
            o_db_rdata <= {8{1'bZ}};
            // we are not address, don't drive bus..
          end
        end
        else begin
          // do not drive shared rdata line if we are not addressed to output anything
          o_db_rdata <= {8{1'bZ}};
        end
        // end db_rstrb
      end
      // end db_wstrb
    end
    // end not in reset
  end
endmodule

module ALU(
input wire [7:0] s_muxa,
input wire [7:0] s_muxb,
input wire [3:0] ctrl_alu,
output wire [7:0] s_alu,
output wire [2:0] flags
);
reg [15:0] result;
wire [15:0] A; wire [15:0] B;
  assign A = {8'b00000000,s_muxa};
  assign B = {8'b00000000,s_muxb};
  always @(*) begin
    case(ctrl_alu)
      4'b0000 : result <= B;
      4'b0001 : result <= A + B;
      4'b0010 : result <= A - B;
      4'b0011 : result <= (s_muxa) * (s_muxb);
      4'b0100 : result <= A / B;
      4'b0101 : result <= A & B;
      4'b0110 : result <= A | B;
      4'b0111 : result <=  ~A;
      4'b1000 : result <= A >> 1;
      4'b1001 : result <= A << 1;
      4'b1010 : result <= A + 1;
      4'b1011 : result <= A - 1;
      default : result <= 16'bXXXXXXXXXXXXXXXX;
    endcase
  end
  assign s_alu = result[7:0];
  assign flags = ((result[7:0]) == 8'b00000000) ? 3'b001 : (result[7] == 1'b1) ? 3'b010 : 3'b100;
endmodule

