module EX(
input wire clock,
input wire reset,
input wire [31:0] ALUA_from_ID,
input wire [31:0] ALUB_from_ID,
input wire [11:0] cntl_from_ID,
input wire p_flag_from_MEM,
output wire [31:0] ALUR_to_MEM,
output wire [4:0] dest_reg_addr_to_ID,
output wire cond_bit_to_IF
);
////Components\\--
//The Arithmetic and Logic Unit
//The condition block, which holds all of the flags generated by the
//ALU and sends the selected flag to the IF stage
//Generic rising-edge-triggered register
//\\Components//--
////Signals\\--
wire [31:0] ALUA_reg_out;  //Output of the stage's input registers
wire [31:0] ALUB_reg_out;
wire [3:0] ALU_flags;  //Carries the flags generated by the ALU
wire [11:0] cntl_reg_out;  //This is the output of the 1-stage buffer that delays the
//control signals coming from the decoder
wire [4:0] flags_to_CB;  //Carries all of the flags to the condition block, including
//the pin flag from MEMIO
//\\Signals//--
  //ALU instantiation
  ALU ALU_inst(
      .A(ALUA_reg_out),
    .B(ALUB_reg_out),
    .sel(cntl_reg_out[3:0]),
    .result(ALUR_to_MEM),
    .flags(ALU_flags));
  //Condition Block instantiation
  ConditionBlock cond_block(
      .clock(clock),
    .reset(reset),
    .sel(cntl_reg_out[6:4]),
    .flags(flags_to_CB),
    .cond_out(cond_bit_to_IF));
  //Input register A instantiation
  GenReg #(
      .size(32))
  ALUA_reg(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(ALUA_from_ID),
    .output(ALUA_reg_out));
  //Input register B instantiation
  GenReg #(
      .size(32))
  ALUB_reg(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(ALUB_from_ID),
    .output(ALUB_reg_out));
  //Control signal buffer register 1 instantiation
  GenReg #(
      .size(12))
  Cntl_reg(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(cntl_from_ID),
    .output(cntl_reg_out));
  assign flags_to_CB = {p_flag_from_MEM,ALU_flags};
  //Adding the pin flag to the ALU flags
  assign dest_reg_addr_to_ID = cntl_reg_out[11:7];
    //Sending the instruction's result register back to ID for
//forwarding logic
endmodule

