    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
    end
    else begin
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {14{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  memoria_exdes BMG_PORT(
      //Port A
    .ADDRA(ADDRA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

