module rs232_sender(
output wire ack_o,
input wire clk_i,
input wire [7:0] dat_i,
input wire rst_i,
input wire stb_i,
output reg tx
);
parameter [31:0] system_speed;
baudrate;
// baudrate, in bps
// Wishbone ACK_O signal
// Wishbone CLK_i signal
// Wishbone DAT_i signal
// Wishbone RST_i signal
// Wishbone STB_i signal
// RS232 transmit pin
parameter max_counter = system_speed / baudrate;
parameter [1:0]
  wait_for_strobe = 0,
  send_start_bit = 1,
  send_bits = 2,
  send_stop_bit = 3;
reg [1:0] state = wait_for_strobe;
reg [31:0] baudrate_counter = 0;
reg [31:0] bit_counter = 0;
reg [7:0] shift_register = 1'b0;
reg data_sending_started = 1'b0;
  // acknowledge, when sending process was started
  assign ack_o = data_sending_started & stb_i;
  always @(posedge clk_i) begin
    if(rst_i == 1'b1) begin
      tx <= 1'b1;
      data_sending_started <= 1'b0;
      state <= wait_for_strobe;
    end
    else begin
      case(state)
            // wait until the master asserts valid data
      wait_for_strobe : begin
        if(stb_i == 1'b1) begin
          state <= send_start_bit;
          baudrate_counter <= max_counter - 1;
          tx <= 1'b0;
          shift_register <= dat_i;
          data_sending_started <= 1'b1;
        end
        else begin
          tx <= 1'b1;
        end
      end
      send_start_bit : begin
        if(baudrate_counter == 0) begin
          state <= send_bits;
          baudrate_counter <= max_counter - 1;
          tx <= shift_register[0];
          bit_counter <= 7;
        end
        else begin
          baudrate_counter <= baudrate_counter - 1;
        end
      end
      send_bits : begin
        if(baudrate_counter == 0) begin
          if(bit_counter == 0) begin
            state <= send_stop_bit;
            tx <= 1'b1;
          end
          else begin
            tx <= shift_register[1];
            shift_register <= shift_register >> 1;
            bit_counter <= bit_counter - 1;
          end
          baudrate_counter <= max_counter - 1;
        end
        else begin
          baudrate_counter <= baudrate_counter - 1;
        end
      end
      send_stop_bit : begin
        if(baudrate_counter == 0) begin
          state <= wait_for_strobe;
        end
        else begin
          baudrate_counter <= baudrate_counter - 1;
        end
      end
      endcase
      // this resets acknowledge until all bits are sent
      if(stb_i == 1'b0 && data_sending_started == 1'b1) begin
        data_sending_started <= 1'b0;
      end
    end
  end
endmodule

